def _capture_eager_class_callable_codes(
    namespace: MappingProxyType,
) -> tuple[tuple[str, str, object, FunctionType, CodeType], ...]:
    entries: list[tuple[str, str, object, FunctionType, CodeType]] = []
    for name, value in tuple(namespace.items()):
        if type(value) is FunctionType:
            entries.append(
                (
                    name,
                    "direct",
                    value,
                    value,
                    object.__getattribute__(value, "__code__"),
                )
            )
            continue
        if type(value) is property:
            for accessor in ("fget", "fset", "fdel"):
                function = getattr(value, accessor)
                if type(function) is FunctionType:
                    entries.append(
                        (
                            name,
                            accessor,
                            value,
                            function,
                            object.__getattribute__(function, "__code__"),
                        )
                    )
    return tuple(entries)


