def _capture_deterministic_prefix_modules() -> tuple[Path, tuple[tuple[str, ModuleType], ...]]:
    """Freeze prefix bindings after this module's own imports are complete."""

    prefix = Path(sys.prefix).resolve(strict=True)
    selected: list[tuple[str, ModuleType]] = []
    for name, module in tuple(sys.modules.items()):
        if type(module) is not ModuleType:
            continue
        module_file = getattr(module, "__file__", None)
        if isinstance(module_file, str):
            try:
                Path(module_file).resolve(strict=True).relative_to(prefix)
            except (OSError, ValueError):
                pass
            else:
                selected.append((name, module))
                continue
        locations = getattr(
            getattr(module, "__spec__", None),
            "submodule_search_locations",
            None,
        )
        if not locations:
            continue
        for raw_location in locations:
            try:
                Path(raw_location).resolve(strict=True).relative_to(prefix)
            except (OSError, ValueError):
                continue
            selected.append((name, module))
            break
    selected.sort(key=lambda item: item[0])
    return prefix, tuple(selected)


(
    _DETERMINISTIC_IMPORT_PREFIX,
    _PREFIX_MODULES_AFTER_DETERMINISTIC_IMPORTS,
) = _capture_deterministic_prefix_modules()


def _capture_deterministic_module_metadata(module: ModuleType) -> tuple[
    ModuleType,
    object,
    object,
    object,
    object,
    object,
    object,
]:
    if type(module) is not ModuleType:
        return (module, None, None, None, None, None, ())
    namespace = vars(module)
    specification = namespace.get("__spec__")
    specification_namespace = (
        vars(specification) if type(specification) is ModuleSpec else {}
    )
    return (
        module,
        namespace.get("__name__"),
        namespace.get("__file__"),
        specification,
        specification_namespace.get("origin"),
        specification_namespace.get("loader"),
        specification_namespace.get("submodule_search_locations"),
    )


_MODULE_OBJECTS_AFTER_DETERMINISTIC_IMPORTS = MappingProxyType(
    {
        name: _capture_deterministic_module_metadata(module)
        for name, module in _PREFIX_MODULES_AFTER_DETERMINISTIC_IMPORTS
    }
)
