def _eager_scalar_sha256(value: object) -> str | None:
    if value is None:
        payload: object = ["NoneType"]
    elif type(value) is bool:
        payload = ["bool", value]
    elif type(value) is int:
        payload = ["int", str(value)]
    elif type(value) is float:
        payload = ["float", value.hex()]
    elif type(value) is complex:
        payload = ["complex", value.real.hex(), value.imag.hex()]
    elif type(value) is str:
        payload = ["str", value]
    elif type(value) is bytes:
        payload = ["bytes", value.hex()]
    else:
        return None
    encoded = json.dumps(
        payload,
        ensure_ascii=True,
        allow_nan=False,
        separators=(",", ":"),
    ).encode("ascii")
    return hashlib.sha256(encoded).hexdigest()


_RAW_MODULE_NAMESPACES_AFTER_DETERMINISTIC_IMPORTS = MappingProxyType(
    {
        name: (
            module,
            tuple(
                (attribute, value, _eager_scalar_sha256(value))
                for attribute, value in sorted(vars(module).items())
            ),
        )
        for name, module in tuple(sys.modules.items())
        if type(module) is ModuleType
    }
)
