def _capture_exact_source_record_layout(
    global_name: str,
    record_type: type[object],
) -> tuple[
    str,
    type[object],
    tuple[str, ...],
    tuple[tuple[str, MemberDescriptorType], ...],
]:
    namespace = type.__getattribute__(record_type, "__dict__")
    slots = namespace.get("__slots__")
    member_get = vars(MemberDescriptorType).get("__get__")
    if (
        type(global_name) is not str
        or type(record_type) is not type
        or type(namespace) is not MappingProxyType
        or type(slots) is not tuple
        or not slots
        or not all(type(name) is str and name for name in slots)
        or type(member_get) is not WrapperDescriptorType
    ):
        raise MutationToolchainError("source policy record layout is invalid")
    descriptors: list[tuple[str, MemberDescriptorType]] = []
    for name in slots:
        descriptor = namespace.get(name)
        if (
            type(descriptor) is not MemberDescriptorType
            or object.__getattribute__(descriptor, "__objclass__")
            is not record_type
            or type(object.__getattribute__(descriptor, "__name__")) is not str
            or not str.__eq__(
                object.__getattribute__(descriptor, "__name__"),
                name,
            )
        ):
            raise MutationToolchainError(
                "source policy record descriptor is invalid"
            )
        descriptors.append((name, descriptor))
    return global_name, record_type, slots, tuple(descriptors)


_EXACT_SOURCE_RECORD_LAYOUTS = tuple(
    _capture_exact_source_record_layout(global_name, record_type)
    for global_name, record_type in (
        ("_SourceCodePolicy", _SourceCodePolicy),
        ("_SourceExpression", _SourceExpression),
        ("_SourceParameterDefault", _SourceParameterDefault),
        ("_SourceDecoratorCall", _SourceDecoratorCall),
        ("_SourceFunctionSemantics", _SourceFunctionSemantics),
        ("_SourceExpressionGuard", _SourceExpressionGuard),
        ("_SourceBindingCandidate", _SourceBindingCandidate),
        ("_SourceBinding", _SourceBinding),
        ("_SourceImportCandidate", _SourceImportCandidate),
        ("_SourceImportBinding", _SourceImportBinding),
        ("_SourceValueCandidate", _SourceValueCandidate),
        ("_SourceModuleDataBinding", _SourceModuleDataBinding),
        ("_SourceVersionGuard", _SourceVersionGuard),
        ("_SourceVersionPrefixGuard", _SourceVersionPrefixGuard),
        ("_SourceVersionRangeGuard", _SourceVersionRangeGuard),
        ("_SourcePytestVersionGuard", _SourcePytestVersionGuard),
        ("_SourcePlatformGuard", _SourcePlatformGuard),
        ("_SourceTypeCheckingGuard", _SourceTypeCheckingGuard),
        ("_SourceReviewedTryGuard", _SourceReviewedTryGuard),
    )
)
_EXACT_SOURCE_RECORD_MEMBER_GET = vars(MemberDescriptorType).get("__get__")
_EXACT_SOURCE_RECORD_MAPPING_GET = vars(MappingProxyType).get("get")
_EXACT_SOURCE_RECORD_NAMESPACE = globals()
_EAGER_SOURCE_TYPE_CHECKING_MODULE = sys.modules.get("typing")
if (
    type(_EAGER_SOURCE_TYPE_CHECKING_MODULE) is not ModuleType
    or dict.get(
        vars(_EAGER_SOURCE_TYPE_CHECKING_MODULE),
        "TYPE_CHECKING",
    )
    is not False
):
    raise RuntimeError("exact typing.TYPE_CHECKING provider is unavailable")


def _exact_source_record_field(
    record: object,
    field_name: str,
    _layouts: tuple[tuple[object, ...], ...] = _EXACT_SOURCE_RECORD_LAYOUTS,
    _member_get: WrapperDescriptorType = _EXACT_SOURCE_RECORD_MEMBER_GET,
    _mapping_get: MethodDescriptorType = _EXACT_SOURCE_RECORD_MAPPING_GET,
    _module_namespace: dict[str, object] = _EXACT_SOURCE_RECORD_NAMESPACE,
    _builtin_vars: BuiltinFunctionType = vars,
) -> object:
    """Read sealed source metadata without invoking replaced descriptors."""

    if (
        dict.get(_module_namespace, "_EXACT_SOURCE_RECORD_LAYOUTS")
        is not _layouts
        or dict.get(_module_namespace, "_EXACT_SOURCE_RECORD_MEMBER_GET")
        is not _member_get
        or dict.get(_module_namespace, "_EXACT_SOURCE_RECORD_MAPPING_GET")
        is not _mapping_get
        or dict.get(_module_namespace, "_EXACT_SOURCE_RECORD_NAMESPACE")
        is not _module_namespace
        or vars is not _builtin_vars
        or _builtin_vars(MemberDescriptorType).get("__get__") is not _member_get
        or _builtin_vars(MappingProxyType).get("get") is not _mapping_get
        or type(_layouts) is not tuple
        or type(field_name) is not str
    ):
        raise MutationToolchainError("source policy record reader changed")
    selected: tuple[object, ...] | None = None
    for entry in _layouts:
        if type(entry) is not tuple or tuple.__len__(entry) != 4:
            raise MutationToolchainError("source policy record layout changed")
        if type(record) is tuple.__getitem__(entry, 1):
            selected = entry
            break
    if selected is None:
        raise MutationToolchainError("source policy record type changed")
    global_name, record_type, slots, descriptors = selected
    if (
        type(global_name) is not str
        or type(record_type) is not type
        or dict.get(_module_namespace, global_name) is not record_type
        or type(slots) is not tuple
        or type(descriptors) is not tuple
    ):
        raise MutationToolchainError("source policy record type changed")
    namespace = type.__getattribute__(record_type, "__dict__")
    if (
        type(namespace) is not MappingProxyType
        or _mapping_get(namespace, "__slots__") is not slots
    ):
        raise MutationToolchainError("source policy record layout changed")
    selected_descriptor: MemberDescriptorType | None = None
    for descriptor_entry in descriptors:
        if (
            type(descriptor_entry) is not tuple
            or tuple.__len__(descriptor_entry) != 2
        ):
            raise MutationToolchainError(
                "source policy record descriptor changed"
            )
        descriptor_name = tuple.__getitem__(descriptor_entry, 0)
        descriptor = tuple.__getitem__(descriptor_entry, 1)
        if (
            type(descriptor_name) is not str
            or type(descriptor) is not MemberDescriptorType
            or _mapping_get(namespace, descriptor_name) is not descriptor
        ):
            raise MutationToolchainError(
                "source policy record descriptor changed"
            )
        if str.__eq__(descriptor_name, field_name):
            selected_descriptor = descriptor
    if selected_descriptor is None:
        raise MutationToolchainError("source policy record field changed")
    return _member_get(selected_descriptor, record, record_type)


