def _capture_hypothesis_entropy_random_method_fingerprints(
    random_module: ModuleType,
    random_class: type[object],
    *,
    _function_type: type[FunctionType] = FunctionType,
    _code_type: type[CodeType] = CodeType,
    _cell_type: type[CellType] = CellType,
    _mapping_proxy_type: type[MappingProxyType] = MappingProxyType,
    _builtin_vars: BuiltinFunctionType = vars,
) -> tuple[tuple[object, ...], ...]:
    if (
        FunctionType is not _function_type
        or CodeType is not _code_type
        or CellType is not _cell_type
        or MappingProxyType is not _mapping_proxy_type
        or vars is not _builtin_vars
        or type(random_module) is not ModuleType
        or type(random_class) is not type
    ):
        raise MutationToolchainError(
            "Hypothesis entropy random method fingerprint controls changed"
        )
    module_namespace = _builtin_vars(random_module)
    class_namespace = type.__getattribute__(random_class, "__dict__")
    if (
        type(module_namespace) is not dict
        or type(class_namespace) is not _mapping_proxy_type
    ):
        raise MutationToolchainError(
            "Hypothesis entropy random method provider changed"
        )
    fingerprints: list[tuple[object, ...]] = []
    for method_name in ("seed", "getstate", "setstate"):
        method = class_namespace.get(method_name)
        if type(method) is not _function_type:
            raise MutationToolchainError(
                "Hypothesis entropy random method provider changed"
            )
        code = object.__getattribute__(method, "__code__")
        globals_namespace = object.__getattribute__(method, "__globals__")
        defaults = object.__getattribute__(method, "__defaults__")
        kwdefaults = object.__getattribute__(method, "__kwdefaults__")
        closure = object.__getattribute__(method, "__closure__")
        method_namespace = object.__getattribute__(method, "__dict__")
        annotate = (
            object.__getattribute__(method, "__annotate__")
            if "__annotate__" in _builtin_vars(_function_type)
            else None
        )
        annotations = (
            object.__getattribute__(method, "__annotations__")
            if annotate is None
            else None
        )
        module_value = object.__getattribute__(method, "__module__")
        name_value = object.__getattribute__(method, "__name__")
        qualname_value = object.__getattribute__(method, "__qualname__")
        doc_value = object.__getattribute__(method, "__doc__")
        if (
            type(code) is not _code_type
            or globals_namespace is not module_namespace
            or (
                str.__eq__(method_name, "seed")
                and (
                    type(defaults) is not tuple
                    or tuple.__len__(defaults) != 2
                    or tuple.__getitem__(defaults, 0) is not None
                    or type(tuple.__getitem__(defaults, 1)) is not int
                    or not int.__eq__(tuple.__getitem__(defaults, 1), 2)
                )
            )
            or (
                not str.__eq__(method_name, "seed")
                and defaults is not None
            )
            or kwdefaults is not None
            or type(closure) is not tuple
            or tuple.__len__(closure) != 1
            or type(tuple.__getitem__(closure, 0)) is not _cell_type
            or tuple.__getitem__(closure, 0).cell_contents is not random_class
            or type(method_namespace) is not dict
            or dict.__len__(method_namespace) != 0
            or type(annotations) is not dict
            or dict.__len__(annotations) != 0
            or annotate is not None
            or type(module_value) is not str
            or not str.__eq__(module_value, "random")
            or type(name_value) is not str
            or not str.__eq__(name_value, method_name)
            or type(qualname_value) is not str
            or not str.__eq__(qualname_value, f"Random.{method_name}")
            or (doc_value is not None and type(doc_value) is not str)
        ):
            raise MutationToolchainError(
                "Hypothesis entropy random method state changed"
            )
        fingerprints.append(
            (
                method_name,
                method,
                code,
                globals_namespace,
                defaults,
                kwdefaults,
                closure,
                (tuple.__getitem__(closure, 0).cell_contents,),
                method_namespace,
                tuple(dict.items(method_namespace)),
                annotations,
                annotate,
                module_value,
                name_value,
                qualname_value,
                doc_value,
            )
        )
    return tuple(fingerprints)


def _hypothesis_entropy_method_fingerprints_are_identical(
    current: tuple[tuple[object, ...], ...],
    expected: tuple[tuple[object, ...], ...],
) -> bool:
    if (
        type(current) is not tuple
        or type(expected) is not tuple
        or tuple.__len__(current) != 3
        or tuple.__len__(expected) != 3
    ):
        return False
    for current_entry, expected_entry in zip(
        current,
        expected,
        strict=True,
    ):
        if (
            type(current_entry) is not tuple
            or type(expected_entry) is not tuple
            or tuple.__len__(current_entry) != 16
            or tuple.__len__(expected_entry) != 16
        ):
            return False
        for index in (0, 12, 13, 14):
            current_value = tuple.__getitem__(current_entry, index)
            expected_value = tuple.__getitem__(expected_entry, index)
            if (
                type(current_value) is not str
                or type(expected_value) is not str
                or not str.__eq__(current_value, expected_value)
            ):
                return False
        for index in (1, 2, 3, 4, 5, 6, 8, 10, 11, 15):
            if tuple.__getitem__(current_entry, index) is not tuple.__getitem__(
                expected_entry,
                index,
            ):
                return False
        for index in (7, 9):
            current_values = tuple.__getitem__(current_entry, index)
            expected_values = tuple.__getitem__(expected_entry, index)
            if (
                type(current_values) is not tuple
                or type(expected_values) is not tuple
                or tuple.__len__(current_values)
                != tuple.__len__(expected_values)
            ):
                return False
            for current_value, expected_value in zip(
                current_values,
                expected_values,
                strict=True,
            ):
                if index == 7:
                    if current_value is not expected_value:
                        return False
                elif (
                    type(current_value) is not tuple
                    or type(expected_value) is not tuple
                    or tuple.__len__(current_value) != 2
                    or tuple.__len__(expected_value) != 2
                    or type(tuple.__getitem__(current_value, 0)) is not str
                    or type(tuple.__getitem__(expected_value, 0)) is not str
                    or not str.__eq__(
                        tuple.__getitem__(current_value, 0),
                        tuple.__getitem__(expected_value, 0),
                    )
                    or tuple.__getitem__(current_value, 1)
                    is not tuple.__getitem__(expected_value, 1)
                ):
                    return False
    return True


