def _exact_bootstrap_global_entry(
    mapping: dict[str, object],
    name: str,
    value: object,
) -> tuple[str, object]:
    if type(mapping) is not dict or type(name) is not str:
        raise RuntimeError("sealed source dependency binding is unavailable")
    matches = tuple(
        (key, current)
        for key, current in dict.items(mapping)
        if type(key) is str and str.__eq__(key, name)
    )
    if tuple.__len__(matches) != 1 or tuple.__getitem__(matches, 0)[1] is not value:
        raise RuntimeError("sealed source dependency binding is unavailable")
    return tuple.__getitem__(matches, 0)


