def _capture_exact_single_callable_closure(
    label: str,
    function: FunctionType,
) -> tuple[tuple[CellType, ...], FunctionType]:
    closure = object.__getattribute__(function, "__closure__")
    if (
        type(label) is not str
        or type(function) is not FunctionType
        or type(closure) is not tuple
        or tuple.__len__(closure) != 1
        or type(tuple.__getitem__(closure, 0)) is not CellType
    ):
        raise RuntimeError(f"exact callable wrapper closure is unavailable: {label}")
    accept = _EXACT_CALLABLE_CELL_CONTENTS_DESCRIPTOR.__get__(
        tuple.__getitem__(closure, 0),
        CellType,
    )
    if type(accept) is not FunctionType:
        raise RuntimeError(f"exact callable wrapper provider is unavailable: {label}")
    return closure, accept


