def _capture_exact_temporal_module_record(
    expected_name: str,
    module: ModuleType,
) -> tuple[object, ...]:
    if type(expected_name) is not str or type(module) is not ModuleType:
        raise RuntimeError("exact Hypothesis temporal module is unavailable")
    namespace = vars(module)
    specification = namespace.get("__spec__")
    if type(specification) is not ModuleSpec:
        raise RuntimeError("exact Hypothesis temporal module spec is unavailable")
    specification_namespace = vars(specification)
    loader = namespace.get("__loader__")
    return (
        expected_name,
        module,
        namespace.get("__name__"),
        namespace.get("__package__"),
        namespace.get("__file__"),
        specification,
        specification_namespace.get("name"),
        specification_namespace.get("origin"),
        loader,
        specification_namespace.get("loader"),
        vars(loader).get("name") if type(loader) is SourceFileLoader else None,
        vars(loader).get("path") if type(loader) is SourceFileLoader else None,
    )


