def _capture_exact_temporal_none_default(
    strategy: object,
) -> tuple[dict[str, object], tuple[tuple[str, object], ...], dict[object, object], dict[str, object]]:
    if type(strategy) is not _EAGER_HYPOTHESIS_LAZY_STRATEGY_TYPE:
        raise RuntimeError("exact Hypothesis temporal LazyStrategy is unavailable")
    namespace = object.__getattribute__(strategy, "__dict__")
    items = tuple(dict.items(namespace)) if type(namespace) is dict else ()
    validate_state = dict.get(namespace, "validate_called")
    kwargs = dict.get(namespace, "_LazyStrategy__kwargs")
    if (
        type(namespace) is not dict
        or type(validate_state) is not dict
        or type(kwargs) is not dict
    ):
        raise RuntimeError(
            "exact Hypothesis temporal LazyStrategy state is unavailable"
        )
    return namespace, items, validate_state, kwargs


