def _capture_exact_annotation_classdict(
    label: str,
    annotate: FunctionType | None,
) -> tuple[CellType, dict[str, object], tuple[tuple[str, object], ...]] | None:
    if annotate is None:
        return None
    closure = object.__getattribute__(annotate, "__closure__")
    if (
        type(label) is not str
        or type(annotate) is not FunctionType
        or type(closure) is not tuple
        or tuple.__len__(closure) != 1
        or type(tuple.__getitem__(closure, 0)) is not CellType
    ):
        raise RuntimeError(
            f"exact annotation classdict closure is unavailable: {label}"
        )
    cell = tuple.__getitem__(closure, 0)
    classdict = _EXACT_CALLABLE_CELL_CONTENTS_DESCRIPTOR.__get__(
        cell,
        CellType,
    )
    if type(classdict) is not dict:
        raise RuntimeError(
            f"exact annotation classdict is unavailable: {label}"
        )
    items = tuple(dict.items(classdict))
    if any(type(name) is not str for name, _value in items):
        raise RuntimeError(
            f"exact annotation classdict namespace changed: {label}"
        )
    return cell, classdict, items


