    def exact_kwdefault_items(
        mapping: object,
        expected_items: object,
    ) -> bool:
        if (
            _builtin_type(mapping) is not _dict_type
            or _builtin_type(expected_items) is not _tuple_type
        ):
            return False
        current_items = _tuple_type(_mapping_items(mapping))
        return (
            _builtin_len(current_items) == _builtin_len(expected_items)
            and _builtin_all(
                _builtin_type(current) is _tuple_type
                and _tuple_len(current) == 2
                and _builtin_type(expected) is _tuple_type
                and _tuple_len(expected) == 2
                and _builtin_type(_tuple_getitem(current, 0)) is _string_type
                and _builtin_type(_tuple_getitem(expected, 0)) is _string_type
                and _tuple_getitem(current, 0)
                is _tuple_getitem(expected, 0)
                and _tuple_getitem(current, 1)
                is _tuple_getitem(expected, 1)
                for current, expected in _builtin_zip(
                    current_items,
                    expected_items,
                    strict=True,
                )
            )
            is True
        )

