_FORWARD_REF_LAYOUT = (
    "__forward_is_argument__",
    "__forward_is_class__",
    "__forward_module__",
    "__weakref__",
    "__arg__",
    "__globals__",
    "__extra_names__",
    "__code__",
    "__ast_node__",
    "__cell__",
    "__owner__",
    "__stringifier_dict__",
)
_FORWARD_REF_DATA_SLOTS = tuple(
    name for name in _FORWARD_REF_LAYOUT if name != "__weakref__"
)


def _capture_eager_forward_ref_runtime() -> tuple[
    ModuleType,
    type[object],
    tuple[str, ...],
    Mapping[str, object],
    object,
]:
    """Retain the exact Python 3.14 unevaluated ForwardRef substrate."""

    module = sys.modules.get("annotationlib")
    if not isinstance(module, ModuleType):
        raise MutationToolchainError(
            "eager annotationlib runtime provider is missing"
        )
    forward_ref = vars(module).get("ForwardRef")
    if (
        type(forward_ref) is not type
        or type.__getattribute__(forward_ref, "__module__") != "annotationlib"
        or type.__getattribute__(forward_ref, "__qualname__") != "ForwardRef"
    ):
        raise MutationToolchainError(
            "eager annotationlib.ForwardRef provider is invalid"
        )
    layout = vars(forward_ref).get("__slots__")
    if type(layout) is not tuple or layout != _FORWARD_REF_LAYOUT:
        raise MutationToolchainError(
            "eager annotationlib.ForwardRef layout is invalid"
        )
    descriptors = {
        name: vars(forward_ref).get(name) for name in _FORWARD_REF_DATA_SLOTS
    }
    weakref_descriptor = vars(forward_ref).get("__weakref__")
    member_get = vars(MemberDescriptorType).get("__get__")
    if (
        any(
            type(descriptor) is not MemberDescriptorType
            for descriptor in descriptors.values()
        )
        or type(weakref_descriptor) is not GetSetDescriptorType
        or type(member_get) is not WrapperDescriptorType
    ):
        raise MutationToolchainError(
            "eager annotationlib.ForwardRef descriptors are invalid"
        )
    return (
        module,
        forward_ref,
        layout,
        MappingProxyType(descriptors),
        member_get,
    )


(
    _EAGER_ANNOTATIONLIB_MODULE,
    _EAGER_FORWARD_REF_TYPE,
    _EAGER_FORWARD_REF_LAYOUT,
    _EAGER_FORWARD_REF_DESCRIPTORS,
    _EAGER_MEMBER_DESCRIPTOR_GET,
) = _capture_eager_forward_ref_runtime()


