def _verify_eager_hypothesis_profile_type_providers(
    _record: _EagerHypothesisProfileTypeProviders = (
        _EAGER_HYPOTHESIS_PROFILE_TYPE_PROVIDERS
    ),
    _record_type: type[_EagerHypothesisProfileTypeProviders] = (
        _EagerHypothesisProfileTypeProviders
    ),
    _slots: tuple[str, ...] = (
        _EAGER_HYPOTHESIS_PROFILE_TYPE_PROVIDER_SLOTS
    ),
    _fingerprint: tuple[tuple[str, object, object], ...] = (
        _EAGER_HYPOTHESIS_PROFILE_TYPE_PROVIDER_FINGERPRINT
    ),
    _state_reader: FunctionType = (
        _checked_hypothesis_profile_type_provider_state
    ),
) -> _EagerHypothesisProfileTypeProviders:
    if (
        _EagerHypothesisProfileTypeProviders is not _record_type
        or _EAGER_HYPOTHESIS_PROFILE_TYPE_PROVIDERS is not _record
        or _EAGER_HYPOTHESIS_PROFILE_TYPE_PROVIDER_SLOTS is not _slots
        or _EAGER_HYPOTHESIS_PROFILE_TYPE_PROVIDER_FINGERPRINT
        is not _fingerprint
        or _checked_hypothesis_profile_type_provider_state
        is not _state_reader
        or type(_record) is not _record_type
        or type(_slots) is not tuple
        or type(_fingerprint) is not tuple
        or len(_slots) != len(_fingerprint)
    ):
        raise MutationToolchainError(
            "eager Hypothesis profile type-provider anchor changed"
        )
    record_namespace = type.__getattribute__(_record_type, "__dict__")
    if (
        type(record_namespace) is not MappingProxyType
        or record_namespace.get("__slots__") is not _slots
    ):
        raise MutationToolchainError(
            "eager Hypothesis profile type-provider layout changed"
        )
    for entry, expected_name in zip(_fingerprint, _slots, strict=True):
        if (
            type(entry) is not tuple
            or len(entry) != 3
            or type(entry[0]) is not str
            or entry[0] != expected_name
            or record_namespace.get(expected_name) is not entry[1]
            or object.__getattribute__(_record, expected_name) is not entry[2]
        ):
            raise MutationToolchainError(
                "eager Hypothesis profile type-provider fingerprint changed"
            )
    current = _state_reader(
        _record.typing_module,
        _record.annotationlib_module,
    )
    current_union_items = current[2] if len(current) == 13 else ()
    current_generic_alias_items = current[7] if len(current) == 13 else ()
    current_forward_ref_items = current[10] if len(current) == 13 else ()
    if (
        type(current) is not tuple
        or len(current) != 13
        or current[0] is not _record.typing_union_type
        or type(current[1]) is not MappingProxyType
        or type(current_union_items) is not tuple
        or len(current_union_items) != len(_record.typing_union_items)
        or not all(
            type(current_name) is str
            and current_name == expected_name
            and current_member is expected_member
            for (current_name, current_member), (
                expected_name,
                expected_member,
            ) in zip(
                current_union_items,
                _record.typing_union_items,
                strict=True,
            )
        )
        or current[3] is not _record.typing_union_args_descriptor
        or current[4] is not _record.generic_alias_type
        or current[5] is not _record.generic_alias_base_type
        or type(current[6]) is not MappingProxyType
        or type(current_generic_alias_items) is not tuple
        or len(current_generic_alias_items) != len(_record.generic_alias_items)
        or not all(
            type(current_name) is str
            and current_name == expected_name
            and current_member is expected_member
            for (current_name, current_member), (
                expected_name,
                expected_member,
            ) in zip(
                current_generic_alias_items,
                _record.generic_alias_items,
                strict=True,
            )
        )
        or current[8] is not _record.forward_ref_type
        or type(current[9]) is not MappingProxyType
        or type(current_forward_ref_items) is not tuple
        or len(current_forward_ref_items) != len(_record.forward_ref_items)
        or not all(
            type(current_name) is str
            and current_name == expected_name
            and current_member is expected_member
            for (current_name, current_member), (
                expected_name,
                expected_member,
            ) in zip(
                current_forward_ref_items,
                _record.forward_ref_items,
                strict=True,
            )
        )
        or current[11] is not _record.forward_ref_arg_descriptor
        or current[12] is not _record.member_descriptor_get
    ):
        raise MutationToolchainError(
            "reviewed Hypothesis profile type-provider binding changed"
        )
    return _record


def _runtime_snapshot_descriptor_value(
    value: FunctionType,
    name: str,
) -> object:
    descriptor = _FUNCTION_RUNTIME_DESCRIPTORS.get(name)
    if descriptor is None or vars(FunctionType).get(name) is not descriptor:
        raise MutationToolchainError(
            f"runtime function descriptor changed: {name}"
        )
    getter = vars(type(descriptor)).get("__get__")
    if getter is None:
        raise MutationToolchainError(
            f"runtime function descriptor is not readable: {name}"
        )
    return getter(descriptor, value, FunctionType)


def _runtime_method_descriptor_value(value: MethodType, name: str) -> object:
    descriptor = _METHOD_RUNTIME_DESCRIPTORS.get(name)
    if (
        type(descriptor) is not MemberDescriptorType
        or vars(MethodType).get(name) is not descriptor
    ):
        raise MutationToolchainError(
            f"runtime method descriptor changed: {name}"
        )
    getter = vars(MemberDescriptorType).get("__get__")
    if type(getter) is not WrapperDescriptorType:
        raise MutationToolchainError(
            f"runtime method descriptor is not readable: {name}"
        )
    return getter(descriptor, value, MethodType)


def _runtime_snapshot_enter(
    value: object,
    *,
    context: _RuntimeSnapshotContext,
) -> tuple[int | None, object | None]:
    identity = id(value)
    reference = context.active.get(identity)
    if reference is not None:
        return None, ["cycle", reference]
    reference = context.next_reference
    context.next_reference += 1
    context.active[identity] = reference
    return reference, None


def _runtime_snapshot_leave(
    value: object,
    *,
    context: _RuntimeSnapshotContext,
) -> None:
    context.active.pop(id(value), None)


def _exact_runtime_class_metadata(value: type[object]) -> tuple[str, str]:
    try:
        module_name = type.__getattribute__(value, "__module__")
        qualname = type.__getattribute__(value, "__qualname__")
    except Exception as exc:
        raise MutationToolchainError(
            "runtime class metadata is not inspectable without user hooks"
        ) from exc
    if not isinstance(module_name, str) or not isinstance(qualname, str):
        raise MutationToolchainError("runtime class metadata is invalid")
    return module_name, qualname


def _runtime_class_reference_shape(value: type[object]) -> object:
    module_name, qualname = _exact_runtime_class_metadata(value)
    metaclass = type(value)
    metaclass_module, metaclass_qualname = _exact_runtime_class_metadata(
        metaclass
    )
    try:
        bases = type.__getattribute__(value, "__bases__")
    except Exception as exc:
        raise MutationToolchainError(
            "runtime class hierarchy is not inspectable without user hooks"
        ) from exc
    if type(bases) is not tuple or not all(_is_runtime_class(base) for base in bases):
        raise MutationToolchainError("runtime class hierarchy is invalid")
    return [
        "class-reference",
        module_name,
        qualname,
        _exact_module_qualname_binding(module_name, qualname) is value,
        [metaclass_module, metaclass_qualname],
        [list(_exact_runtime_class_metadata(base)) for base in bases],
    ]


