def _capture_eager_namedtuple_source_classdict_cell(
    *,
    label: str,
    source_module_name: str,
    source_class_name: str,
) -> _EagerSourceClassdictCellBinding:
    """Retain one explicitly named compiler-created NamedTuple annotation cycle."""

    if (
        type(label) is not str
        or type(source_module_name) is not str
        or type(source_class_name) is not str
    ):
        raise MutationToolchainError(
            "reviewed source classdict cell coordinates are invalid"
        )
    source_module = sys.modules.get(source_module_name)
    typing_module = sys.modules.get("typing")
    cell_provider_module = sys.modules.get("types")
    if (
        type(source_module) is not ModuleType
        or type(typing_module) is not ModuleType
        or type(cell_provider_module) is not ModuleType
    ):
        raise MutationToolchainError(
            "reviewed source classdict cell providers are missing"
        )

    source_class = vars(source_module).get(source_class_name)
    named_tuple_meta = vars(typing_module).get("NamedTupleMeta")
    if type(source_class) is not type or type(named_tuple_meta) is not type:
        raise MutationToolchainError(
            "reviewed source classdict cell owners are invalid"
        )
    source_namespace = type.__getattribute__(source_class, "__dict__")
    named_tuple_namespace = type.__getattribute__(named_tuple_meta, "__dict__")
    if (
        type(source_namespace) is not MappingProxyType
        or type(named_tuple_namespace) is not MappingProxyType
    ):
        raise MutationToolchainError(
            "reviewed source classdict cell owner namespace is invalid"
        )

    wrapper = _EAGER_MAPPING_PROXY_GET(source_namespace, "__annotate_func__")
    classdict_cell = _EAGER_MAPPING_PROXY_GET(
        source_namespace,
        "__classdictcell__",
    )
    named_tuple_new_staticmethod = _EAGER_MAPPING_PROXY_GET(
        named_tuple_namespace,
        "__new__",
    )
    if (
        type(wrapper) is not FunctionType
        or type(classdict_cell) is not CellType
        or type(named_tuple_new_staticmethod) is not staticmethod
    ):
        raise MutationToolchainError(
            "reviewed source classdict cell bindings are invalid"
        )
    named_tuple_new = object.__getattribute__(
        named_tuple_new_staticmethod,
        "__func__",
    )
    if type(named_tuple_new) is not FunctionType:
        raise MutationToolchainError(
            "reviewed source classdict cell factory is invalid"
        )

    wrapper_globals = _runtime_snapshot_descriptor_value(wrapper, "__globals__")
    wrapper_code = _runtime_snapshot_descriptor_value(wrapper, "__code__")
    wrapper_closure = _runtime_snapshot_descriptor_value(wrapper, "__closure__")
    named_tuple_new_code = _runtime_snapshot_descriptor_value(
        named_tuple_new,
        "__code__",
    )
    if (
        wrapper_globals is not vars(typing_module)
        or type(wrapper_code) is not CodeType
        or type(wrapper_closure) is not tuple
        or tuple.__len__(wrapper_closure) != 1
        or type(tuple.__getitem__(wrapper_closure, 0)) is not CellType
        or wrapper_code.co_freevars != ("original_annotate",)
        or _runtime_snapshot_descriptor_value(wrapper, "__module__") != "typing"
        or _runtime_snapshot_descriptor_value(wrapper, "__name__") != "annotate"
        or _runtime_snapshot_descriptor_value(wrapper, "__qualname__")
        != "NamedTupleMeta.__new__.<locals>.annotate"
        or _runtime_snapshot_descriptor_value(named_tuple_new, "__globals__")
        is not vars(typing_module)
        or type(named_tuple_new_code) is not CodeType
        or _runtime_snapshot_descriptor_value(named_tuple_new, "__module__")
        != "typing"
        or _runtime_snapshot_descriptor_value(named_tuple_new, "__name__")
        != "__new__"
        or _runtime_snapshot_descriptor_value(named_tuple_new, "__qualname__")
        != "NamedTupleMeta.__new__"
        or _runtime_snapshot_descriptor_value(named_tuple_new, "__closure__")
        is not None
        or not any(item is wrapper_code for item in named_tuple_new_code.co_consts)
    ):
        raise MutationToolchainError(
            "reviewed source classdict cell wrapper provenance changed"
        )

    cell_contents_descriptor = _CELL_CONTENTS_DESCRIPTOR
    if (
        vars(cell_provider_module).get("CellType") is not CellType
        or type(cell_contents_descriptor) is not GetSetDescriptorType
        or vars(CellType).get("cell_contents") is not cell_contents_descriptor
        or object.__getattribute__(cell_contents_descriptor, "__objclass__")
        is not CellType
        or object.__getattribute__(cell_contents_descriptor, "__name__")
        != "cell_contents"
    ):
        raise MutationToolchainError(
            "reviewed source classdict cell descriptor changed"
        )

    wrapper_cell = tuple.__getitem__(wrapper_closure, 0)
    try:
        original = cell_contents_descriptor.__get__(wrapper_cell, CellType)
    except (AttributeError, ValueError) as exc:
        raise MutationToolchainError(
            "reviewed source classdict cell wrapper is empty"
        ) from exc
    if type(original) is not FunctionType:
        raise MutationToolchainError(
            "reviewed source classdict cell original annotate is invalid"
        )
    original_globals = _runtime_snapshot_descriptor_value(original, "__globals__")
    original_code = _runtime_snapshot_descriptor_value(original, "__code__")
    original_closure = _runtime_snapshot_descriptor_value(original, "__closure__")
    if (
        original_globals is not vars(source_module)
        or type(original_code) is not CodeType
        or type(original_closure) is not tuple
        or tuple.__len__(original_closure) != 1
        or tuple.__getitem__(original_closure, 0) is not classdict_cell
        or original_code.co_freevars != ("__classdict__",)
        or _runtime_snapshot_descriptor_value(original, "__module__")
        != source_module_name
        or _runtime_snapshot_descriptor_value(original, "__name__")
        != "__annotate__"
        or _runtime_snapshot_descriptor_value(original, "__qualname__")
        != f"{source_class_name}.__annotate__"
    ):
        raise MutationToolchainError(
            "reviewed source classdict cell original provenance changed"
        )

    try:
        classdict = cell_contents_descriptor.__get__(classdict_cell, CellType)
    except (AttributeError, ValueError) as exc:
        raise MutationToolchainError(
            "reviewed source classdict cell is empty"
        ) from exc
    if type(classdict) is not dict:
        raise MutationToolchainError(
            "reviewed source classdict cell contents are invalid"
        )
    classdict_items = tuple(dict.items(classdict))
    if (
        not classdict_items
        or not all(type(name) is str for name, _value in classdict_items)
        or dict.get(classdict, "__classdictcell__") is not classdict_cell
        or dict.get(classdict, "__annotate_func__") is not original
        or _EAGER_MAPPING_PROXY_GET(source_namespace, "__annotate_func__")
        is not wrapper
        or _EAGER_MAPPING_PROXY_GET(source_namespace, "__classdictcell__")
        is not classdict_cell
        or sys.modules.get(source_module_name) is not source_module
        or sys.modules.get("typing") is not typing_module
        or sys.modules.get("types") is not cell_provider_module
        or vars(source_module).get("__name__") != source_module_name
        or vars(source_module).get(source_class_name) is not source_class
        or _EAGER_MAPPING_PROXY_GET(source_namespace, "__module__")
        != source_module_name
        or _exact_runtime_class_metadata(source_class)
        != (source_module_name, source_class_name)
        or vars(typing_module).get("NamedTupleMeta") is not named_tuple_meta
        or _EAGER_MAPPING_PROXY_GET(named_tuple_namespace, "__module__")
        != "typing"
        or _exact_runtime_class_metadata(named_tuple_meta)
        != ("typing", "NamedTupleMeta")
    ):
        raise MutationToolchainError(
            "reviewed source classdict cell ownership changed"
        )

    return _EagerSourceClassdictCellBinding(
        label=label,
        source_module_name=source_module_name,
        source_module=source_module,
        source_class_name=source_class_name,
        source_class=source_class,
        typing_module=typing_module,
        named_tuple_meta=named_tuple_meta,
        named_tuple_new_staticmethod=named_tuple_new_staticmethod,
        named_tuple_new=named_tuple_new,
        named_tuple_new_code=named_tuple_new_code,
        wrapper=wrapper,
        wrapper_code=wrapper_code,
        wrapper_closure=wrapper_closure,
        wrapper_cell=wrapper_cell,
        original=original,
        original_code=original_code,
        original_closure=original_closure,
        classdict_cell=classdict_cell,
        classdict=classdict,
        classdict_items=classdict_items,
        cell_provider_module=cell_provider_module,
        cell_type=CellType,
        cell_contents_descriptor=cell_contents_descriptor,
    )


