def _requires_eager_semantic_snapshot(value: object) -> bool:
    value_type = type(value)
    return (
        value_type is FunctionType
        or value_type is _PARTIAL_TYPE
        or value_type is property
        or value_type is staticmethod
        or value_type is classmethod
        or value_type is _CACHED_PROPERTY_TYPE
    )


def _capture_eager_module_namespaces(
) -> Mapping[str, tuple[ModuleType, tuple[_EagerNamespaceEntry, ...]]]:
    captured: dict[
        str,
        tuple[ModuleType, tuple[_EagerNamespaceEntry, ...]],
    ] = {}
    for module_name, (module, namespace) in (
        _RAW_MODULE_NAMESPACES_AFTER_DETERMINISTIC_IMPORTS.items()
    ):
        entries: list[_EagerNamespaceEntry] = []
        for name, value, scalar_sha256 in namespace:
            semantic_shape: object | None = None
            semantic_error: str | None = None
            if _requires_eager_semantic_snapshot(value):
                try:
                    semantic_shape = _runtime_value_shape(value)
                except MutationToolchainError as exc:
                    # Capture the inability itself.  If this attribute is ever
                    # used as a provider edge, verification fails closed rather
                    # than silently falling back to top-level identity.
                    semantic_error = str(exc)
            entries.append(
                _EagerNamespaceEntry(
                    name=name,
                    value=value,
                    scalar_sha256=scalar_sha256,
                    semantic_shape=semantic_shape,
                    semantic_error=semantic_error,
                )
            )
        captured[module_name] = (module, tuple(entries))
    return MappingProxyType(captured)


_MODULE_NAMESPACES_AFTER_DETERMINISTIC_IMPORTS = (
    _capture_eager_module_namespaces()
)


