def _lru_wrapper_semantic_shape(
    value: object,
    *,
    source_class: tuple[ModuleType, type[object], str] | None = None,
) -> object:
    namespace = vars(value)
    if type(namespace) is not dict:
        raise MutationToolchainError(
            "eager LRU wrapper namespace is not an exact dictionary"
        )
    wrapped = dict.get(namespace, "__wrapped__", _EAGER_ATTRIBUTE_MISSING)
    if wrapped is _EAGER_ATTRIBUTE_MISSING:
        raise MutationToolchainError("eager LRU wrapper omits __wrapped__")
    return [
        "functools._lru_cache_wrapper",
        _runtime_value_shape(wrapped, _source_class=source_class),
        _runtime_value_shape(namespace, _source_class=source_class),
    ]


def _lru_source_class_from_paths(
    paths: Sequence[_EagerLruWrapperPath],
) -> tuple[ModuleType, type[object], str] | None:
    selected: list[tuple[ModuleType, type[object], str]] = []
    for path in paths:
        if path.kind not in {"property-fget", "descriptor-func"}:
            continue
        class_name = path.components[0]
        owner = path.components[1]
        if type(class_name) is not str or not _is_runtime_class(owner):
            raise MutationToolchainError(
                f"reviewed LRU class path changed: {path.label}"
            )
        selected.append((path.module, owner, class_name))
    if not selected:
        return None
    first = selected[0]
    if not all(
        module is first[0] and owner is first[1] and name == first[2]
        for module, owner, name in selected
    ):
        raise MutationToolchainError(
            "reviewed LRU wrapper has ambiguous source-class ownership"
        )
    return first


def _lru_cache_info_type_state(value: type[object]) -> object:
    if (
        type(value) is not type
        or _exact_runtime_class_metadata(value) != ("functools", "CacheInfo")
        or type.__getattribute__(value, "__bases__") != (tuple,)
    ):
        raise MutationToolchainError("functools CacheInfo type changed")
    namespace = type.__getattribute__(value, "__dict__")
    if type(namespace) is not MappingProxyType:
        raise MutationToolchainError("functools CacheInfo namespace changed")
    keys = tuple(namespace.keys())
    if not all(type(key) is str for key in keys):
        raise MutationToolchainError("functools CacheInfo namespace changed")
    members: list[tuple[str, object, object | None]] = []
    for key in sorted(keys):
        member = namespace[key]
        semantic_shape = None
        if (
            _requires_eager_semantic_snapshot(member)
            or type(member) in {tuple, list, dict, set, frozenset}
        ):
            semantic_shape = _runtime_value_shape(member)
        members.append((key, member, semantic_shape))
    return tuple(members)


def _lru_cache_info_type_state_matches(
    value: type[object],
    expected: object,
) -> bool:
    current = _lru_cache_info_type_state(value)
    if type(expected) is not tuple or tuple.__len__(current) != tuple.__len__(
        expected
    ):
        return False
    for index in range(tuple.__len__(current)):
        current_item = tuple.__getitem__(current, index)
        expected_item = tuple.__getitem__(expected, index)
        if (
            type(current_item) is not tuple
            or type(expected_item) is not tuple
            or tuple.__len__(current_item) != 3
            or tuple.__len__(expected_item) != 3
            or type(tuple.__getitem__(current_item, 0)) is not str
            or tuple.__getitem__(current_item, 0)
            != tuple.__getitem__(expected_item, 0)
            or tuple.__getitem__(current_item, 1)
            is not tuple.__getitem__(expected_item, 1)
            or tuple.__getitem__(current_item, 2)
            != tuple.__getitem__(expected_item, 2)
        ):
            return False
    return True


