def _captured_lru_provider_module(module_name: str) -> ModuleType:
    captured = _RAW_MODULE_NAMESPACES_AFTER_DETERMINISTIC_IMPORTS.get(
        module_name
    )
    if captured is None:
        raise MutationToolchainError(
            f"reviewed functools LRU-wrapper module is unavailable: {module_name}"
        )
    module, _namespace = captured
    if sys.modules.get(module_name) is not module:
        raise MutationToolchainError(
            f"reviewed functools LRU-wrapper module binding changed: {module_name}"
        )
    return module


def _capture_eager_pytest_plugin_manager_provider() -> tuple[
    ModuleType,
    type[object],
    type[object],
    FunctionType,
    object,
    tuple[str, ...],
    tuple[str, ...],
    tuple[tuple[str, object], ...],
    tuple[tuple[str, object], ...],
]:
    module = _captured_lru_provider_module("_pytest.config")
    config_type = vars(module).get("Config")
    manager_type = vars(module).get("PytestPluginManager")
    get_directory = vars(module).get("_get_directory")
    assignments = vars(functools).get("WRAPPER_ASSIGNMENTS")
    updates = vars(functools).get("WRAPPER_UPDATES")
    if (
        not _is_runtime_class(config_type)
        or type.__getattribute__(config_type, "__module__") != "_pytest.config"
        or type.__getattribute__(config_type, "__qualname__") != "Config"
        or not _is_runtime_class(manager_type)
        or type.__getattribute__(manager_type, "__module__") != "_pytest.config"
        or type.__getattribute__(manager_type, "__qualname__")
        != "PytestPluginManager"
        or type(get_directory) is not FunctionType
        or get_directory.__module__ != "_pytest.config"
        or get_directory.__qualname__ != "_get_directory"
        or type(assignments) is not tuple
        or not assignments
        or not all(type(name) is str and name for name in assignments)
        or type(updates) is not tuple
        or updates != ("__dict__",)
    ):
        raise MutationToolchainError(
            "reviewed pytest plugin-manager LRU provider changed"
        )
    assigned_values: list[tuple[str, object]] = []
    for name in assignments:
        try:
            value = object.__getattribute__(get_directory, name)
        except AttributeError as exc:
            raise MutationToolchainError(
                "reviewed pytest _get_directory wrapper metadata changed"
            ) from exc
        assigned_values.append((name, value))
    namespace = object.__getattribute__(get_directory, "__dict__")
    if type(namespace) is not dict or not all(
        type(name) is str for name in dict.keys(namespace)
    ):
        raise MutationToolchainError(
            "reviewed pytest _get_directory function namespace changed"
        )
    return (
        module,
        config_type,
        manager_type,
        get_directory,
        _runtime_value_shape(get_directory),
        assignments,
        updates,
        tuple(assigned_values),
        tuple(dict.items(namespace)),
    )


