def _exact_hypothesis_compat_function_candidate(
    source_binding: _SourceBinding,
    *,
    name: str,
    first_line: int,
    guard_operator: str,
    guard_width: int,
    guard_version: tuple[int, ...],
    guard_branch: bool,
    _field_reader: FunctionType = _hypothesis_compat_source_record_field,
) -> tuple[
    _SourceBindingCandidate,
    _SourceVersionPrefixGuard,
    _SourceFunctionSemantics,
]:
    if (
        _hypothesis_compat_source_record_field is not _field_reader
        or type(name) is not str
        or type(first_line) is not int
        or first_line <= 0
        or type(guard_operator) is not str
        or not str.__eq__(guard_operator, "lt")
        or type(guard_width) is not int
        or guard_width <= 0
        or type(guard_version) is not tuple
        or tuple.__len__(guard_version) != guard_width
        or any(type(value) is not int or value < 0 for value in guard_version)
        or type(guard_branch) is not bool
    ):
        raise MutationToolchainError(
            "reviewed Hypothesis compat stdlib alias expectation changed"
        )
