def _exact_hypothesis_compat_required_module_import(
    imports: tuple[_SourceImportBinding, ...],
    *,
    module_name: str,
    _field_reader: FunctionType = _hypothesis_compat_source_record_field,
) -> _SourceImportBinding:
    if (
        _hypothesis_compat_source_record_field is not _field_reader
        or type(imports) is not tuple
        or type(module_name) is not str
    ):
        raise MutationToolchainError(
            "reviewed Hypothesis compat import expectation changed"
        )
    matching: list[_SourceImportBinding] = []
    for import_binding in imports:
        name = _field_reader(
            import_binding,
            tag="import_binding",
            field_name="name",
        )
        if type(name) is not str:
            raise MutationToolchainError(
                "reviewed Hypothesis compat import name changed"
            )
        if str.__eq__(name, module_name):
            matching.append(import_binding)
    if len(matching) != 1:
        raise MutationToolchainError(
            "reviewed Hypothesis compat import binding changed"
        )
    import_binding = matching[0]
    required = _field_reader(
        import_binding,
        tag="import_binding",
        field_name="required",
    )
    may_be_overwritten = _field_reader(
        import_binding,
        tag="import_binding",
        field_name="may_be_overwritten",
    )
    candidates = _field_reader(
        import_binding,
        tag="import_binding",
        field_name="candidates",
    )
    overwrite_candidates = _field_reader(
        import_binding,
        tag="import_binding",
        field_name="overwrite_candidates",
    )
    if (
        type(required) is not bool
        or required is not True
        or type(may_be_overwritten) is not bool
        or may_be_overwritten is not False
        or type(overwrite_candidates) is not tuple
        or tuple.__len__(overwrite_candidates) != 0
        or type(candidates) is not tuple
        or tuple.__len__(candidates) != 1
    ):
        raise MutationToolchainError(
            "reviewed Hypothesis compat import topology changed"
        )
    candidate = tuple.__getitem__(candidates, 0)
    candidate_module = _field_reader(
        candidate,
        tag="import_candidate",
        field_name="module",
    )
    candidate_level = _field_reader(
        candidate,
        tag="import_candidate",
        field_name="level",
    )
    candidate_attribute = _field_reader(
        candidate,
        tag="import_candidate",
        field_name="attribute",
    )
    candidate_star = _field_reader(
        candidate,
        tag="import_candidate",
        field_name="star",
    )
    if (
        type(candidate_module) is not str
        or not str.__eq__(candidate_module, module_name)
        or type(candidate_level) is not int
        or not int.__eq__(candidate_level, 0)
        or candidate_attribute is not None
        or type(candidate_star) is not bool
        or candidate_star is not False
    ):
        raise MutationToolchainError(
            "reviewed Hypothesis compat import candidate changed"
        )
    return import_binding


def _exact_hypothesis_compat_inactive_stdlib_alias_expected_value(
    module: ModuleType,
    *,
    policy: _SourceCodePolicy,
    source_binding: _SourceBinding,
    _field_reader: FunctionType = _hypothesis_compat_source_record_field,
    _candidate_reader: FunctionType = _exact_hypothesis_compat_function_candidate,
    _imports_reader: FunctionType = _validated_hypothesis_compat_source_imports,
    _bindings_reader: FunctionType = _validated_hypothesis_compat_source_bindings,
    _required_import_reader: FunctionType = (
        _exact_hypothesis_compat_required_module_import
    ),
    _stdlib_verifier: FunctionType = (
        _verify_eager_hypothesis_compat_stdlib_providers
    ),
    _dataclasses_verifier: FunctionType = (
        _verify_eager_hypothesis_compat_dataclasses_provider
    ),
    _batched_verifier: FunctionType = (
        _verify_eager_hypothesis_compat_batched_provider
    ),
    _prefix_modules: tuple[tuple[str, ModuleType], ...] = (
        _PREFIX_MODULES_AFTER_DETERMINISTIC_IMPORTS
    ),
    _deterministic_prefix: Path = _DETERMINISTIC_IMPORT_PREFIX,
    _missing: object = _INACTIVE_SOURCE_IMPORT_UNAVAILABLE,
    _stable_bytes: FunctionType = _stable_policy_bytes,
    _sha256: FunctionType = _sha256_bytes,
    _ast_sha256: FunctionType = _source_ast_sha256,
    _path_type: type[Path] = Path,
    _ast_module: ModuleType = ast,
    _os_module: ModuleType = os,
    _sys_module: ModuleType = sys,
    _builtins_module: ModuleType = builtins,
    _tuple_type: type[tuple[object, ...]] = tuple,
    _sys_version_info: object = sys.version_info,
    _compat_source_sha256: str = _HYPOTHESIS_COMPAT_SOURCE_SHA256,
    _compat_ast_sha256: str = _HYPOTHESIS_COMPAT_AST_SHA256,
) -> object:
    if (
        _hypothesis_compat_source_record_field is not _field_reader
        or _exact_hypothesis_compat_function_candidate is not _candidate_reader
        or _validated_hypothesis_compat_source_imports is not _imports_reader
        or _validated_hypothesis_compat_source_bindings is not _bindings_reader
        or _exact_hypothesis_compat_required_module_import
        is not _required_import_reader
        or _verify_eager_hypothesis_compat_stdlib_providers
        is not _stdlib_verifier
        or _verify_eager_hypothesis_compat_dataclasses_provider
        is not _dataclasses_verifier
        or _verify_eager_hypothesis_compat_batched_provider
        is not _batched_verifier
        or _PREFIX_MODULES_AFTER_DETERMINISTIC_IMPORTS is not _prefix_modules
        or _DETERMINISTIC_IMPORT_PREFIX is not _deterministic_prefix
        or _INACTIVE_SOURCE_IMPORT_UNAVAILABLE is not _missing
        or _stable_policy_bytes is not _stable_bytes
        or _sha256_bytes is not _sha256
        or _source_ast_sha256 is not _ast_sha256
        or Path is not _path_type
        or ast is not _ast_module
        or os is not _os_module
        or sys is not _sys_module
        or builtins is not _builtins_module
        or tuple is not _tuple_type
        or type(_compat_source_sha256) is not str
        or _HYPOTHESIS_COMPAT_SOURCE_SHA256 is not _compat_source_sha256
        or type(_compat_ast_sha256) is not str
        or _HYPOTHESIS_COMPAT_AST_SHA256 is not _compat_ast_sha256
        or type(module) is not ModuleType
        or vars(_builtins_module).get("tuple") is not _tuple_type
        or vars(_sys_module).get("version_info") is not _sys_version_info
        or _sys_module.modules.get("sys") is not _sys_module
    ):
        raise MutationToolchainError(
            "reviewed Hypothesis compat stdlib alias reader changed"
        )
    namespace = vars(module)
    if type(namespace) is not dict:
        raise MutationToolchainError(
            "reviewed Hypothesis compat stdlib alias owner changed"
        )
    module_name = dict.get(namespace, "__name__")
    if type(module_name) is not str:
        raise MutationToolchainError(
            "reviewed Hypothesis compat stdlib alias owner changed"
        )
    if not str.__eq__(module_name, "hypothesis.internal.compat"):
        return _missing

    policy_source_ast_sha256 = _field_reader(
        policy,
        tag="policy",
        field_name="source_ast_sha256",
    )
    if (
        type(policy_source_ast_sha256) is not str
        or not str.__eq__(policy_source_ast_sha256, _compat_ast_sha256)
    ):
        raise MutationToolchainError(
            "reviewed Hypothesis compat stdlib alias policy changed"
        )
    imports = _imports_reader(policy)
    bindings = _bindings_reader(policy)
    if sum(binding is source_binding for binding in bindings) != 1:
        raise MutationToolchainError(
            "reviewed Hypothesis compat stdlib alias binding changed"
        )
    path = _field_reader(source_binding, tag="binding", field_name="path")
    if type(path) is not tuple or any(type(part) is not str for part in path):
        raise MutationToolchainError(
            "reviewed Hypothesis compat stdlib alias path changed"
        )
    if tuple.__len__(path) != 1:
        return _missing
    name = tuple.__getitem__(path, 0)
    is_dataclass_asdict = str.__eq__(name, "dataclass_asdict")
    is_batched = str.__eq__(name, "batched")
    if not is_dataclass_asdict and not is_batched:
        return _missing

    if is_dataclass_asdict:
        first_line = 279
        guard_version = (3, 12)
        provider_name = "dataclasses"
        branch_line = 252
        assignment_line = 292
        expected_test_source = "if sys.version_info[:2] < (3, 12):\n    pass\n"
        expected_assignment_source = "dataclass_asdict = dataclasses.asdict\n"
        expected_doc: str | None = (
            "\n        A vendored variant of dataclasses.asdict. Includes the bugfix for\n"
            "        defaultdicts (cpython/32056) for all versions. See also "
            "issues/3812.\n\n"
            "        This should be removed whenever we drop support for 3.11. "
            "We can use the\n"
            "        standard dataclasses.asdict after that point.\n        "
        )
    else:
        first_line = 299
        guard_version = (3, 13)
        provider_name = "itertools"
        branch_line = 295
        assignment_line = 309
        expected_test_source = "if sys.version_info[:2] < (3, 13):\n    pass\n"
        expected_assignment_source = "batched = itertools.batched\n"
        expected_doc = None
    candidate, actual_guard, semantics = _candidate_reader(
        source_binding,
        name=name,
        first_line=first_line,
        guard_operator="lt",
        guard_width=2,
        guard_version=guard_version,
        guard_branch=True,
    )
    defaults = _field_reader(
        semantics,
        tag="semantics",
        field_name="defaults",
    )
    doc = _field_reader(semantics, tag="semantics", field_name="doc")
    if type(defaults) is not tuple or tuple.__len__(defaults) != 1:
        raise MutationToolchainError(
            "reviewed Hypothesis compat stdlib alias defaults changed"
        )
    default = tuple.__getitem__(defaults, 0)
    parameter = _field_reader(
        default,
        tag="default",
        field_name="parameter",
    )
    parameter_kind = _field_reader(
        default,
        tag="default",
        field_name="parameter_kind",
    )
    expression = _field_reader(
        default,
        tag="default",
        field_name="expression",
    )
    expression_kind = _field_reader(
        expression,
        tag="expression",
        field_name="kind",
    )
    expression_payload = _field_reader(
        expression,
        tag="expression",
        field_name="payload",
    )
    expression_ast_shape = _field_reader(
        expression,
        tag="expression",
        field_name="ast_shape",
    )
    if (
        type(parameter) is not str
        or type(parameter_kind) is not str
        or type(expression_kind) is not str
        or type(expression_ast_shape) is not str
    ):
        raise MutationToolchainError(
            "reviewed Hypothesis compat stdlib alias defaults changed"
        )
    if is_dataclass_asdict:
        if (
            not str.__eq__(parameter, "dict_factory")
            or not str.__eq__(parameter_kind, "keyword_only")
            or not str.__eq__(expression_kind, "reference")
            or type(expression_payload) is not tuple
            or tuple.__len__(expression_payload) != 1
            or type(tuple.__getitem__(expression_payload, 0)) is not str
            or not str.__eq__(tuple.__getitem__(expression_payload, 0), "dict")
            or not str.__eq__(
                expression_ast_shape,
                "Name(id='dict', ctx=Load())",
            )
            or type(doc) is not str
            or type(expected_doc) is not str
            or not str.__eq__(doc, expected_doc)
        ):
            raise MutationToolchainError(
                "reviewed Hypothesis compat dataclass_asdict defaults changed"
            )
    elif (
        not str.__eq__(parameter, "strict")
        or not str.__eq__(parameter_kind, "keyword_only")
        or not str.__eq__(expression_kind, "literal")
        or type(expression_payload) is not list
        or list.__len__(expression_payload) != 2
        or type(list.__getitem__(expression_payload, 0)) is not str
        or not str.__eq__(list.__getitem__(expression_payload, 0), "bool")
        or list.__getitem__(expression_payload, 1) is not False
        or not str.__eq__(expression_ast_shape, "Constant(value=False)")
        or doc is not None
        or expected_doc is not None
    ):
        raise MutationToolchainError(
            "reviewed Hypothesis compat batched defaults changed"
        )

    captured: list[ModuleType] = []
    if type(_prefix_modules) is not tuple:
        raise MutationToolchainError(
            "reviewed Hypothesis compat stdlib alias owner changed"
        )
    for retained_entry in _prefix_modules:
        if (
            type(retained_entry) is not tuple
            or tuple.__len__(retained_entry) != 2
            or type(tuple.__getitem__(retained_entry, 0)) is not str
            or type(tuple.__getitem__(retained_entry, 1)) is not ModuleType
        ):
            raise MutationToolchainError(
                "reviewed Hypothesis compat stdlib alias owner changed"
            )
        if str.__eq__(tuple.__getitem__(retained_entry, 0), module_name):
            captured.append(tuple.__getitem__(retained_entry, 1))
    module_file = dict.get(namespace, "__file__")
    if (
        len(captured) != 1
        or captured[0] is not module
        or _sys_module.modules.get(module_name) is not module
        or type(module_file) is not str
        or dict.get(namespace, "sys") is not _sys_module
    ):
        raise MutationToolchainError(
            "reviewed Hypothesis compat stdlib alias owner changed"
        )

    stdlib_record = _stdlib_verifier()
    if is_dataclass_asdict:
        provider = stdlib_record.dataclasses_module
        provider_value = stdlib_record.dataclass_asdict
        dataclasses_record = _dataclasses_verifier()
        if dataclasses_record.module is not provider:
            raise MutationToolchainError(
                "reviewed Hypothesis compat dataclasses provider changed"
            )
    else:
        provider = stdlib_record.itertools_module
        provider_value = stdlib_record.itertools_batched
        batched_record = _batched_verifier()
        if (
            batched_record.module is not provider
            or batched_record.value is not provider_value
        ):
            raise MutationToolchainError(
                "reviewed Hypothesis compat batched provider changed"
            )
    if (
        type(provider) is not ModuleType
        or dict.get(namespace, provider_name) is not provider
        or dict.get(namespace, name) is not provider_value
    ):
        raise MutationToolchainError(
            "reviewed Hypothesis compat stdlib alias identity changed"
        )

    _required_import_reader(imports, module_name="sys")
    _required_import_reader(imports, module_name=provider_name)
    version_prefix = _tuple_type(_sys_version_info)[:2]
    if (
        type(version_prefix) is not tuple
        or tuple.__len__(version_prefix) != 2
        or any(type(part) is not int or part < 0 for part in version_prefix)
        or tuple.__lt__(version_prefix, guard_version) is True
    ):
        raise MutationToolchainError(
            "reviewed Hypothesis compat stdlib alias branch changed"
        )

    source_path = _path_type(module_file).resolve(strict=True)
    source = _stable_bytes(
        _deterministic_prefix,
        source_path,
        label="reviewed Hypothesis compat source",
    )
    tree = _ast_module.parse(
        source,
        filename=_os_module.fspath(source_path),
        mode="exec",
    )
    if (
        not str.__eq__(_sha256(source), _compat_source_sha256)
        or not str.__eq__(_ast_sha256(tree), _compat_ast_sha256)
    ):
        raise MutationToolchainError(
            "reviewed Hypothesis compat stdlib alias branch changed"
        )
    branches = tuple(
        statement
        for statement in tree.body
        if type(statement) is ast.If and statement.lineno == branch_line
    )
    expected_test = _ast_module.parse(
        expected_test_source,
        mode="exec",
    ).body[0].test
    expected_assignment = _ast_module.parse(
        expected_assignment_source,
        mode="exec",
    ).body[0]
    if tuple.__len__(branches) != 1:
        raise MutationToolchainError(
            "reviewed Hypothesis compat stdlib alias topology changed"
        )
    branch = tuple.__getitem__(branches, 0)
    if (
        not str.__eq__(
            _ast_module.dump(branch.test, include_attributes=False),
            _ast_module.dump(expected_test, include_attributes=False),
        )
        or type(branch.orelse) is not list
        or list.__len__(branch.orelse) != 1
        or type(list.__getitem__(branch.orelse, 0)) is not ast.Assign
        or type(list.__getitem__(branch.orelse, 0).lineno) is not int
        or not int.__eq__(
            list.__getitem__(branch.orelse, 0).lineno,
            assignment_line,
        )
        or not str.__eq__(
            _ast_module.dump(
                list.__getitem__(branch.orelse, 0),
                include_attributes=False,
            ),
            _ast_module.dump(expected_assignment, include_attributes=False),
        )
    ):
        raise MutationToolchainError(
            "reviewed Hypothesis compat stdlib alias topology changed"
        )
    if is_batched:
        return provider_value

    sibling_bindings: list[_SourceBinding] = []
    for binding in bindings:
        binding_path = _field_reader(binding, tag="binding", field_name="path")
        if (
            type(binding_path) is tuple
            and tuple.__len__(binding_path) == 1
            and type(tuple.__getitem__(binding_path, 0)) is str
            and str.__eq__(tuple.__getitem__(binding_path, 0), "_asdict_inner")
        ):
            sibling_bindings.append(binding)
    if len(sibling_bindings) != 1:
        raise MutationToolchainError(
            "reviewed Hypothesis compat dataclass sibling changed"
        )
    _sibling, _sibling_guard, sibling_semantics = _candidate_reader(
        sibling_bindings[0],
        name="_asdict_inner",
        first_line=254,
        guard_operator="lt",
        guard_width=2,
        guard_version=(3, 12),
        guard_branch=True,
    )
    sibling_defaults = _field_reader(
        sibling_semantics,
        tag="semantics",
        field_name="defaults",
    )
    sibling_doc = _field_reader(
        sibling_semantics,
        tag="semantics",
        field_name="doc",
    )
    if (
        type(sibling_defaults) is not tuple
        or tuple.__len__(sibling_defaults) != 0
        or sibling_doc is not None
        or dict.get(namespace, "_asdict_inner", _missing) is not _missing
    ):
        raise MutationToolchainError(
            "reviewed Hypothesis compat dataclass sibling changed"
        )
    return provider_value


def _exact_hypothesis_entropy_randomlike_expected_value(
    module: ModuleType,
    *,
    policy: _SourceCodePolicy,
    source_binding: _SourceBinding,
    _record_accessor: FunctionType = (
        _exact_eager_hypothesis_entropy_randomlike_provider
    ),
    _provider_verifier: FunctionType = (
        _verify_eager_hypothesis_entropy_randomlike_provider
    ),
    _field_reader: FunctionType = _exact_source_record_field,
    _type_checking_reader: FunctionType = (
        _exact_active_source_type_checking_guard
    ),
    _missing: object = _INACTIVE_SOURCE_IMPORT_UNAVAILABLE,
    _module_registry: dict[str, ModuleType] = sys.modules,
    _toolchain_namespace: dict[str, object] = globals(),
    _module_type: type[ModuleType] = ModuleType,
    _function_type: type[FunctionType] = FunctionType,
    _guard_type: type[_SourceTypeCheckingGuard] = _SourceTypeCheckingGuard,
    _builtin_vars: BuiltinFunctionType = vars,
) -> object:
    """Admit only entropy's exact runtime ``random.Random`` fallback."""

    if (
        dict.get(
            _toolchain_namespace,
            "_exact_eager_hypothesis_entropy_randomlike_provider",
        )
        is not _record_accessor
        or dict.get(
            _toolchain_namespace,
            "_verify_eager_hypothesis_entropy_randomlike_provider",
        )
        is not _provider_verifier
        or dict.get(_toolchain_namespace, "_exact_source_record_field")
        is not _field_reader
        or dict.get(
            _toolchain_namespace,
            "_exact_active_source_type_checking_guard",
        )
        is not _type_checking_reader
        or dict.get(
            _toolchain_namespace,
            "_INACTIVE_SOURCE_IMPORT_UNAVAILABLE",
        )
        is not _missing
        or dict.get(_toolchain_namespace, "ModuleType") is not _module_type
        or dict.get(_toolchain_namespace, "FunctionType") is not _function_type
        or dict.get(_toolchain_namespace, "_SourceTypeCheckingGuard")
        is not _guard_type
        or sys.modules is not _module_registry
        or vars is not _builtin_vars
        or type(module) is not _module_type
    ):
        raise MutationToolchainError(
            "reviewed Hypothesis entropy alias reader changed"
        )
    record = _provider_verifier()
    namespace = _builtin_vars(module)
    module_name = dict.get(namespace, "__name__")
    if module is not record.module:
        if (
            type(module_name) is str
            and not str.__eq__(module_name, "hypothesis.internal.entropy")
        ):
            return _missing
        raise MutationToolchainError(
            "reviewed Hypothesis entropy alias owner changed"
        )
    if (
        type(module_name) is not str
        or not str.__eq__(module_name, "hypothesis.internal.entropy")
        or _module_registry.get(module_name) is not module
    ):
        raise MutationToolchainError(
            "reviewed Hypothesis entropy alias owner changed"
        )

    binding_path = _field_reader(source_binding, "path")
    if (
        type(binding_path) is not tuple
        or tuple.__len__(binding_path) not in (1, 2)
        or any(type(part) is not str for part in binding_path)
    ):
        raise MutationToolchainError(
            "reviewed Hypothesis entropy alias path changed"
        )
    if not str.__eq__(tuple.__getitem__(binding_path, 0), "RandomLike"):
        return _missing
    member_name: str | None = None
    if tuple.__len__(binding_path) == 2:
        candidate_member_name = tuple.__getitem__(binding_path, 1)
        if not any(
            str.__eq__(candidate_member_name, expected)
            for expected in ("seed", "getstate", "setstate")
        ):
            return _missing
        member_name = candidate_member_name

    policy_hash = _field_reader(policy, "source_ast_sha256")
    policy_bindings = _field_reader(policy, "bindings")
    policy_imports = _field_reader(policy, "imports")
    if (
        type(policy_hash) is not str
        or not str.__eq__(policy_hash, record.source_ast_sha256)
        or type(policy_bindings) is not tuple
        or sum(binding is source_binding for binding in policy_bindings) != 1
        or type(policy_imports) is not tuple
    ):
        raise MutationToolchainError(
            "reviewed Hypothesis entropy source policy changed"
        )

    binding_kind = _field_reader(source_binding, "kind")
    binding_accessor = _field_reader(source_binding, "accessor")
    binding_required = _field_reader(source_binding, "required")
    binding_must_be_absent = _field_reader(source_binding, "must_be_absent")
    binding_candidates = _field_reader(source_binding, "candidates")
    expected_kind = "class" if member_name is None else "function"
    expected_line = (
        31
        if member_name is None
        else {"seed": 32, "getstate": 33, "setstate": 34}[member_name]
    )
    expected_qualname = (
        "RandomLike"
        if member_name is None
        else f"RandomLike.{member_name}"
    )
    if (
        type(binding_kind) is not str
        or not str.__eq__(binding_kind, expected_kind)
        or type(binding_accessor) is not str
        or not str.__eq__(binding_accessor, "direct")
        or binding_required is not False
        or binding_must_be_absent is not False
        or type(binding_candidates) is not tuple
        or tuple.__len__(binding_candidates) != 1
    ):
        raise MutationToolchainError(
            "reviewed Hypothesis entropy source binding changed"
        )
    candidate = tuple.__getitem__(binding_candidates, 0)
    qualname = _field_reader(candidate, "qualname")
    first_line = _field_reader(candidate, "first_line")
    definition_line = _field_reader(candidate, "definition_line")
    decorators = _field_reader(candidate, "decorators")
    semantics = _field_reader(candidate, "function_semantics")
    guards = _field_reader(candidate, "guards")
    guards_complete = _field_reader(candidate, "guards_complete")
    if (
        type(qualname) is not str
        or not str.__eq__(qualname, expected_qualname)
        or type(first_line) is not int
        or not int.__eq__(first_line, expected_line)
        or type(definition_line) is not int
        or not int.__eq__(definition_line, expected_line)
        or type(decorators) is not tuple
        or tuple.__len__(decorators) != 0
        or type(guards) is not tuple
        or tuple.__len__(guards) != 1
        or guards_complete is not True
    ):
        raise MutationToolchainError(
            "reviewed Hypothesis entropy source candidate changed"
        )
    guard = tuple.__getitem__(guards, 0)
    if (
        type(guard) is not _guard_type
        or type(_field_reader(guard, "reference")) is not str
        or not str.__eq__(_field_reader(guard, "reference"), "direct")
        or _field_reader(guard, "branch") is not True
        or _type_checking_reader(
            module,
            policy=policy,
            guard=guard,
        )
        is not False
    ):
        raise MutationToolchainError(
            "reviewed Hypothesis entropy TYPE_CHECKING guard changed"
        )

    if member_name is None:
        if semantics is not None:
            raise MutationToolchainError(
                "reviewed Hypothesis entropy Protocol candidate changed"
            )
    else:
        defaults = _field_reader(semantics, "defaults")
        semantic_decorators = _field_reader(semantics, "decorators")
        doc = _field_reader(semantics, "doc")
        annotations = _field_reader(semantics, "annotations")
        type_parameters = _field_reader(semantics, "type_parameters")
        expected_annotations = (
            ("args", "var_positional"),
            ("kwargs", "var_keyword"),
            ("return", "return"),
        )
        if (
            type(defaults) is not tuple
            or tuple.__len__(defaults) != 0
            or type(semantic_decorators) is not tuple
            or tuple.__len__(semantic_decorators) != 0
            or doc is not None
            or type(annotations) is not tuple
            or tuple.__len__(annotations) != 3
            or type(type_parameters) is not tuple
            or tuple.__len__(type_parameters) != 0
        ):
            raise MutationToolchainError(
                "reviewed Hypothesis entropy Protocol method changed"
            )
        for annotation, (expected_name, expected_kind_name) in zip(
            annotations,
            expected_annotations,
            strict=True,
        ):
            if type(annotation) is not tuple or tuple.__len__(annotation) != 3:
                raise MutationToolchainError(
                    "reviewed Hypothesis entropy Protocol annotation changed"
                )
            annotation_name = tuple.__getitem__(annotation, 0)
            annotation_kind = tuple.__getitem__(annotation, 1)
            expression = tuple.__getitem__(annotation, 2)
            expression_kind = _field_reader(expression, "kind")
            expression_payload = _field_reader(expression, "payload")
            expression_shape = _field_reader(expression, "ast_shape")
            if (
                type(annotation_name) is not str
                or not str.__eq__(annotation_name, expected_name)
                or type(annotation_kind) is not str
                or not str.__eq__(annotation_kind, expected_kind_name)
                or type(expression_kind) is not str
                or not str.__eq__(expression_kind, "reference")
                or type(expression_payload) is not tuple
                or tuple.__len__(expression_payload) != 1
                or type(tuple.__getitem__(expression_payload, 0)) is not str
                or not str.__eq__(
                    tuple.__getitem__(expression_payload, 0),
                    "Any",
                )
                or type(expression_shape) is not str
                or not str.__eq__(expression_shape, "Name(id='Any', ctx=Load())")
            ):
                raise MutationToolchainError(
                    "reviewed Hypothesis entropy Protocol annotation changed"
                )

    expected_imports = (
        ("Any", True, "typing", "Any"),
        ("Protocol", False, "typing", "Protocol"),
        ("Random", True, "random", "Random"),
        ("TYPE_CHECKING", True, "typing", "TYPE_CHECKING"),
        ("random", True, "random", None),
    )
    for expected_name, expected_required, provider_name, provider_attribute in (
        expected_imports
    ):
        matches: list[_SourceImportBinding] = []
        for import_binding in policy_imports:
            import_name = _field_reader(import_binding, "name")
            if type(import_name) is not str:
                raise MutationToolchainError(
                    "reviewed Hypothesis entropy import metadata changed"
                )
            if str.__eq__(import_name, expected_name):
                matches.append(import_binding)
        if len(matches) != 1:
            raise MutationToolchainError(
                "reviewed Hypothesis entropy import topology changed"
            )
        import_binding = matches[0]
        required = _field_reader(import_binding, "required")
        may_be_overwritten = _field_reader(
            import_binding,
            "may_be_overwritten",
        )
        candidates = _field_reader(import_binding, "candidates")
        overwrite_candidates = _field_reader(
            import_binding,
            "overwrite_candidates",
        )
        if (
            required is not expected_required
            or may_be_overwritten is not False
            or type(candidates) is not tuple
            or tuple.__len__(candidates) != 1
            or type(overwrite_candidates) is not tuple
            or tuple.__len__(overwrite_candidates) != 0
        ):
            raise MutationToolchainError(
                "reviewed Hypothesis entropy import topology changed"
            )
        import_candidate = tuple.__getitem__(candidates, 0)
        actual_provider_name = _field_reader(import_candidate, "module")
        level = _field_reader(import_candidate, "level")
        actual_provider_attribute = _field_reader(
            import_candidate,
            "attribute",
        )
        star = _field_reader(import_candidate, "star")
        if (
            type(actual_provider_name) is not str
            or not str.__eq__(actual_provider_name, provider_name)
            or type(level) is not int
            or not int.__eq__(level, 0)
            or star is not False
            or (
                provider_attribute is None
                and actual_provider_attribute is not None
            )
            or (
                type(provider_attribute) is str
                and (
                    type(actual_provider_attribute) is not str
                    or not str.__eq__(
                        actual_provider_attribute,
                        provider_attribute,
                    )
                )
            )
        ):
            raise MutationToolchainError(
                "reviewed Hypothesis entropy import provider changed"
            )

    typing_namespace = _builtin_vars(record.typing_module)
    if (
        dict.get(namespace, "Any") is not dict.get(typing_namespace, "Any")
        or dict.get(namespace, "TYPE_CHECKING") is not False
        or dict.get(namespace, "random") is not record.random_module
        or dict.get(namespace, "Random") is not record.random_class
        or dict.get(namespace, "Protocol", _missing) is not _missing
    ):
        raise MutationToolchainError(
            "reviewed Hypothesis entropy runtime import changed"
        )
    if member_name is None:
        return record.random_class
    selected_method: object = _missing
    for fingerprint in record.random_method_fingerprints:
        if (
            type(fingerprint) is not tuple
            or tuple.__len__(fingerprint) != 16
            or type(tuple.__getitem__(fingerprint, 0)) is not str
        ):
            raise MutationToolchainError(
                "reviewed Hypothesis entropy method fingerprint changed"
            )
        if str.__eq__(tuple.__getitem__(fingerprint, 0), member_name):
            selected_method = tuple.__getitem__(fingerprint, 1)
    if selected_method is _missing:
        raise MutationToolchainError(
            "reviewed Hypothesis entropy method provider changed"
        )
    return selected_method


_EAGER_HYPOTHESIS_ENTROPY_RANDOMLIKE_ALIAS_READER = (
    _exact_hypothesis_entropy_randomlike_expected_value
)


_EAGER_HYPOTHESIS_COMPAT_INACTIVE_STDLIB_ALIAS_READER = (
    _exact_hypothesis_compat_inactive_stdlib_alias_expected_value
)


def _exact_inactive_source_import_expected_value(
    module: ModuleType,
    *,
    policy: _SourceCodePolicy,
    source_binding: _SourceBinding,
    _core_reader: FunctionType = _exact_inactive_source_import_expected_value_core,
    _entropy_reader: FunctionType = (
        _EAGER_HYPOTHESIS_ENTROPY_RANDOMLIKE_ALIAS_READER
    ),
    _compat_reader: FunctionType = (
        _EAGER_HYPOTHESIS_COMPAT_INACTIVE_STDLIB_ALIAS_READER
    ),
    _missing: object = _INACTIVE_SOURCE_IMPORT_UNAVAILABLE,
    _module_namespace: dict[str, object] = (
        _EAGER_HYPOTHESIS_COMPAT_SOURCE_RECORD_NAMESPACE
    ),
) -> object:
    """Route late compatibility aliases through immutable reader identities."""

    if (
        dict.get(
            _module_namespace,
            "_exact_inactive_source_import_expected_value_core",
        )
        is not _core_reader
        or dict.get(
            _module_namespace,
            "_exact_hypothesis_entropy_randomlike_expected_value",
        )
        is not _entropy_reader
        or dict.get(
            _module_namespace,
            "_EAGER_HYPOTHESIS_ENTROPY_RANDOMLIKE_ALIAS_READER",
        )
        is not _entropy_reader
        or dict.get(
            _module_namespace,
            "_exact_hypothesis_compat_inactive_stdlib_alias_expected_value",
        )
        is not _compat_reader
        or dict.get(
            _module_namespace,
            "_EAGER_HYPOTHESIS_COMPAT_INACTIVE_STDLIB_ALIAS_READER",
        )
        is not _compat_reader
        or dict.get(
            _module_namespace,
            "_INACTIVE_SOURCE_IMPORT_UNAVAILABLE",
        )
        is not _missing
        or type(_core_reader) is not FunctionType
        or type(_entropy_reader) is not FunctionType
        or type(_compat_reader) is not FunctionType
    ):
        raise MutationToolchainError(
            "reviewed inactive source import dispatcher changed"
        )
    entropy_value = _entropy_reader(
        module,
        policy=policy,
        source_binding=source_binding,
    )
    if entropy_value is not _missing:
        return entropy_value
    compat_value = _compat_reader(
        module,
        policy=policy,
        source_binding=source_binding,
    )
    if compat_value is not _missing:
        return compat_value
    return _core_reader(
        module,
        policy=policy,
        source_binding=source_binding,
    )


def _exact_hypothesis_compat_import_candidate(
    module: ModuleType,
    *,
    policy: _SourceCodePolicy,
    name: str,
    value: object,
    candidates: Sequence[tuple[str, ModuleType, str | None, object]],
) -> tuple[str, ModuleType, str | None, object] | None:
    module_name = vars(module).get("__name__")
    if (
        type(module_name) is not str
        or module_name != "hypothesis.internal.compat"
        or name not in {"NotRequired", "TypedDict", "override"}
    ):
        return None
    captured = tuple(
        retained
        for retained_name, retained in _PREFIX_MODULES_AFTER_DETERMINISTIC_IMPORTS
        if retained_name == module_name
    )
    module_file = vars(module).get("__file__")
    typing_module = sys.modules.get("typing")
    if (
        len(captured) != 1
        or captured[0] is not module
        or sys.modules.get(module_name) is not module
        or type(module_file) is not str
        or type(typing_module) is not ModuleType
        or vars(module).get("sys") is not sys
        or vars(module).get("typing") is not typing_module
        or vars(module).get("TYPE_CHECKING") is not False
        or policy.source_ast_sha256 != _HYPOTHESIS_COMPAT_AST_SHA256
    ):
        raise MutationToolchainError(
            "reviewed Hypothesis compat import owner changed"
        )
    source_path = Path(module_file).resolve(strict=True)
    source = _stable_policy_bytes(
        _DETERMINISTIC_IMPORT_PREFIX,
        source_path,
        label="reviewed Hypothesis compat source",
    )
    if (
        _sha256_bytes(source) != _HYPOTHESIS_COMPAT_SOURCE_SHA256
        or _source_ast_sha256(
            ast.parse(source, filename=os.fspath(source_path), mode="exec")
        )
        != _HYPOTHESIS_COMPAT_AST_SHA256
        or not _exact_source_type_checking_guard(
            module,
            policy=policy,
            guard=_SourceTypeCheckingGuard("direct", False),
        )
        or not _exact_source_version_prefix_guard(
            module,
            policy=policy,
            guard=_SourceVersionPrefixGuard("ge", 2, (3, 11), True),
        )
    ):
        raise MutationToolchainError(
            "reviewed Hypothesis compat import branch changed"
        )
    expected_candidates = {
        "NotRequired": (
            _SourceImportCandidate(
                module="typing_extensions",
                level=0,
                attribute="NotRequired",
                star=False,
            ),
            _SourceImportCandidate(
                module="typing",
                level=0,
                attribute="NotRequired",
                star=False,
            ),
            _SourceImportCandidate(
                module="typing_extensions",
                level=0,
                attribute="NotRequired",
                star=False,
            ),
        ),
        "TypedDict": (
            _SourceImportCandidate(
                module="typing",
                level=0,
                attribute="TypedDict",
                star=False,
            ),
            _SourceImportCandidate(
                module="typing_extensions",
                level=0,
                attribute="TypedDict",
                star=False,
            ),
            _SourceImportCandidate(
                module="typing",
                level=0,
                attribute="TypedDict",
                star=False,
            ),
            _SourceImportCandidate(
                module="typing_extensions",
                level=0,
                attribute="TypedDict",
                star=False,
            ),
        ),
        "override": (
            _SourceImportCandidate(
                module="typing_extensions",
                level=0,
                attribute="override",
                star=False,
            ),
            _SourceImportCandidate(
                module="typing",
                level=0,
                attribute="override",
                star=False,
            ),
            _SourceImportCandidate(
                module="typing_extensions",
                level=0,
                attribute="override",
                star=False,
            ),
        ),
    }
    import_bindings = tuple(
        binding for binding in policy.imports if binding.name == name
    )
    expected_required = name == "TypedDict"
    expected_overwritten = name != "TypedDict"
    if (
        len(import_bindings) != 1
        or import_bindings[0].required is not expected_required
        or import_bindings[0].may_be_overwritten is not expected_overwritten
        or import_bindings[0].candidates != expected_candidates[name]
        or import_bindings[0].overwrite_candidates
    ):
        raise MutationToolchainError(
            "reviewed Hypothesis compat import topology changed"
        )
    _verify_eager_provider_attribute("typing", typing_module, name)
    provider_value = vars(typing_module).get(
        name,
        _EAGER_ATTRIBUTE_MISSING,
    )
    if (
        provider_value is _EAGER_ATTRIBUTE_MISSING
        or vars(module).get(name) is not provider_value
        or value is not provider_value
    ):
        raise MutationToolchainError(
            "reviewed Hypothesis compat import identity changed"
        )
    selected = tuple(
        candidate
        for candidate in candidates
        if (
            candidate[0] == "typing"
            and candidate[1] is typing_module
            and candidate[2] == name
            and candidate[3] is provider_value
        )
    )
    expected_provider_count = 2 if name == "TypedDict" else 1
    if len(selected) != expected_provider_count:
        raise MutationToolchainError(
            "reviewed Hypothesis compat import provider is ambiguous"
        )
    return selected[0]


def _runtime_import_sentinels(
    module: ModuleType,
    *,
    policy: _SourceCodePolicy,
    expected: Sequence[_RuntimeImportSentinel] | None = None,
) -> tuple[_RuntimeImportSentinel, ...]:
    missing = object()
    grouped: dict[
        str,
        list[tuple[str, ModuleType, str | None, object]],
    ] = {}
    required: dict[str, bool] = {}
    overwritten: dict[str, bool] = {}
    for binding in policy.imports:
        if binding.name == "*":
            for candidate in binding.candidates:
                provider_name = _absolute_import_name(module, candidate)
                provider = sys.modules.get(provider_name)
                if not isinstance(provider, ModuleType):
                    if binding.required:
                        raise MutationToolchainError(
                            "loaded source star-import provider is missing: "
                            f"{module.__name__} -> {provider_name}"
                        )
                    continue
                for name in _static_star_export_names(provider):
                    _verify_eager_provider_attribute(
                        provider_name,
                        provider,
                        name,
                    )
                    grouped.setdefault(name, []).append(
                        (provider_name, provider, name, vars(provider)[name])
                    )
                    required[name] = required.get(name, False) or binding.required
                    overwritten[name] = (
                        overwritten.get(name, False)
                        or binding.may_be_overwritten
                    )
            continue
        grouped.setdefault(binding.name, [])
        required[binding.name] = binding.required
        overwritten[binding.name] = binding.may_be_overwritten
        for candidate in binding.candidates:
            provider_name = _absolute_import_name(module, candidate)
            provider = sys.modules.get(provider_name)
            if not isinstance(provider, ModuleType):
                continue
            if candidate.attribute is None:
                provider_value: object = provider
            else:
                _verify_eager_provider_attribute(
                    provider_name,
                    provider,
                    candidate.attribute,
                )
                provider_value = vars(provider).get(candidate.attribute, missing)
                if provider_value is missing:
                    submodule_name = f"{provider_name}.{candidate.attribute}"
                    submodule = sys.modules.get(submodule_name)
                    if isinstance(submodule, ModuleType):
                        provider_value = submodule
                    else:
                        continue
            grouped.setdefault(binding.name, []).append(
                (
                    provider_name,
                    provider,
                    candidate.attribute,
                    provider_value,
                )
            )

    sentinels: list[_RuntimeImportSentinel] = []
    expected_by_name = {
        item.name: item for item in expected or ()
    }

    def exact_source_overwrite_kind(
        binding: _SourceImportBinding,
        value: object,
    ) -> str | None:
        for candidate in binding.overwrite_candidates:
            if (
                candidate.kind == "builtin"
                and isinstance(candidate.value, str)
                and vars(builtins).get(candidate.value) is value
            ):
                return f"builtin:{candidate.value}"
            if (
                candidate.kind == "literal"
                and _runtime_value_shape(value) == candidate.value
            ):
                return "literal"
        for source_binding in policy.bindings:
            if source_binding.path != (binding.name,):
                continue
            expected_qualnames = {
                candidate.qualname
                for candidate in source_binding.candidates
            }
            if source_binding.kind == "class" and (
                inspect.isclass(value)
                and value.__module__ == module.__name__
                and value.__qualname__ in expected_qualnames
            ):
                return "sealed-source-class"
            if source_binding.kind == "function" and (
                type(value) is FunctionType
                and value.__module__ == module.__name__
                and value.__qualname__ in expected_qualnames
                and value.__code__.co_qualname in expected_qualnames
            ):
                return "sealed-source-function"
        return None

    def exact_deleted_import_is_admitted(name: str) -> bool:
        admitted = _ADMITTED_DELETED_IMPORT_BINDINGS.get(module.__name__)
        module_type = type(module)
        return (
            admitted is not None
            and name in admitted
            and sys.modules.get(module.__name__) is module
            and module_type.__module__ == module.__name__
            and module_type.__qualname__ == "_automodule"
            and vars(module).get("_automodule") is module_type
            and name not in vars(module)
        )

    bindings_by_name = {
        binding.name: binding
        for binding in policy.imports
        if binding.name != "*"
    }
    for name, candidates in sorted(grouped.items()):
        value = vars(module).get(name, missing)
        if value is missing:
            if exact_deleted_import_is_admitted(name):
                continue
            if required.get(name, False) and not overwritten.get(name, False):
                raise MutationToolchainError(
                    f"loaded source import binding is missing: {module.__name__}.{name}"
                )
            continue
        matches = [candidate for candidate in candidates if value is candidate[3]]
        prior = expected_by_name.get(name)
        selected = _exact_hypothesis_compat_import_candidate(
            module,
            policy=policy,
            name=name,
            value=value,
            candidates=matches,
        )
        if selected is None:
            selected = next(
                (
                    candidate
                    for candidate in matches
                    if (
                        prior is not None
                        and prior.provider_name == candidate[0]
                        and prior.provider is candidate[1]
                        and prior.provider_attribute == candidate[2]
                        and prior.provider_value is candidate[3]
                    )
                ),
                matches[0] if matches else None,
            )
        if selected is None:
            binding = bindings_by_name[name]
            overwrite_kind = (
                exact_source_overwrite_kind(binding, value)
                if overwritten.get(name, False)
                else None
            )
            if overwrite_kind is not None:
                code = value.__code__ if isinstance(value, FunctionType) else None
                sentinels.append(
                    _RuntimeImportSentinel(
                        name=name,
                        value=value,
                        provider_name=None,
                        provider=None,
                        provider_attribute=overwrite_kind,
                        provider_value=value,
                        callable_code=code,
                        callable_code_sha256=(
                            _normalized_code_sha256(code)
                            if code is not None
                            else None
                        ),
                    )
                )
                continue
            raise MutationToolchainError(
                f"loaded source import binding changed: {module.__name__}.{name}"
            )
        provider_name, provider, attribute, provider_value = selected
        code = value.__code__ if isinstance(value, FunctionType) else None
        sentinels.append(
            _RuntimeImportSentinel(
                name=name,
                value=value,
                provider_name=provider_name,
                provider=provider,
                provider_attribute=attribute,
                provider_value=provider_value,
                callable_code=code,
                callable_code_sha256=(
                    _normalized_code_sha256(code) if code is not None else None
                ),
            )
        )
    for binding in policy.imports:
        if binding.name == "*" or binding.name in grouped:
            continue
        value = vars(module).get(binding.name, missing)
        if (
            binding.required
            and not binding.may_be_overwritten
            and value is missing
        ):
            if exact_deleted_import_is_admitted(binding.name):
                continue
            raise MutationToolchainError(
                "loaded source import provider is missing: "
                f"{module.__name__}.{binding.name}"
            )
        if value is not missing and not binding.may_be_overwritten:
            raise MutationToolchainError(
                f"loaded source import binding changed: {module.__name__}.{binding.name}"
            )
    return tuple(sentinels)


def _source_reference_value(
    module: ModuleType,
    path: tuple[str, ...] | None,
) -> object | None:
    if not path:
        return None
    missing = object()
    value = vars(module).get(path[0], missing)
    if value is missing:
        value = vars(builtins).get(path[0], missing)
    if value is missing:
        return None
    for part in path[1:]:
        try:
            value = vars(value).get(part, missing)
        except TypeError:
            return None
        if value is missing:
            return None
    return value


def _source_plain_class_bases(
    module: ModuleType,
    shape: _SourceClassShape,
) -> tuple[type[object], ...] | None:
    if shape.decorators:
        return None
    if not shape.base_references:
        return (object,)
    bases: list[type[object]] = []
    for reference in shape.base_references:
        value = _source_reference_value(module, reference)
        if not inspect.isclass(value):
            return None
        bases.append(value)
    return tuple(bases)


def _source_plain_class_metaclass(
    module: ModuleType,
    shape: _SourceClassShape,
    bases: tuple[type[object], ...] | None,
) -> type[object] | None:
    if shape.decorators or any(
        name not in {"metaclass"} for name, _value in shape.keywords
    ):
        return None
    if shape.metaclass_reference is not None:
        value = _source_reference_value(module, shape.metaclass_reference)
        return value if inspect.isclass(value) else None
    if bases is None:
        return None
    winner: type[object] = type
    for base in bases:
        candidate = type(base)
        if candidate is winner or candidate in winner.__mro__:
            continue
        if winner in candidate.__mro__:
            winner = candidate
            continue
        return None
    return winner


def _exact_reexport_rewrite_index(
    tree: ast.Module,
    *,
    public_module_name: str,
) -> int | None:
    if type(tree) is not ast.Module or type(public_module_name) is not str:
        return None
    expected = ast.parse(
        "for __value in list(locals().values()):\n"
        "    if getattr(__value, '__module__', '').startswith("
        f"{public_module_name + '.'!r}):\n"
        "        __value.__module__ = __name__\n"
    ).body[0]
    expected_shape = ast.dump(
        expected,
        annotate_fields=True,
        include_attributes=False,
    )
    matches = [
        (index, statement)
        for index, statement in enumerate(tree.body)
        if ast.dump(
            statement,
            annotate_fields=True,
            include_attributes=False,
        )
        == expected_shape
    ]
    if len(matches) != 1:
        return None
    rewrite_index, rewrite_statement = matches[0]
    rewrite_targets = [
        node
        for node in ast.walk(rewrite_statement)
        if type(node) is ast.Attribute
        and node.attr == "__module__"
        and type(node.ctx) is ast.Store
    ]
    all_write_targets = [
        node
        for node in ast.walk(tree)
        if type(node) is ast.Attribute
        and node.attr == "__module__"
        and type(node.ctx) in {ast.Store, ast.Del}
    ]
    rewrite_module_constants = [
        node
        for node in ast.walk(rewrite_statement)
        if type(node) is ast.Constant and node.value == "__module__"
    ]
    all_module_constants = [
        node
        for node in ast.walk(tree)
        if type(node) is ast.Constant and node.value == "__module__"
    ]
    if (
        len(rewrite_targets) != 1
        or len(all_write_targets) != 1
        or all_write_targets[0] is not rewrite_targets[0]
        or len(rewrite_module_constants) != 1
        or len(all_module_constants) != 1
        or all_module_constants[0] is not rewrite_module_constants[0]
    ):
        return None
    return rewrite_index


def _captured_source_module(
    module_name: str,
    module: ModuleType,
    *,
    prefix: Path,
) -> tuple[
    str,
    str,
    ModuleSpec,
    str,
    object,
    _FileIdentity,
    ast.Module,
    _SourceCodePolicy,
] | None:
    captured = _MODULE_OBJECTS_AFTER_DETERMINISTIC_IMPORTS.get(module_name)
    if type(captured) is not tuple or len(captured) != 7:
        return None
    prior = _MODULE_OBJECTS_BEFORE_TOOLCHAIN_IMPORT.get(module_name)
    if prior is not None and prior[0] is not module:
        return None
    (
        captured_module,
        module_name_value,
        module_file,
        specification,
        origin,
        loader,
        _locations,
    ) = captured
    if (
        type(module) is not ModuleType
        or type(module_name) is not str
        or captured_module is not module
        or type(module_name_value) is not str
        or module_name_value != module_name
        or type(module_file) is not str
        or type(specification) is not ModuleSpec
        or type(origin) is not str
    ):
        return None
    namespace = vars(module)
    specification_namespace = vars(specification)
    if (
        namespace.get("__name__") is not module_name_value
        or namespace.get("__file__") is not module_file
        or namespace.get("__spec__") is not specification
        or specification_namespace.get("name") is not module_name_value
        or specification_namespace.get("origin") is not origin
        or specification_namespace.get("loader") is not loader
    ):
        return None
    try:
        source_path = Path(module_file).resolve(strict=True)
        origin_path = Path(origin).resolve(strict=True)
        if source_path != origin_path or source_path.suffix.casefold() not in {
            ".py",
            ".pyw",
        }:
            return None
        raw = _stable_policy_bytes(
            prefix,
            source_path,
            label=f"eager re-export source {module_name}",
        )
        identity = _stable_file_identity(
            prefix,
            source_path,
            label=f"eager re-export source {module_name}",
        )
        tree = ast.parse(raw, filename=os.fspath(source_path), mode="exec")
        policy = _source_code_policy(tree)
    except (MutationToolchainError, OSError, SyntaxError, ValueError):
        return None
    return (
        module_name_value,
        module_file,
        specification,
        origin,
        loader,
        identity,
        tree,
        policy,
    )


def _exact_direct_public_import(
    public_module: ModuleType,
    *,
    tree: ast.Module,
    before_index: int,
    policy: _SourceCodePolicy,
    class_name: str,
    defining_module_name: str,
) -> bool:
    if (
        type(tree) is not ast.Module
        or type(before_index) is not int
        or before_index < 0
    ):
        return False
    bindings = [binding for binding in policy.imports if binding.name == class_name]
    if len(bindings) != 1:
        return False
    binding = bindings[0]
    if (
        not binding.required
        or binding.may_be_overwritten
        or len(binding.candidates) != 1
    ):
        return False
    candidate = binding.candidates[0]
    if candidate.star or candidate.attribute != class_name:
        return False
    try:
        provider_name = _absolute_import_name(public_module, candidate)
    except MutationToolchainError:
        return False
    source_imports = [
        index
        for index, statement in enumerate(tree.body)
        if type(statement) is ast.ImportFrom
        for alias in statement.names
        if (
            type(alias) is ast.alias
            and statement.module == candidate.module
            and statement.level == candidate.level
            and alias.name == class_name
            and (alias.asname or alias.name) == class_name
        )
    ]
    return (
        provider_name == defining_module_name
        and len(source_imports) == 1
        and source_imports[0] < before_index
    )


def _exact_anyio_typed_attribute_factory_is_declared(
    tree: ast.Module,
    policy: _SourceCodePolicy,
) -> bool:
    def write_count(name: str) -> int:
        count = sum(
            isinstance(node, (ast.AsyncFunctionDef, ast.ClassDef, ast.FunctionDef))
            and node.name == name
            for node in ast.walk(tree)
        )
        count += sum(
            isinstance(node, ast.Name)
            and node.id == name
            and isinstance(node.ctx, (ast.Del, ast.Store))
            for node in ast.walk(tree)
        )
        count += sum(
            (
                alias.asname == name
                or (alias.asname is None and alias.name.split(".", 1)[0] == name)
            )
            for node in ast.walk(tree)
            if isinstance(node, (ast.Import, ast.ImportFrom))
            for alias in node.names
        )
        count += sum(
            isinstance(node, ast.arg) and node.arg == name
            for node in ast.walk(tree)
        )
        return count

    bindings = [
        binding
        for binding in policy.bindings
        if binding.path == ("typed_attribute",) and binding.kind == "function"
    ]
    functions = [
        statement
        for statement in tree.body
        if isinstance(statement, ast.FunctionDef)
        and statement.name == "typed_attribute"
    ]
    if len(bindings) != 1 or len(functions) != 1:
        return False
    binding = bindings[0]
    function = functions[0]
    arguments = function.args
    if (
        not binding.required
        or binding.must_be_absent
        or len(binding.candidates) != 1
        or binding.candidates[0].qualname != "typed_attribute"
        or binding.candidates[0].first_line != function.lineno
        or binding.candidates[0].definition_line != function.lineno
        or binding.candidates[0].guards
        or not binding.candidates[0].guards_complete
        or function.decorator_list
        or getattr(function, "type_params", ())
        or arguments.posonlyargs
        or arguments.args
        or arguments.vararg is not None
        or arguments.kwonlyargs
        or arguments.kw_defaults
        or arguments.kwarg is not None
        or arguments.defaults
        or write_count("typed_attribute") != 1
        or write_count("object") != 0
        or len(function.body) != 2
        or not isinstance(function.body[0], ast.Expr)
        or not isinstance(function.body[0].value, ast.Constant)
        or type(function.body[0].value.value) is not str
        or not isinstance(function.body[1], ast.Return)
        or not isinstance(function.body[1].value, ast.Call)
    ):
        return False
    call = function.body[1].value
    return (
        not call.args
        and not call.keywords
        and isinstance(call.func, ast.Name)
        and call.func.id == "object"
    )


def _exact_anyio_typed_attribute_import(
    module: ModuleType,
    *,
    policy: _SourceCodePolicy,
) -> bool:
    if type(module) is not ModuleType:
        return False
    module_name = vars(module).get("__name__")
    if (
        type(module_name) is not str
        or not str.startswith(module_name, "anyio.")
    ):
        return False
    expected_imports = (
        ("typed_attribute", _EAGER_ANYIO_TYPED_ATTRIBUTE),
        ("TypedAttributeSet", _EAGER_ANYIO_TYPED_ATTRIBUTE_SET),
    )
    for binding_name, expected_value in expected_imports:
        bindings = [
            binding for binding in policy.imports if binding.name == binding_name
        ]
        if len(bindings) != 1:
            return False
        binding = bindings[0]
        if (
            not binding.required
            or binding.may_be_overwritten
            or len(binding.candidates) != 1
        ):
            return False
        candidate = binding.candidates[0]
        try:
            provider_name = _absolute_import_name(module, candidate)
        except MutationToolchainError:
            return False
        if (
            provider_name not in {"anyio._core._typedattr", "anyio"}
            or candidate.star
            or candidate.attribute != binding_name
            or vars(module).get(binding_name) is not expected_value
        ):
            return False
    provider = _EAGER_ANYIO_TYPED_ATTRIBUTE
    return (
        sys.modules.get("anyio._core._typedattr")
        is _EAGER_ANYIO_TYPED_ATTRIBUTE_MODULE
        and sys.modules.get("anyio") is _DETERMINISTIC_ANYIO_MODULE
        and vars(_EAGER_ANYIO_TYPED_ATTRIBUTE_MODULE).get("typed_attribute")
        is provider
        and vars(_EAGER_ANYIO_TYPED_ATTRIBUTE_MODULE).get("TypedAttributeSet")
        is _EAGER_ANYIO_TYPED_ATTRIBUTE_SET
        and vars(_DETERMINISTIC_ANYIO_MODULE).get("typed_attribute") is provider
        and vars(_DETERMINISTIC_ANYIO_MODULE).get("TypedAttributeSet")
        is _EAGER_ANYIO_TYPED_ATTRIBUTE_SET
        and type(provider) is FunctionType
        and provider.__code__ is _EAGER_ANYIO_TYPED_ATTRIBUTE_CODE
        and provider.__globals__ is vars(_EAGER_ANYIO_TYPED_ATTRIBUTE_MODULE)
        and provider.__builtins__ is vars(builtins)
        and "object" not in vars(_EAGER_ANYIO_TYPED_ATTRIBUTE_MODULE)
        and vars(builtins).get("object") is _EAGER_OBJECT_TYPE
    )


def _source_class_shape_sha256(shape: _SourceClassShape) -> str:
    return _bounded_normalized_shape_sha256(
        [
            list(shape.path),
            shape.qualname,
            shape.first_line,
            shape.definition_line,
            [
                _sha256_bytes(
                    _canonical_json_bytes(_source_guard_manifest(guard))
                )
                for guard in shape.guards
            ],
            shape.guards_complete,
            list(shape.bases),
            [
                list(reference) if reference is not None else None
                for reference in shape.base_references
            ],
            [list(keyword) for keyword in shape.keywords],
            (
                list(shape.metaclass_reference)
                if shape.metaclass_reference is not None
                else None
            ),
            list(shape.decorators),
            [list(member) for member in shape.members],
            [list(member) for member in shape.literal_members],
            [
                [
                    member.name,
                    list(member.reference),
                    member.assignment_kind,
                    member.annotation,
                    member.simple,
                ]
                for member in shape.zero_arg_call_members
            ],
            [
                [
                    member.name,
                    member.kind,
                    [
                        _sha256_bytes(
                            _canonical_json_bytes(
                                _source_guard_manifest(guard)
                            )
                        )
                        for guard in member.guards
                    ],
                ]
                for member in shape.conditional_members
            ],
            shape.conditional_namespace_complete,
        ]
    )


def _bounded_normalized_shape_sha256(value: object) -> str:
    def prove(item: object, *, depth: int) -> None:
        if depth > 12:
            raise MutationToolchainError(
                "eager re-export shape exceeds bounded depth"
            )
        if item is None or type(item) in {bool, int, str}:
            return
        if type(item) not in {list, tuple}:
            raise MutationToolchainError(
                "eager re-export shape contains a non-normalized value"
            )
        if len(item) > 4096:
            raise MutationToolchainError(
                "eager re-export shape exceeds bounded container size"
            )
        for member in item:
            prove(member, depth=depth + 1)

    prove(value, depth=0)
    return _sha256_bytes(_canonical_json_bytes(value))


def _capture_eager_anyio_typed_attribute_classes(
) -> Mapping[tuple[str, str], _EagerAnyioTypedAttributeClassBinding]:
    prefix = _DETERMINISTIC_IMPORT_PREFIX
    prefix_modules = dict(_PREFIX_MODULES_AFTER_DETERMINISTIC_IMPORTS)
    provider_snapshot = _captured_source_module(
        "anyio._core._typedattr",
        _EAGER_ANYIO_TYPED_ATTRIBUTE_MODULE,
        prefix=prefix,
    )
    if provider_snapshot is None:
        raise RuntimeError("exact AnyIO typed-attribute source is unavailable")
    *_, provider_tree, provider_policy = provider_snapshot
    if not _exact_anyio_typed_attribute_factory_is_declared(
        provider_tree,
        provider_policy,
    ):
        raise RuntimeError("exact AnyIO typed-attribute source is unavailable")

    selected: dict[
        tuple[str, str],
        _EagerAnyioTypedAttributeClassBinding,
    ] = {}
    all_values: list[object] = []
    for module_name, module in sorted(prefix_modules.items()):
        if not module_name.startswith("anyio."):
            continue
        snapshot = _captured_source_module(module_name, module, prefix=prefix)
        if snapshot is None:
            continue
        (
            module_name_value,
            module_file,
            module_specification,
            module_origin,
            module_loader,
            module_identity,
            _tree,
            policy,
        ) = snapshot
        for source_shape in policy.classes:
            typed_members = tuple(
                member
                for member in source_shape.zero_arg_call_members
                if member.reference == ("typed_attribute",)
            )
            if not typed_members:
                continue
            if (
                len(source_shape.path) != 1
                or any(
                    member.assignment_kind != "annassign"
                    or type(member.annotation) is not str
                    or not member.annotation
                    or member.simple != 1
                    for member in typed_members
                )
                or source_shape.base_references
                != (("TypedAttributeSet",),)
                or not _exact_anyio_typed_attribute_import(module, policy=policy)
            ):
                raise RuntimeError(
                    "AnyIO typed-attribute class source is unsupported: "
                    f"{module_name}.{'.'.join(source_shape.path)}"
                )
            class_name = source_shape.path[0]
            source_bindings = [
                binding
                for binding in policy.bindings
                if binding.path == (class_name,) and binding.kind == "class"
            ]
            if len(source_bindings) != 1:
                raise RuntimeError(
                    "AnyIO typed-attribute class binding is unavailable: "
                    f"{module_name}.{class_name}"
                )
            source_binding = source_bindings[0]
            candidate = (
                source_binding.candidates[0]
                if len(source_binding.candidates) == 1
                else None
            )
            value = vars(module).get(class_name)
            if (
                not source_binding.required
                or source_binding.must_be_absent
                or candidate is None
                or candidate.qualname != class_name
                or candidate.first_line != source_shape.first_line
                or candidate.definition_line != source_shape.definition_line
                or candidate.guards
                or not candidate.guards_complete
                or not inspect.isclass(value)
                or type.__getattribute__(value, "__qualname__") != class_name
                or vars(module).get(class_name) is not value
                or type.__getattribute__(value, "__bases__")
                != (_EAGER_ANYIO_TYPED_ATTRIBUTE_SET,)
            ):
                raise RuntimeError(
                    "AnyIO typed-attribute class binding is unavailable: "
                    f"{module_name}.{class_name}"
                )
            namespace = type.__getattribute__(value, "__dict__")
            member_bindings: list[tuple[str, object]] = []
            for source_member in typed_members:
                member = namespace.get(source_member.name, _EAGER_ATTRIBUTE_MISSING)
                if (
                    type(member) is not _EAGER_OBJECT_TYPE
                    or member is _EAGER_ANYIO_TYPED_ATTRIBUTE_UNDEFINED
                ):
                    raise RuntimeError(
                        "AnyIO typed-attribute member is unavailable: "
                        f"{module_name}.{class_name}.{source_member.name}"
                    )
                member_bindings.append((source_member.name, member))
                all_values.append(member)
            selected[(module_name, class_name)] = (
                _EagerAnyioTypedAttributeClassBinding(
                    prefix=prefix,
                    module_name=module_name,
                    module_name_value=module_name_value,
                    module=module,
                    module_file=module_file,
                    module_specification=module_specification,
                    module_origin=module_origin,
                    module_loader=module_loader,
                    module_identity=module_identity,
                    source_shape_sha256=_source_class_shape_sha256(source_shape),
                    class_name=class_name,
                    value=value,
                    members=tuple(member_bindings),
                )
            )
    if any(
        left is right
        for index, left in enumerate(all_values)
        for right in all_values[index + 1 :]
    ):
        raise RuntimeError("AnyIO typed-attribute identities are not unique")
    required = {
        ("anyio.abc._sockets", "SocketAttribute"),
        ("anyio.streams.file", "FileStreamAttribute"),
        ("anyio.streams.tls", "TLSAttribute"),
    }
    if not required.issubset(selected):
        raise RuntimeError("required AnyIO typed-attribute evidence is unavailable")
    return MappingProxyType(selected)


_EAGER_ANYIO_TYPED_ATTRIBUTE_CLASS_BINDINGS = (
    _capture_eager_anyio_typed_attribute_classes()
)


def _capture_eager_abc_registry(
    owner: type[object],
    member: object,
) -> tuple[tuple[ReferenceType, type[object]], ...]:
    owner_namespace = type.__getattribute__(owner, "__dict__")
    if (
        type(owner_namespace) is not MappingProxyType
        or sys.modules.get("abc") is not _EAGER_ABC_MODULE
        or sys.modules.get("_abc") is not _EAGER_NATIVE_ABC_MODULE
        or sys.modules.get("weakref") is not _EAGER_WEAKREF_MODULE
        or vars(_EAGER_NATIVE_ABC_MODULE).get("_get_dump")
        is not _EAGER_ABC_GET_DUMP
        or vars(_EAGER_WEAKREF_MODULE).get("ReferenceType") is not ReferenceType
        or vars(ReferenceType).get("__call__") is not _EAGER_WEAKREF_CALL
        or owner_namespace.get("_abc_impl", _EAGER_ATTRIBUTE_MISSING)
        is not member
        or type(member) is not _EAGER_ABC_DATA_TYPE
    ):
        raise MutationToolchainError("eager ABC registry provider graph changed")
    dump = _EAGER_ABC_GET_DUMP(owner)
    if type(dump) is not tuple or len(dump) != 4:
        raise MutationToolchainError("eager ABC registry dump is invalid")
    registry = tuple.__getitem__(dump, 0)
    if type(registry) is not set:
        raise MutationToolchainError("eager ABC registry is not an exact set")
    entries: list[tuple[ReferenceType, type[object]]] = []
    for reference in registry:
        if type(reference) is not ReferenceType:
            raise MutationToolchainError(
                "eager ABC registry contains a non-weakref entry"
            )
        referent = _EAGER_WEAKREF_CALL(reference)
        if referent is None or not _is_runtime_class(referent):
            raise MutationToolchainError(
                "eager ABC registry weakref has no exact class referent"
            )
        entries.append((reference, referent))
    return tuple(entries)


def _exact_eager_abc_registry_matches(
    owner: type[object],
    member: object,
    expected: tuple[tuple[ReferenceType, type[object]], ...],
) -> bool:
    try:
        current = _capture_eager_abc_registry(owner, member)
    except (MutationToolchainError, TypeError):
        return False
    return len(current) == len(expected) and all(
        any(
            current_reference is expected_reference
            and current_referent is expected_referent
            for current_reference, current_referent in current
        )
        for expected_reference, expected_referent in expected
    )


def _capture_eager_reexported_classes(
) -> Mapping[tuple[str, str], _EagerReexportedClassBinding]:
    prefix = _DETERMINISTIC_IMPORT_PREFIX
    prefix_modules = {
        name: module for name, module in _PREFIX_MODULES_AFTER_DETERMINISTIC_IMPORTS
    }
    captured_anyio = _MODULE_OBJECTS_AFTER_DETERMINISTIC_IMPORTS.get("anyio")
    prefix_anyio = [
        module
        for name, module in _PREFIX_MODULES_AFTER_DETERMINISTIC_IMPORTS
        if name == "anyio"
    ]
    if (
        type(_DETERMINISTIC_ANYIO_MODULE) is not ModuleType
        or sys.modules.get("anyio") is not _DETERMINISTIC_ANYIO_MODULE
        or type(captured_anyio) is not tuple
        or len(captured_anyio) != 7
        or captured_anyio[0] is not _DETERMINISTIC_ANYIO_MODULE
        or prefix_anyio != [_DETERMINISTIC_ANYIO_MODULE]
        or prefix_modules.get("anyio") is not _DETERMINISTIC_ANYIO_MODULE
    ):
        raise RuntimeError("deterministic AnyIO module cohort is unavailable")
    source_cache: dict[
        str,
        tuple[
            str,
            str,
            ModuleSpec,
            str,
            object,
            _FileIdentity,
            ast.Module,
            _SourceCodePolicy,
        ]
        | None,
    ] = {}

    def source_snapshot(
        module_name: str,
        module: ModuleType,
    ) -> tuple[
        str,
        str,
        ModuleSpec,
        str,
        object,
        _FileIdentity,
        ast.Module,
        _SourceCodePolicy,
    ] | None:
        if module_name not in source_cache:
            source_cache[module_name] = _captured_source_module(
                module_name,
                module,
                prefix=prefix,
            )
        return source_cache[module_name]

    selected: dict[tuple[str, str], _EagerReexportedClassBinding] = {}
    for defining_module_name, defining_module in sorted(prefix_modules.items()):
        root_name = defining_module_name.split(".", 1)[0]
        if root_name not in _ADMITTED_CLASS_MODULE_REEXPORT_ROOTS:
            continue
        defining_snapshot = source_snapshot(
            defining_module_name,
            defining_module,
        )
        if defining_snapshot is None:
            continue
        (
            defining_module_name_value,
            defining_file,
            defining_specification,
            defining_origin,
            defining_loader,
            defining_identity,
            _defining_tree,
            defining_policy,
        ) = defining_snapshot
        source_shape_candidates: dict[str, list[_SourceClassShape]] = {}
        for shape in defining_policy.classes:
            if len(shape.path) == 1:
                source_shape_candidates.setdefault(shape.path[0], []).append(
                    shape
                )
        source_shapes = {
            class_name: shapes[0]
            for class_name, shapes in source_shape_candidates.items()
            if len(shapes) == 1
        }
        required_classes = {
            binding.path[0]
            for binding in defining_policy.bindings
            if (
                binding.kind == "class"
                and binding.required
                and binding.path
                and len(binding.path) == 1
            )
        }
        for class_name in sorted(required_classes & source_shapes.keys()):
            value = vars(defining_module).get(class_name)
            if not inspect.isclass(value) or value.__qualname__ != class_name:
                continue
            public_module_name = value.__module__
            if (
                public_module_name == defining_module_name
                or not defining_module_name.startswith(f"{public_module_name}.")
                or public_module_name.split(".", 1)[0] != root_name
            ):
                continue
            public_module = prefix_modules.get(public_module_name)
            if not isinstance(public_module, ModuleType):
                continue
            public_snapshot = source_snapshot(public_module_name, public_module)
            if public_snapshot is None:
                continue
            (
                public_module_name_value,
                public_file,
                public_specification,
                public_origin,
                public_loader,
                public_identity,
                public_tree,
                public_policy,
            ) = public_snapshot
            rewrite_index = _exact_reexport_rewrite_index(
                public_tree,
                public_module_name=public_module_name,
            )
            if (
                vars(public_module).get(class_name) is not value
                or rewrite_index is None
                or not _exact_direct_public_import(
                    public_module,
                    tree=public_tree,
                    before_index=rewrite_index,
                    policy=public_policy,
                    class_name=class_name,
                    defining_module_name=defining_module_name,
                )
            ):
                continue
            source_shape = source_shapes[class_name]
            typed_attribute_record = (
                _EAGER_ANYIO_TYPED_ATTRIBUTE_CLASS_BINDINGS.get(
                    (defining_module_name, class_name)
                )
            )
            typed_attribute_members = (
                dict(typed_attribute_record.members)
                if typed_attribute_record is not None
                else {}
            )
            try:
                captured_members: list[tuple[str, object, str | None]] = []
                abc_registry: tuple[
                    tuple[ReferenceType, type[object]],
                    ...,
                ] | None = None
                for name, member in sorted(vars(value).items()):
                    if name == "_abc_impl" and type(member) is _EAGER_ABC_DATA_TYPE:
                        shape_sha256: str | None = None
                        abc_registry = _capture_eager_abc_registry(value, member)
                    elif (
                        typed_attribute_members.get(
                            name,
                            _EAGER_ATTRIBUTE_MISSING,
                        )
                        is member
                    ):
                        shape_sha256 = _ANYIO_TYPED_ATTRIBUTE_MEMBER_MARKER
                    else:
                        shape_sha256 = _sha256_bytes(
                            _canonical_json_bytes(
                                _runtime_value_shape(member)
                            )
                        )
                    captured_members.append((name, member, shape_sha256))
                members = tuple(captured_members)
            except MutationToolchainError:
                continue
            selected[(defining_module_name, class_name)] = (
                _EagerReexportedClassBinding(
                    prefix=prefix,
                    defining_module_name=defining_module_name,
                    defining_module_name_value=defining_module_name_value,
                    defining_module=defining_module,
                    defining_file=defining_file,
                    defining_specification=defining_specification,
                    defining_origin=defining_origin,
                    defining_loader=defining_loader,
                    defining_identity=defining_identity,
                    source_shape_sha256=_source_class_shape_sha256(
                        source_shape
                    ),
                    original_module_name=defining_module_name,
                    public_module_name=public_module_name,
                    public_module_name_value=public_module_name_value,
                    public_module=public_module,
                    public_file=public_file,
                    public_specification=public_specification,
                    public_origin=public_origin,
                    public_loader=public_loader,
                    public_identity=public_identity,
                    public_alias=class_name,
                    value=value,
                    qualname=class_name,
                    metaclass=type(value),
                    bases=value.__bases__,
                    members=members,
                    abc_registry=abc_registry,
                )
            )
    required_public_aliases = {
        ("anyio", "AsyncFile"),
        ("anyio.abc", "SocketAttribute"),
    }
    captured_public_aliases = {
        (record.public_module_name, record.public_alias)
        for record in selected.values()
    }
    if not required_public_aliases.issubset(captured_public_aliases):
        raise RuntimeError("required AnyIO re-export evidence is unavailable")
    return MappingProxyType(selected)


_EAGER_REEXPORTED_CLASS_BINDINGS = _capture_eager_reexported_classes()


def _exact_eager_anyio_typed_attribute_member(
    module: ModuleType,
    owner: type[object],
    *,
    path: str,
    name: str,
    member: object,
    source_shape: _SourceClassShape,
) -> bool:
    module_name = vars(module).get("__name__")
    if type(module_name) is not str or type(source_shape) is not _SourceClassShape:
        return False
    try:
        owner_qualname = type.__getattribute__(owner, "__qualname__")
        owner_bases = type.__getattribute__(owner, "__bases__")
        owner_namespace = type.__getattribute__(owner, "__dict__")
    except TypeError:
        return False
    if (
        type(owner_qualname) is not str
        or type(owner_bases) is not tuple
        or type(owner_namespace) is not MappingProxyType
    ):
        return False
    record = _EAGER_ANYIO_TYPED_ATTRIBUTE_CLASS_BINDINGS.get(
        (module_name, owner_qualname)
    )
    if (
        record is None
        or record.module is not module
        or record.value is not owner
        or record.class_name != path
        or record.source_shape_sha256 != _source_class_shape_sha256(source_shape)
        or owner_bases != (_EAGER_ANYIO_TYPED_ATTRIBUTE_SET,)
        or vars(module).get(record.class_name) is not owner
        or not _captured_module_metadata_matches(
            module,
            module_name=record.module_name,
            module_name_value=record.module_name_value,
            module_file=record.module_file,
            specification=record.module_specification,
            origin=record.module_origin,
            loader=record.module_loader,
        )
        or type(member) is not _EAGER_OBJECT_TYPE
        or member is _EAGER_ANYIO_TYPED_ATTRIBUTE_UNDEFINED
        or sys.modules.get("anyio._core._typedattr")
        is not _EAGER_ANYIO_TYPED_ATTRIBUTE_MODULE
        or sys.modules.get("anyio") is not _DETERMINISTIC_ANYIO_MODULE
        or type(_DETERMINISTIC_ANYIO_MODULE) is not ModuleType
        or vars(_EAGER_ANYIO_TYPED_ATTRIBUTE_MODULE).get("typed_attribute")
        is not _EAGER_ANYIO_TYPED_ATTRIBUTE
        or vars(_EAGER_ANYIO_TYPED_ATTRIBUTE_MODULE).get("TypedAttributeSet")
        is not _EAGER_ANYIO_TYPED_ATTRIBUTE_SET
        or vars(_EAGER_ANYIO_TYPED_ATTRIBUTE_MODULE).get("undefined")
        is not _EAGER_ANYIO_TYPED_ATTRIBUTE_UNDEFINED
        or vars(_DETERMINISTIC_ANYIO_MODULE).get("typed_attribute")
        is not _EAGER_ANYIO_TYPED_ATTRIBUTE
        or vars(_DETERMINISTIC_ANYIO_MODULE).get("TypedAttributeSet")
        is not _EAGER_ANYIO_TYPED_ATTRIBUTE_SET
        or vars(module).get("typed_attribute")
        is not _EAGER_ANYIO_TYPED_ATTRIBUTE
        or _EAGER_ANYIO_TYPED_ATTRIBUTE.__code__
        is not _EAGER_ANYIO_TYPED_ATTRIBUTE_CODE
        or _EAGER_ANYIO_TYPED_ATTRIBUTE.__globals__
        is not vars(_EAGER_ANYIO_TYPED_ATTRIBUTE_MODULE)
        or _EAGER_ANYIO_TYPED_ATTRIBUTE.__name__ != "typed_attribute"
        or _EAGER_ANYIO_TYPED_ATTRIBUTE.__qualname__ != "typed_attribute"
        or _EAGER_ANYIO_TYPED_ATTRIBUTE.__module__ != "anyio"
        or "object" in vars(_EAGER_ANYIO_TYPED_ATTRIBUTE_MODULE)
        or vars(builtins).get("object") is not _EAGER_OBJECT_TYPE
    ):
        return False
    try:
        if (
            _stable_file_identity(
                record.prefix,
                Path(record.module_file),
                label=f"eager typed-attribute source {record.module_name}",
            )
            != record.module_identity
        ):
            return False
    except MutationToolchainError:
        return False
    all_members: list[object] = []
    for class_record in _EAGER_ANYIO_TYPED_ATTRIBUTE_CLASS_BINDINGS.values():
        class_namespace = type.__getattribute__(class_record.value, "__dict__")
        for member_name, expected in class_record.members:
            if class_namespace.get(member_name) is not expected:
                return False
            all_members.append(expected)
    return (
        not any(
            left is right
            for index, left in enumerate(all_members)
            for right in all_members[index + 1 :]
        )
        and any(member_name == name and value is member for member_name, value in record.members)
        and owner_namespace.get(name) is member
    )


def _captured_module_metadata_matches(
    module: ModuleType,
    *,
    module_name: str,
    module_name_value: str,
    module_file: str,
    specification: ModuleSpec,
    origin: str,
    loader: object,
) -> bool:
    if (
        type(module) is not ModuleType
        or type(module_name) is not str
        or type(module_name_value) is not str
        or type(module_file) is not str
        or type(specification) is not ModuleSpec
        or type(origin) is not str
    ):
        return False
    namespace = vars(module)
    specification_namespace = vars(specification)
    return (
        sys.modules.get(module_name) is module
        and namespace.get("__name__") is module_name_value
        and namespace.get("__file__") is module_file
        and namespace.get("__spec__") is specification
        and specification_namespace.get("name") is module_name_value
        and specification_namespace.get("origin") is origin
        and specification_namespace.get("loader") is loader
    )


def _exact_reexported_class_module(
    module: ModuleType,
    value: type[object],
    *,
    source_shape: _SourceClassShape,
) -> bool:
    if type(module) is not ModuleType or not _is_runtime_class(value):
        return False
    module_namespace = vars(module)
    module_name_value = module_namespace.get("__name__")
    try:
        value_qualname = type.__getattribute__(value, "__qualname__")
        value_module = type.__getattribute__(value, "__module__")
        value_name = type.__getattribute__(value, "__name__")
        value_bases = type.__getattribute__(value, "__bases__")
        namespace = type.__getattribute__(value, "__dict__")
    except TypeError:
        return False
    if (
        type(module_name_value) is not str
        or type(value_qualname) is not str
        or type(value_module) is not str
        or type(value_name) is not str
        or type(value_bases) is not tuple
        or type(namespace) is not MappingProxyType
    ):
        return False
    record = _EAGER_REEXPORTED_CLASS_BINDINGS.get(
        (module_name_value, value_qualname)
    )
    if record is None:
        return False
    if (
        record.source_shape_sha256 != _source_class_shape_sha256(source_shape)
        or record.original_module_name != record.defining_module_name
        or record.defining_module is not module
        or record.value is not value
        or record.qualname != value_qualname
        or record.public_module_name != value_module
        or record.public_alias != value_name
        or type(value) is not record.metaclass
        or len(value_bases) != len(record.bases)
        or any(
            actual is not expected
            for actual, expected in zip(value_bases, record.bases, strict=True)
        )
        or not _captured_module_metadata_matches(
            module,
            module_name=record.defining_module_name,
            module_name_value=record.defining_module_name_value,
            module_file=record.defining_file,
            specification=record.defining_specification,
            origin=record.defining_origin,
            loader=record.defining_loader,
        )
        or not _captured_module_metadata_matches(
            record.public_module,
            module_name=record.public_module_name,
            module_name_value=record.public_module_name_value,
            module_file=record.public_file,
            specification=record.public_specification,
            origin=record.public_origin,
            loader=record.public_loader,
        )
        or module_namespace.get(record.public_alias) is not value
        or vars(record.public_module).get(record.public_alias) is not value
    ):
        return False
    try:
        if (
            _stable_file_identity(
                record.prefix,
                Path(record.defining_file),
                label=f"eager re-export source {record.defining_module_name}",
            )
            != record.defining_identity
            or _stable_file_identity(
                record.prefix,
                Path(record.public_file),
                label=f"eager re-export source {record.public_module_name}",
            )
            != record.public_identity
        ):
            return False
    except MutationToolchainError:
        return False
    if sorted(namespace) != [name for name, _member, _shape in record.members]:
        return False
    source_path = ".".join(source_shape.path)
    for name, member, shape_sha256 in record.members:
        if namespace.get(name) is not member:
            return False
        try:
            if shape_sha256 is None:
                if (
                    name != "_abc_impl"
                    or type(member) is not _EAGER_ABC_DATA_TYPE
                    or record.abc_registry is None
                    or not _exact_eager_abc_registry_matches(
                        value,
                        member,
                        record.abc_registry,
                    )
                ):
                    return False
                _runtime_source_class_member_shape(
                    module,
                    value,
                    path=source_path,
                    name=name,
                    member=member,
                )
            elif shape_sha256 == _ANYIO_TYPED_ATTRIBUTE_MEMBER_MARKER:
                if not _exact_eager_anyio_typed_attribute_member(
                    module,
                    value,
                    path=source_path,
                    name=name,
                    member=member,
                    source_shape=source_shape,
                ):
                    return False
            elif (
                _sha256_bytes(
                    _canonical_json_bytes(
                        _runtime_value_shape(namespace[name])
                    )
                )
                != shape_sha256
            ):
                return False
        except MutationToolchainError:
            return False
    return True


def _source_runtime_member_name(class_name: str, source_name: str) -> str:
    if (
        source_name.startswith("__")
        and not source_name.endswith("__")
        and class_name.lstrip("_")
    ):
        return f"_{class_name.lstrip('_')}{source_name}"
    return source_name


def _eager_class_namespace_keys(
    module: ModuleType,
    value: type[object],
    *,
    path: str,
) -> tuple[str, ...] | None:
    if "." in path:
        return None
    matches = [
        keys
        for (
            module_name,
            captured_module,
            attribute,
            captured_class,
            keys,
            _abc_impl,
        ) in (
            _CLASS_NAMESPACES_AFTER_DETERMINISTIC_IMPORTS
        )
        if (
            module_name == module.__name__
            and captured_module is module
            and attribute == path
            and captured_class is value
        )
    ]
    if len(matches) != 1:
        return None
    if sys.modules.get(module.__name__) is not module or vars(module).get(path) is not value:
        raise MutationToolchainError(
            f"loaded source class binding changed: {module.__name__}.{path}"
        )
    return matches[0]


def _eager_class_abc_impl(
    module: ModuleType,
    value: type[object],
    *,
    path: str,
) -> object:
    if "." in path:
        return _EAGER_ATTRIBUTE_MISSING
    matches = [
        abc_impl
        for (
            module_name,
            captured_module,
            attribute,
            captured_class,
            _keys,
            abc_impl,
        ) in _CLASS_NAMESPACES_AFTER_DETERMINISTIC_IMPORTS
        if (
            module_name == module.__name__
            and captured_module is module
            and attribute == path
            and captured_class is value
        )
    ]
    if len(matches) > 1:
        raise MutationToolchainError(
            f"eager source ABC class binding is ambiguous: {module.__name__}.{path}"
        )
    return matches[0] if matches else _EAGER_ATTRIBUTE_MISSING


def _has_exact_abcmeta_derived_metaclass(value: type[object]) -> bool:
    metaclass = type(value)
    try:
        metaclass_mro = type.__getattribute__(metaclass, "__mro__")
    except Exception:
        return False
    if (
        type(metaclass_mro) is not tuple
        or not any(base is _EAGER_ABC_META for base in metaclass_mro)
    ):
        return False
    module_name, qualname = _exact_runtime_class_metadata(metaclass)
    return _exact_module_qualname_binding(module_name, qualname) is metaclass


def _compare_source_version_tuple(
    actual: tuple[int | str, ...],
    operator: str,
    expected: tuple[int | str, ...],
) -> bool:
    if (
        not actual
        or not expected
        or any(type(item) not in {int, str} for item in (*actual, *expected))
    ):
        raise MutationToolchainError(
            "sealed source class version comparison is not a literal version tuple"
        )
    try:
        if operator == "eq":
            return actual == expected
        if operator == "gt":
            return actual > expected
        if operator == "ge":
            return actual >= expected
        if operator == "lt":
            return actual < expected
        if operator == "le":
            return actual <= expected
        if operator == "ne":
            return actual != expected
    except TypeError as exc:
        raise MutationToolchainError(
            "sealed source class version comparison is not orderable"
        ) from exc
    raise MutationToolchainError(
        f"sealed source class version comparison is unsupported: {operator}"
    )


def _source_literal_slot_names(
    module: ModuleType,
    *,
    path: str,
    source_shape: _SourceClassShape,
) -> tuple[str, ...]:
    if not any(name == "__slots__" for name, _kind in source_shape.members):
        return ()
    matches = [
        shape
        for name, shape in source_shape.literal_members
        if name == "__slots__"
    ]
    if len(matches) != 1:
        raise MutationToolchainError(
            "loaded source class slots are not an exact literal: "
            f"{module.__name__}.{path}"
        )
    literal = matches[0]
    if (
        type(literal) is list
        and len(literal) == 2
        and literal[0] == "str"
        and isinstance(literal[1], str)
    ):
        return (literal[1],)
    if not (
        type(literal) is list
        and len(literal) == 2
        and literal[0] in {"list", "tuple"}
        and type(literal[1]) is list
    ):
        raise MutationToolchainError(
            "loaded source class slots have an unsupported literal shape: "
            f"{module.__name__}.{path}"
        )
    names: list[str] = []
    for item in literal[1]:
        if not (
            type(item) is list
            and len(item) == 2
            and item[0] == "str"
            and isinstance(item[1], str)
        ):
            raise MutationToolchainError(
                "loaded source class slots contain a non-string literal: "
                f"{module.__name__}.{path}"
            )
        names.append(item[1])
    return tuple(names)


def _verify_source_slot_descriptors(
    module: ModuleType,
    value: type[object],
    *,
    path: str,
    source_shape: _SourceClassShape,
) -> tuple[str, ...]:
    names = _source_literal_slot_names(
        module,
        path=path,
        source_shape=source_shape,
    )
    if names:
        types_module = sys.modules.get("types")
        if not isinstance(types_module, ModuleType):
            raise MutationToolchainError(
                "loaded source slot descriptor provider is missing"
            )
        _verify_eager_provider_attribute(
            "types",
            types_module,
            "MemberDescriptorType",
        )
        _verify_eager_provider_attribute(
            "types",
            types_module,
            "GetSetDescriptorType",
        )
        if (
            vars(types_module).get("MemberDescriptorType")
            is not MemberDescriptorType
            or vars(types_module).get("GetSetDescriptorType")
            is not GetSetDescriptorType
        ):
            raise MutationToolchainError(
                "loaded source slot descriptor provider changed"
            )
    namespace = vars(value)
    for source_name in names:
        runtime_name = _source_runtime_member_name(value.__name__, source_name)
        member = namespace.get(runtime_name)
        expected_type = (
            GetSetDescriptorType
            if source_name in {"__dict__", "__weakref__"}
            else MemberDescriptorType
        )
        if (
            type(member) is not expected_type
            or member.__name__ != runtime_name
            or member.__objclass__ is not value
        ):
            raise MutationToolchainError(
                "loaded source slot descriptor changed: "
                f"{module.__name__}.{path}.{runtime_name}"
            )
    return tuple(
        _source_runtime_member_name(value.__name__, name) for name in names
    )


def _exact_direct_protocol_generated_names(
    module: ModuleType,
    value: type[object],
    *,
    path: str,
    source_shape: _SourceClassShape,
) -> tuple[str, ...]:
    if type(value) is not _EAGER_PROTOCOL_META:
        return ()
    expected_bases = _source_plain_class_bases(module, source_shape)
    actual_bases = type.__getattribute__(value, "__bases__")
    if (
        expected_bases is None
        or len(expected_bases) != 1
        or expected_bases[0] is not _EAGER_PROTOCOL_CLASS
        or type(actual_bases) is not tuple
        or len(actual_bases) != 1
        or actual_bases[0] is not _EAGER_PROTOCOL_CLASS
        or source_shape.conditional_members
    ):
        raise MutationToolchainError(
            "loaded source Protocol shape is outside the exact direct-Protocol "
            f"policy: {module.__name__}.{path}"
        )
    if (
        sys.modules.get("typing") is not _EAGER_TYPING_MODULE
        or vars(_EAGER_TYPING_MODULE).get("Protocol") is not _EAGER_PROTOCOL_CLASS
        or vars(_EAGER_TYPING_MODULE).get("_ProtocolMeta")
        is not _EAGER_PROTOCOL_META
        or vars(_EAGER_TYPING_MODULE).get("_no_init_or_replace_init")
        is not _EAGER_PROTOCOL_INIT
        or vars(_EAGER_TYPING_MODULE).get("_proto_hook")
        is not _EAGER_PROTOCOL_HOOK
    ):
        raise MutationToolchainError(
            f"loaded source Protocol provider changed: {module.__name__}.{path}"
        )
    for provider_name in (
        "Protocol",
        "_ProtocolMeta",
        "_no_init_or_replace_init",
        "_proto_hook",
    ):
        _verify_eager_provider_attribute(
            "typing",
            _EAGER_TYPING_MODULE,
            provider_name,
        )

    namespace = vars(value)
    protocol_attrs = namespace.get("__protocol_attrs__")
    annotations_cache = namespace.get("__annotations_cache__")
    parameters = namespace.get("__parameters__")
    expected_protocol_attrs = sorted(
        {
            _source_runtime_member_name(value.__name__, name)
            for name, _kind in source_shape.members
        }
    )
    if (
        namespace.get("_is_protocol") is not True
        or namespace.get("__init__") is not _EAGER_PROTOCOL_INIT
        or namespace.get("__subclasshook__") is not _EAGER_PROTOCOL_HOOK
        or type(protocol_attrs) is not set
        or not all(type(name) is str for name in protocol_attrs)
        or sorted(protocol_attrs) != expected_protocol_attrs
        or type(parameters) is not tuple
        or parameters
        or type(annotations_cache) is not dict
        or annotations_cache
    ):
        raise MutationToolchainError(
            f"loaded source Protocol generated state changed: {module.__name__}.{path}"
        )
    return (
        "__annotations_cache__",
        "__init__",
        "__parameters__",
        "__protocol_attrs__",
        "__subclasshook__",
        "_is_protocol",
    )


def _exact_source_version_guard(
    module: ModuleType,
    *,
    policy: _SourceCodePolicy,
    guard: _SourceVersionGuard,
    _tuple_type: type[tuple[object, ...]] = tuple,
    _int_type: type[int] = int,
    _str_type: type[str] = str,
    _bool_type: type[bool] = bool,
) -> bool:
    if (
        type(guard.operator) is not _str_type
        or type(guard.version) is not _tuple_type
        or not guard.version
        or any(type(part) not in {_int_type, _str_type} for part in guard.version)
        or type(guard.branch) is not _bool_type
    ):
        raise MutationToolchainError("sealed source class version guard is invalid")
    if vars(builtins).get("tuple") is not _tuple_type:
        raise MutationToolchainError(
            "loaded source class version tuple provider changed"
        )
    imports = [binding for binding in policy.imports if binding.name == "sys"]
    if (
        len(imports) != 1
        or imports[0].may_be_overwritten
        or not any(
            candidate.module == "sys"
            and candidate.level == 0
            and candidate.attribute is None
            and not candidate.star
            for candidate in imports[0].candidates
        )
        or vars(module).get("sys") is not sys
        or sys.modules.get("sys") is not sys
    ):
        raise MutationToolchainError(
            f"loaded source class version provider changed: {module.__name__}.sys"
        )
    _verify_eager_provider_attribute("sys", sys, "version_info")
    eager = _eager_module_namespace_entry("sys", sys, "version_info")
    if (
        not isinstance(eager, _EagerNamespaceEntry)
        or eager.value is not sys.version_info
    ):
        raise MutationToolchainError(
            "loaded source class version provider is not eagerly sealed"
        )
    actual = _tuple_type(sys.version_info)
    result = _compare_source_version_tuple(actual, guard.operator, guard.version)
    return result is guard.branch


def _exact_source_version_prefix_guard(
    module: ModuleType,
    *,
    policy: _SourceCodePolicy,
    guard: _SourceVersionPrefixGuard,
    _tuple_type: type[tuple[object, ...]] = tuple,
    _int_type: type[int] = int,
    _str_type: type[str] = str,
    _bool_type: type[bool] = bool,
) -> bool:
    if (
        type(guard.operator) is not _str_type
        or type(guard.width) is not _int_type
        or guard.width <= 0
        or type(guard.version) is not _tuple_type
        or tuple.__len__(guard.version) != guard.width
        or any(
            type(part) is not _int_type or part < 0
            for part in guard.version
        )
        or type(guard.branch) is not _bool_type
    ):
        raise MutationToolchainError(
            "sealed source version-prefix guard is invalid"
        )
    if vars(builtins).get("tuple") is not _tuple_type:
        raise MutationToolchainError(
            "loaded source version-prefix tuple provider changed"
        )
    imports = [binding for binding in policy.imports if binding.name == "sys"]
    if (
        len(imports) != 1
        or imports[0].may_be_overwritten
        or not any(
            candidate.module == "sys"
            and candidate.level == 0
            and candidate.attribute is None
            and not candidate.star
            for candidate in imports[0].candidates
        )
        or vars(module).get("sys") is not sys
        or sys.modules.get("sys") is not sys
    ):
        raise MutationToolchainError(
            "loaded source version-prefix provider changed: "
            f"{module.__name__}.sys"
        )
    _verify_eager_provider_attribute("sys", sys, "version_info")
    eager = _eager_module_namespace_entry("sys", sys, "version_info")
    if (
        not isinstance(eager, _EagerNamespaceEntry)
        or eager.value is not sys.version_info
    ):
        raise MutationToolchainError(
            "loaded source version-prefix provider is not eagerly sealed"
        )
    actual = _tuple_type(sys.version_info)
    prefix = actual[: guard.width]
    if type(prefix) is not _tuple_type or tuple.__len__(prefix) != guard.width:
        raise MutationToolchainError(
            "loaded source version-prefix value changed"
        )
    result = _compare_source_version_tuple(
        prefix,
        guard.operator,
        guard.version,
    )
    return result is guard.branch


def _exact_source_version_range_guard(
    module: ModuleType,
    *,
    policy: _SourceCodePolicy,
    guard: _SourceVersionRangeGuard,
    _tuple_type: type[tuple[object, ...]] = tuple,
    _int_type: type[int] = int,
    _bool_type: type[bool] = bool,
) -> bool:
    if (
        type(guard.lower) is not _tuple_type
        or not guard.lower
        or any(type(part) is not _int_type or part < 0 for part in guard.lower)
        or type(guard.upper) is not _tuple_type
        or not guard.upper
        or any(type(part) is not _int_type or part < 0 for part in guard.upper)
        or type(guard.branch) is not _bool_type
    ):
        raise MutationToolchainError("sealed source class version range guard is invalid")
    lower_active = _exact_source_version_guard(
        module,
        policy=policy,
        guard=_SourceVersionGuard("ge", guard.lower, True),
    )
    upper_active = _exact_source_version_guard(
        module,
        policy=policy,
        guard=_SourceVersionGuard("lt", guard.upper, True),
    )
    result = lower_active and upper_active
    return result is guard.branch


def _exact_source_pytest_version_guard(
    module: ModuleType,
    *,
    policy: _SourceCodePolicy,
    guard: _SourcePytestVersionGuard,
    _tuple_type: type[tuple[object, ...]] = tuple,
    _map_type: type[map] = map,
    _int_type: type[int] = int,
    _str_type: type[str] = str,
) -> bool:
    pytest_module = sys.modules.get("pytest")
    imports = [
        binding for binding in policy.imports if binding.name == "pytest"
    ]
    if (
        type(pytest_module) is not ModuleType
        or len(imports) != 1
        or imports[0].may_be_overwritten
        or not any(
            candidate.module == "pytest"
            and candidate.level == 0
            and candidate.attribute is None
            and not candidate.star
            for candidate in imports[0].candidates
        )
        or vars(module).get("pytest") is not pytest_module
        or any(name in vars(module) for name in ("tuple", "map", "int"))
        or vars(builtins).get("tuple") is not _tuple_type
        or vars(builtins).get("map") is not _map_type
        or vars(builtins).get("int") is not _int_type
        or vars(builtins).get("str") is not _str_type
    ):
        raise MutationToolchainError(
            "loaded source pytest version provider changed: "
            f"{module.__name__}.pytest"
        )
    _verify_eager_provider_attribute(
        "pytest",
        pytest_module,
        "__version__",
    )
    eager = _eager_module_namespace_entry(
        "pytest",
        pytest_module,
        "__version__",
    )
    version = vars(pytest_module).get("__version__")
    if (
        not isinstance(eager, _EagerNamespaceEntry)
        or type(version) is not _str_type
        or eager.value is not version
        or eager.scalar_sha256 != _eager_scalar_sha256(version)
    ):
        raise MutationToolchainError(
            "loaded source pytest version is not eagerly sealed"
        )
    parts = _str_type.split(version, ".")
    if (
        type(parts) is not list
        or len(parts) < 2
        or type(parts[0]) is not _str_type
        or type(parts[1]) is not _str_type
    ):
        raise MutationToolchainError(
            "loaded source pytest version cannot satisfy its sealed guard"
        )
    try:
        actual = (_int_type(parts[0]), _int_type(parts[1]))
    except ValueError as exc:
        raise MutationToolchainError(
            "loaded source pytest version cannot satisfy its sealed guard"
        ) from exc
    result = _compare_source_version_tuple(
        actual,
        guard.operator,
        guard.version,
    )
    return result is guard.branch


def _exact_source_platform_guard(
    module: ModuleType,
    *,
    policy: _SourceCodePolicy,
    guard: _SourcePlatformGuard,
    _str_type: type[str] = str,
) -> bool:
    if (
        type(guard.operator) is not _str_type
        or type(guard.platform) is not _str_type
        or type(guard.branch) is not bool
    ):
        raise MutationToolchainError("sealed source class platform guard is invalid")
    imports = [binding for binding in policy.imports if binding.name == "sys"]
    if (
        len(imports) != 1
        or imports[0].may_be_overwritten
        or not any(
            candidate.module == "sys"
            and candidate.level == 0
            and candidate.attribute is None
            and not candidate.star
            for candidate in imports[0].candidates
        )
        or vars(module).get("sys") is not sys
        or sys.modules.get("sys") is not sys
    ):
        raise MutationToolchainError(
            f"loaded source class platform provider changed: {module.__name__}.sys"
        )
    _verify_eager_provider_attribute("sys", sys, "platform")
    eager = _eager_module_namespace_entry("sys", sys, "platform")
    if (
        not isinstance(eager, _EagerNamespaceEntry)
        or eager.value is not sys.platform
        or type(sys.platform) is not _str_type
    ):
        raise MutationToolchainError(
            "loaded source class platform provider is not eagerly sealed"
        )
    if guard.operator == "eq":
        result = sys.platform == guard.platform
    elif guard.operator == "ne":
        result = sys.platform != guard.platform
    elif guard.operator == "startswith":
        result = _str_type.startswith(sys.platform, guard.platform)
    else:
        raise MutationToolchainError(
            "sealed source class platform comparison is unsupported: "
            f"{guard.operator}"
        )
    return result is guard.branch


def _exact_source_type_checking_guard(
    module: ModuleType,
    *,
    policy: _SourceCodePolicy,
    guard: _SourceTypeCheckingGuard,
) -> bool:
    typing_module = sys.modules.get("typing")
    if not isinstance(typing_module, ModuleType):
        raise MutationToolchainError(
            "loaded source class TYPE_CHECKING provider is missing"
        )
    _verify_eager_provider_attribute(
        "typing",
        typing_module,
        "TYPE_CHECKING",
    )
    eager = _eager_module_namespace_entry(
        "typing",
        typing_module,
        "TYPE_CHECKING",
    )
    if (
        not isinstance(eager, _EagerNamespaceEntry)
        or eager.value is not False
        or eager.scalar_sha256 != _eager_scalar_sha256(False)
        or vars(typing_module).get("TYPE_CHECKING") is not False
    ):
        raise MutationToolchainError(
            "loaded source class TYPE_CHECKING provider is not eagerly sealed False"
        )

    if guard.reference == "direct":
        imports = [
            binding
            for binding in policy.imports
            if binding.name == "TYPE_CHECKING"
        ]
        candidate_is_exact = len(imports) == 1 and any(
            candidate.module == "typing"
            and candidate.level == 0
            and candidate.attribute == "TYPE_CHECKING"
            and not candidate.star
            for candidate in imports[0].candidates
        )
        binding_is_exact = vars(module).get("TYPE_CHECKING") is False
    elif guard.reference == "module":
        imports = [binding for binding in policy.imports if binding.name == "typing"]
        candidate_is_exact = len(imports) == 1 and any(
            candidate.module == "typing"
            and candidate.level == 0
            and candidate.attribute is None
            and not candidate.star
            for candidate in imports[0].candidates
        )
        binding_is_exact = (
            vars(module).get("typing") is typing_module
            and sys.modules.get("typing") is typing_module
        )
    else:
        raise MutationToolchainError(
            "sealed source class TYPE_CHECKING reference is unsupported"
        )
    if (
        len(imports) != 1
        or imports[0].may_be_overwritten
        or not candidate_is_exact
        or not binding_is_exact
    ):
        raise MutationToolchainError(
            "loaded source class TYPE_CHECKING import provider changed: "
            f"{module.__name__}"
        )
    return (False is guard.branch)


def _exact_source_colorama_win32_reviewed_try_guard(
    module: ModuleType,
    *,
    policy: _SourceCodePolicy,
    guard: _SourceReviewedTryGuard,
    _outcome_reader: object = _exact_eager_colorama_win32_try_outcome,
) -> bool:
    if (
        type(_outcome_reader) is not FunctionType
        or _exact_eager_colorama_win32_try_outcome is not _outcome_reader
    ):
        raise MutationToolchainError(
            "eager Colorama reviewed try reader changed"
        )
    record = _outcome_reader()
    if (
        type(guard.policy) is not str
        or type(guard.topology_sha256) is not str
        or guard.policy != _COLORAMA_WIN32_CTYPES_TRY_POLICY
        or type(guard.branch) is not bool
        or type(record) is not _EagerColoramaWin32TryOutcome
        or type(record.policy) is not str
        or type(record.topology_sha256) is not str
        or record.policy != _COLORAMA_WIN32_CTYPES_TRY_POLICY
        or guard.topology_sha256 != record.topology_sha256
        or type(policy.source_ast_sha256) is not str
        or policy.source_ast_sha256 != record.topology_sha256
        or record.succeeded is not True
        or type(module) is not ModuleType
        or module is not record.module
        or sys.modules.get("colorama.win32") is not module
    ):
        raise MutationToolchainError(
            "sealed source reviewed try guard is unavailable"
        )
    for (
        module_name,
        module_name_value,
        expected_module,
        module_file,
        specification,
        origin,
        loader,
    ) in record.module_metadata:
        if not _captured_module_metadata_matches(
            expected_module,
            module_name=module_name,
            module_name_value=module_name_value,
            module_file=module_file,
            specification=specification,
            origin=origin,
            loader=loader,
        ):
            raise MutationToolchainError(
                "loaded source reviewed try module metadata changed"
            )

    expected_imports = {
        "ctypes": ("ctypes", None),
        "LibraryLoader": ("ctypes", "LibraryLoader"),
        "wintypes": ("ctypes", "wintypes"),
        "byref": ("ctypes", "byref"),
        "Structure": ("ctypes", "Structure"),
        "c_char": ("ctypes", "c_char"),
        "POINTER": ("ctypes", "POINTER"),
    }
    if {binding.name for binding in policy.imports} != set(expected_imports):
        raise MutationToolchainError(
            "sealed source reviewed try import set changed"
        )
    for binding in policy.imports:
        expected_module_name, expected_attribute = expected_imports[binding.name]
        if (
            binding.required
            or binding.may_be_overwritten
            or len(binding.candidates) != 1
        ):
            raise MutationToolchainError(
                "sealed source reviewed try import binding changed"
            )
        candidate = binding.candidates[0]
        if (
            candidate.module != expected_module_name
            or candidate.level != 0
            or candidate.attribute != expected_attribute
            or candidate.star
        ):
            raise MutationToolchainError(
                "sealed source reviewed try import candidate changed"
            )

    for provider_name, provider, bindings in (
        ("colorama.win32", module, record.consumer_bindings),
        ("ctypes", record.ctypes_module, record.ctypes_bindings),
        ("ctypes.wintypes", record.wintypes_module, record.wintypes_bindings),
    ):
        if sys.modules.get(provider_name) is not provider:
            raise MutationToolchainError(
                "loaded source reviewed try provider route changed"
            )
        namespace = vars(provider)
        for name, expected in bindings:
            _verify_eager_provider_attribute(provider_name, provider, name)
            if namespace.get(name, _EAGER_ATTRIBUTE_MISSING) is not expected:
                raise MutationToolchainError(
                    "loaded source reviewed try provider binding changed: "
                    f"{provider_name}.{name}"
                )

    def exact_binding(
        bindings: object,
        expected_name: str,
    ) -> object:
        if type(bindings) is not tuple or type(expected_name) is not str:
            raise MutationToolchainError(
                "loaded source reviewed try binding inventory changed"
            )
        selected = _EAGER_ATTRIBUTE_MISSING
        for entry in bindings:
            if (
                type(entry) is not tuple
                or len(entry) != 2
                or type(entry[0]) is not str
            ):
                raise MutationToolchainError(
                    "loaded source reviewed try binding inventory changed"
                )
            if entry[0] == expected_name:
                if selected is not _EAGER_ATTRIBUTE_MISSING:
                    raise MutationToolchainError(
                        "loaded source reviewed try binding is ambiguous"
                    )
                selected = entry[1]
        if selected is _EAGER_ATTRIBUTE_MISSING:
            raise MutationToolchainError(
                "loaded source reviewed try binding is missing"
            )
        return selected

    if (
        type(record.library_loader) is not type
        or type(record.win_dll) is not type
        or type(record.windll) is not record.library_loader
    ):
        raise MutationToolchainError(
            "loaded source reviewed try outcome type changed"
        )
    windll_namespace = object.__getattribute__(record.windll, "__dict__")
    if (
        type(windll_namespace) is not dict
        or type(record.windll_namespace) is not tuple
        or len(windll_namespace) != len(record.windll_namespace)
        or any(type(name) is not str for name in windll_namespace)
        or any(
            type(entry) is not tuple
            or len(entry) != 2
            or type(entry[0]) is not str
            or windll_namespace.get(entry[0], _EAGER_ATTRIBUTE_MISSING)
            is not entry[1]
            for entry in record.windll_namespace
        )
        or windll_namespace.get("_dlltype") is not record.win_dll
        or exact_binding(record.consumer_bindings, "ctypes")
        is not record.ctypes_module
        or exact_binding(record.consumer_bindings, "LibraryLoader")
        is not record.library_loader
        or exact_binding(record.consumer_bindings, "windll") is not record.windll
        or exact_binding(record.consumer_bindings, "wintypes")
        is not record.wintypes_module
        or exact_binding(record.ctypes_bindings, "LibraryLoader")
        is not record.library_loader
        or exact_binding(record.ctypes_bindings, "WinDLL") is not record.win_dll
        or exact_binding(record.ctypes_bindings, "wintypes")
        is not record.wintypes_module
        or exact_binding(record.consumer_bindings, "COORD")
        is not exact_binding(record.wintypes_bindings, "_COORD")
        or any(
            exact_binding(record.consumer_bindings, name)
            is not exact_binding(record.ctypes_bindings, name)
            for name in ("byref", "Structure", "c_char", "POINTER")
        )
    ):
        raise MutationToolchainError(
            "loaded source reviewed try outcome changed"
        )
    return record.succeeded is guard.branch


def _exact_source_colorama_winterm_reviewed_try_guard(
    module: ModuleType,
    *,
    policy: _SourceCodePolicy,
    guard: _SourceReviewedTryGuard,
    _outcome_reader: object = _exact_eager_colorama_winterm_try_outcome,
) -> bool:
    if (
        type(_outcome_reader) is not FunctionType
        or _exact_eager_colorama_winterm_try_outcome is not _outcome_reader
    ):
        raise MutationToolchainError(
            "eager Colorama winterm reviewed try reader changed"
        )
    record = _outcome_reader()
    if (
        type(guard.policy) is not str
        or type(guard.topology_sha256) is not str
        or guard.policy != _COLORAMA_WINTERM_MSVCRT_TRY_POLICY
        or type(guard.branch) is not bool
        or guard.branch is not False
        or type(record) is not _EagerColoramaWintermTryOutcome
        or type(record.policy) is not str
        or type(record.topology_sha256) is not str
        or record.policy != _COLORAMA_WINTERM_MSVCRT_TRY_POLICY
        or guard.topology_sha256 != record.topology_sha256
        or type(policy.source_ast_sha256) is not str
        or policy.source_ast_sha256 != record.topology_sha256
        or record.succeeded is not True
        or type(module) is not ModuleType
        or module is not record.module
        or sys.modules.get("colorama.winterm") is not module
        or type(record.provider) is not ModuleType
        or sys.modules.get("msvcrt") is not record.provider
        or type(record.value) is not BuiltinFunctionType
    ):
        raise MutationToolchainError(
            "sealed source Colorama winterm try guard is unavailable"
        )

    module_metadata = record.module_metadata
    if type(module_metadata) is not tuple or len(module_metadata) != 7:
        raise MutationToolchainError(
            "loaded Colorama winterm module metadata changed"
        )
    (
        module_name,
        module_name_value,
        expected_module,
        module_file,
        module_specification,
        module_origin,
        module_loader,
    ) = module_metadata
    if not _captured_module_metadata_matches(
        expected_module,
        module_name=module_name,
        module_name_value=module_name_value,
        module_file=module_file,
        specification=module_specification,
        origin=module_origin,
        loader=module_loader,
    ):
        raise MutationToolchainError(
            "loaded Colorama winterm module metadata changed"
        )

    provider_namespace = vars(record.provider)
    provider_specification_namespace = vars(record.provider_specification)
    if (
        type(record.provider_name_value) is not str
        or record.provider_name_value != "msvcrt"
        or type(record.provider_specification) is not ModuleSpec
        or type(record.provider_origin) is not str
        or record.provider_origin != "built-in"
        or record.provider_loader is not BuiltinImporter
        or record.provider_file_present is not False
        or record.provider_file is not None
        or provider_namespace.get("__name__")
        is not record.provider_name_value
        or provider_namespace.get("__spec__")
        is not record.provider_specification
        or provider_namespace.get("__loader__") is not record.provider_loader
        or ("__file__" in provider_namespace) is not record.provider_file_present
        or provider_specification_namespace.get("name")
        is not record.provider_name_value
        or provider_specification_namespace.get("origin")
        is not record.provider_origin
        or provider_specification_namespace.get("loader")
        is not record.provider_loader
        or provider_specification_namespace.get("submodule_search_locations")
        is not None
    ):
        raise MutationToolchainError(
            "loaded Colorama winterm provider metadata changed"
        )

    imports = tuple(
        binding
        for binding in policy.imports
        if binding.name == "get_osfhandle"
    )
    if len(imports) != 1:
        raise MutationToolchainError(
            "sealed Colorama winterm import policy changed"
        )
    source_import = imports[0]
    if (
        source_import.required
        or not source_import.may_be_overwritten
        or source_import.overwrite_candidates
        or len(source_import.candidates) != 1
    ):
        raise MutationToolchainError(
            "sealed Colorama winterm import policy changed"
        )
    import_candidate = source_import.candidates[0]
    if (
        import_candidate.module != "msvcrt"
        or import_candidate.level != 0
        or import_candidate.attribute != "get_osfhandle"
        or import_candidate.star
    ):
        raise MutationToolchainError(
            "sealed Colorama winterm import candidate changed"
        )

    source_bindings = tuple(
        binding
        for binding in policy.bindings
        if binding.path == ("get_osfhandle",)
        and binding.kind == "function"
        and binding.accessor == "direct"
    )
    if len(source_bindings) != 1:
        raise MutationToolchainError(
            "sealed Colorama winterm fallback policy changed"
        )
    source_binding = source_bindings[0]
    if (
        source_binding.required
        or source_binding.must_be_absent
        or len(source_binding.candidates) != 1
    ):
        raise MutationToolchainError(
            "sealed Colorama winterm fallback policy changed"
        )
    fallback = source_binding.candidates[0]
    semantics = fallback.function_semantics
    if (
        fallback.qualname != "get_osfhandle"
        or fallback.first_line != 5
        or fallback.definition_line != 5
        or fallback.decorators
        or type(semantics) is not _SourceFunctionSemantics
        or semantics.defaults
        or semantics.decorators
        or semantics.doc is not None
        or semantics.annotations
        or semantics.type_parameters
        or fallback.guards != (guard,)
        or not fallback.guards_complete
    ):
        raise MutationToolchainError(
            "sealed Colorama winterm fallback policy changed"
        )

    _verify_eager_provider_attribute(
        "colorama.winterm",
        module,
        "get_osfhandle",
    )
    _verify_eager_provider_attribute(
        "msvcrt",
        record.provider,
        "get_osfhandle",
    )
    value = record.value
    current_value_name = object.__getattribute__(value, "__name__")
    current_value_qualname = object.__getattribute__(value, "__qualname__")
    current_value_module = object.__getattribute__(value, "__module__")
    if (
        vars(module).get("get_osfhandle", _EAGER_ATTRIBUTE_MISSING) is not value
        or provider_namespace.get(
            "get_osfhandle",
            _EAGER_ATTRIBUTE_MISSING,
        )
        is not value
        or object.__getattribute__(value, "__self__") is not record.provider
        or type(current_value_name) is not str
        or current_value_name != record.value_name
        or type(current_value_qualname) is not str
        or current_value_qualname != record.value_qualname
        or type(current_value_module) is not str
        or current_value_module != record.value_module
        or type(record.value_name) is not str
        or record.value_name != "get_osfhandle"
        or type(record.value_qualname) is not str
        or record.value_qualname != "get_osfhandle"
        or type(record.value_module) is not str
        or record.value_module != "msvcrt"
    ):
        raise MutationToolchainError(
            "loaded Colorama winterm import outcome changed"
        )
    return record.succeeded is guard.branch


def _exact_source_reviewed_try_guard(
    module: ModuleType,
    *,
    policy: _SourceCodePolicy,
    guard: _SourceReviewedTryGuard,
) -> bool:
    policy_name = guard.policy
    if type(policy_name) is not str:
        raise MutationToolchainError(
            "sealed source reviewed try policy is invalid"
        )
    if policy_name == _COLORAMA_WIN32_CTYPES_TRY_POLICY:
        return _exact_source_colorama_win32_reviewed_try_guard(
            module,
            policy=policy,
            guard=guard,
        )
    if policy_name == _COLORAMA_WINTERM_MSVCRT_TRY_POLICY:
        return _exact_source_colorama_winterm_reviewed_try_guard(
            module,
            policy=policy,
            guard=guard,
        )
    raise MutationToolchainError(
        "sealed source reviewed try policy is unsupported"
    )


def _exact_source_class_guard(
    module: ModuleType,
    *,
    policy: _SourceCodePolicy,
    guard: _SourceClassGuard,
) -> bool:
    if type(guard) is _SourceVersionGuard:
        return _exact_source_version_guard(module, policy=policy, guard=guard)
    if type(guard) is _SourceVersionPrefixGuard:
        return _exact_source_version_prefix_guard(
            module,
            policy=policy,
            guard=guard,
        )
    if type(guard) is _SourceVersionRangeGuard:
        return _exact_source_version_range_guard(
            module,
            policy=policy,
            guard=guard,
        )
    if type(guard) is _SourcePytestVersionGuard:
        return _exact_source_pytest_version_guard(
            module,
            policy=policy,
            guard=guard,
        )
    if type(guard) is _SourcePlatformGuard:
        return _exact_source_platform_guard(module, policy=policy, guard=guard)
    if type(guard) is _SourceTypeCheckingGuard:
        return _exact_source_type_checking_guard(
            module,
            policy=policy,
            guard=guard,
        )
    if type(guard) is _SourceReviewedTryGuard:
        return _exact_source_reviewed_try_guard(
            module,
            policy=policy,
            guard=guard,
        )
    raise MutationToolchainError("sealed source class guard type is unsupported")


def _source_class_namespace_keys(
    module: ModuleType,
    value: type[object],
    *,
    path: str,
    policy: _SourceCodePolicy,
    source_shape: _SourceClassShape,
) -> tuple[str, ...] | None:
    eager = _eager_class_namespace_keys(module, value, path=path)
    if eager is not None:
        return eager
    if source_shape.decorators:
        return None
    if not source_shape.conditional_namespace_complete:
        raise MutationToolchainError(
            "loaded source class namespace cannot be derived from sealed source: "
            f"{module.__name__}.{path}"
        )
    expected = {
        _source_runtime_member_name(value.__name__, name)
        for name, _kind in source_shape.members
    }
    slot_names = _verify_source_slot_descriptors(
        module,
        value,
        path=path,
        source_shape=source_shape,
    )
    expected.update(slot_names)
    expected.update(
        _source_runtime_member_name(value.__name__, member.name)
        for member in source_shape.conditional_members
        if all(
            _exact_source_class_guard(module, policy=policy, guard=guard)
            for guard in member.guards
        )
    )
    expected.update({"__doc__", "__module__"})
    if any(base.startswith("Subscript(") for base in source_shape.bases):
        # CPython records the original parameterized base alongside the
        # erased runtime base.  The sealed AST proves when this compiler/runtime
        # key is lawful; its GenericAlias payload is recursively attested.
        expected.update({"__orig_bases__"} & vars(value).keys())
    if sys.version_info >= (3, 13):
        expected.update({"__firstlineno__", "__static_attributes__"})
    compiler_or_layout_names = {
        "__annotate_func__",
        "__annotations__",
        "__classcell__",
    }
    if not any(name == "__slots__" for name, _kind in source_shape.members):
        compiler_or_layout_names.update({"__dict__", "__weakref__"})
    expected.update(compiler_or_layout_names & vars(value).keys())
    expected.update(
        _exact_direct_protocol_generated_names(
            module,
            value,
            path=path,
            source_shape=source_shape,
        )
    )
    if _has_exact_abcmeta_derived_metaclass(value):
        expected.update({"__abstractmethods__", "_abc_impl"} & vars(value).keys())
    if isinstance(value, EnumMeta) and Enum in value.__mro__:
        enum_generated_names = {
            "__format__",
            "__new__",
            "__reduce_ex__",
            "__repr__",
            "__str__",
            "_generate_next_value_",
            "_hashable_values_",
            "_member_map_",
            "_member_names_",
            "_member_type_",
            "_new_member_",
            "_unhashable_values_",
            "_unhashable_values_map_",
            "_use_args_",
            "_value2member_map_",
            "_value_repr_",
        }
        expected.update(enum_generated_names & vars(value).keys())
    return tuple(sorted(expected))


def _exact_initial_pytest_class_lifecycle_keys(
    module: ModuleType,
    value: type[object],
    *,
    path: str,
    expected_names: tuple[str, ...],
    members: tuple[_RuntimeClassMemberSentinel, ...],
) -> bool:
    attr_name = "_pytest_diamond_inheritance_warning_shown"
    actual_names = tuple(member.name for member in members)
    if (
        module.__name__ != "_pytest.python"
        or path not in {"Function", "FunctionDefinition"}
        or set(actual_names) - set(expected_names) != {attr_name}
        or set(expected_names) - set(actual_names)
    ):
        return False
    before = _RuntimeClassSentinel(
        path=path,
        value=value,
        module=value.__module__,
        qualname=value.__qualname__,
        metaclass=type(value),
        bases=value.__bases__,
        members=tuple(member for member in members if member.name != attr_name),
    )
    after = _RuntimeClassSentinel(
        path=path,
        value=value,
        module=value.__module__,
        qualname=value.__qualname__,
        metaclass=type(value),
        bases=value.__bases__,
        members=members,
    )
    return _exact_pytest_function_lifecycle_transition(before, after)


def _verify_source_enum_literals(
    module: ModuleType,
    value: type[object],
    *,
    path: str,
    source_shape: _SourceClassShape,
) -> None:
    if not isinstance(value, EnumMeta) or Enum not in value.__mro__:
        return
    namespace = vars(value)
    member_map = namespace.get("_member_map_")
    if type(member_map) is not dict:
        raise MutationToolchainError(
            f"loaded source Enum member map changed: {module.__name__}.{path}"
        )
    for source_name, expected_shape in source_shape.literal_members:
        if source_name.startswith("_"):
            continue
        runtime_name = _source_runtime_member_name(value.__name__, source_name)
        member = namespace.get(runtime_name)
        mapped = member_map.get(runtime_name)
        if (
            type(member) is not value
            or mapped is not member
            or _runtime_value_shape(vars(member).get("_value_")) != expected_shape
        ):
            raise MutationToolchainError(
                "loaded source Enum member changed: "
                f"{module.__name__}.{path}.{runtime_name}"
            )


def _abc_weakref_set_shape(value: object, *, label: str) -> object:
    if type(value) is not set:
        raise MutationToolchainError(
            f"loaded source ABC {label} is not an exact set"
        )
    referents: list[object] = []
    for reference in value:
        if type(reference) is not ReferenceType:
            raise MutationToolchainError(
                f"loaded source ABC {label} contains a non-weakref entry"
            )
        referent = _EAGER_WEAKREF_CALL(reference)
        if referent is None:
            referents.append(["dead-weakref"])
        elif _is_runtime_class(referent):
            referents.append(_runtime_class_reference_shape(referent))
        else:
            raise MutationToolchainError(
                f"loaded source ABC {label} weakref has a non-class referent"
            )
    return sorted(referents, key=_compact_canonical_json_bytes)


def _exact_eager_colorama_cfield_member(
    module: ModuleType,
    owner: type[object],
    *,
    path: str,
    name: str,
    member: object,
    source_shape: _SourceClassShape | None,
    _outcome_reader: object = _exact_eager_colorama_win32_try_outcome,
) -> bool:
    if (
        type(_outcome_reader) is not FunctionType
        or _exact_eager_colorama_win32_try_outcome is not _outcome_reader
    ):
        return False
    try:
        record = _outcome_reader()
    except MutationToolchainError:
        return False
    if (
        type(record) is not _EagerColoramaWin32TryOutcome
        or type(module) is not ModuleType
        or module is not record.module
        or owner is not record.structure_class
        or path != "CONSOLE_SCREEN_BUFFER_INFO"
        or type(name) is not str
        or type(source_shape) is not _SourceClassShape
    ):
        return False
    if (
        len(source_shape.guards) != 1
        or type(source_shape.guards[0]) is not _SourceReviewedTryGuard
        or record.topology_sha256
        != source_shape.guards[0].topology_sha256
    ):
        return False
    structure_providers = [
        value
        for provider_name, value in record.ctypes_bindings
        if type(provider_name) is str and provider_name == "Structure"
    ]
    if len(structure_providers) != 1:
        return False
    try:
        owner_namespace = type.__getattribute__(owner, "__dict__")
        owner_bases = type.__getattribute__(owner, "__bases__")
    except TypeError:
        return False
    if (
        type(owner_namespace) is not MappingProxyType
        or owner_bases != (structure_providers[0],)
        or owner_namespace.get("_fields_") is not record.structure_fields
        or type(record.structure_fields) is not list
        or len(record.structure_fields) != len(record.structure_field_entries)
        or type(record.structure_descriptors) is not tuple
        or len(record.structure_descriptors)
        != len(record.structure_field_entries)
    ):
        return False
    for current, expected in zip(
        record.structure_fields,
        record.structure_field_entries,
        strict=True,
    ):
        if (
            current is not expected
            or
            type(current) is not tuple
            or len(current) != 2
            or type(current[0]) is not str
            or current[0] != expected[0]
            or current[1] is not expected[1]
        ):
            return False
    selected: tuple[str, object, tuple[tuple[str, bool, object], ...]] | None = None
    for descriptor_name, expected_descriptor, layout in record.structure_descriptors:
        if (
            type(descriptor_name) is not str
            or type(layout) is not tuple
            or type(expected_descriptor) is not record.cfield_type
            or owner_namespace.get(descriptor_name, _EAGER_ATTRIBUTE_MISSING)
            is not expected_descriptor
        ):
            return False
        if descriptor_name == name:
            if selected is not None:
                return False
            selected = (descriptor_name, expected_descriptor, layout)
        for attribute, present, expected_value in layout:
            if type(attribute) is not str or type(present) is not bool:
                return False
            try:
                current_value = object.__getattribute__(
                    expected_descriptor,
                    attribute,
                )
            except AttributeError:
                if present:
                    return False
            else:
                if not present:
                    return False
                if type(expected_value) in {bool, int, str}:
                    if (
                        type(current_value) is not type(expected_value)
                        or current_value != expected_value
                    ):
                        return False
                elif current_value is not expected_value:
                    return False
    if selected is None or selected[1] is not member:
        return False
    try:
        _verify_eager_provider_attribute("ctypes", record.ctypes_module, "CField")
    except MutationToolchainError:
        return False
    current_provider = vars(record.ctypes_module).get(
        "CField",
        _EAGER_ATTRIBUTE_MISSING,
    )
    return (
        (record.cfield_provider is _EAGER_ATTRIBUTE_MISSING)
        is (current_provider is _EAGER_ATTRIBUTE_MISSING)
        and (
            record.cfield_provider is _EAGER_ATTRIBUTE_MISSING
            or current_provider is record.cfield_provider is record.cfield_type
        )
    )


def _runtime_source_class_member_shape(
    module: ModuleType,
    owner: type[object],
    *,
    path: str,
    name: str,
    member: object,
    source_shape: _SourceClassShape | None = None,
    lru_runtime_context: object | None = None,
) -> object:
    profile_registry_shape = (
        _reviewed_hypothesis_profile_registry_member_shape(
            module,
            owner,
            path=path,
            name=name,
            member=member,
        )
    )
    if profile_registry_shape is not _EAGER_ATTRIBUTE_MISSING:
        return profile_registry_shape
    if _exact_eager_colorama_cfield_member(
        module,
        owner,
        path=path,
        name=name,
        member=member,
        source_shape=source_shape,
    ):
        return [
            _COLORAMA_CFIELD_MEMBER_MARKER,
            "colorama.win32",
            "CONSOLE_SCREEN_BUFFER_INFO",
            name,
        ]
    if (
        type(member) is _EAGER_OBJECT_TYPE
        and _exact_eager_anyio_typed_attribute_member(
            module,
            owner,
            path=path,
            name=name,
            member=member,
            source_shape=source_shape,
        )
    ):
        return [
            _ANYIO_TYPED_ATTRIBUTE_MEMBER_MARKER,
            module.__name__,
            path,
            name,
        ]
    lifecycle_shape = _exact_pytest_pdb_lifecycle_reference_shape(
        module,
        owner,
        path=path,
        name=name,
        member=member,
        lru_runtime_context=lru_runtime_context,
    )
    if lifecycle_shape is not _EAGER_ATTRIBUTE_MISSING:
        return lifecycle_shape
    if name != "_abc_impl":
        try:
            return _runtime_value_shape(
                member,
                _source_class=(module, owner, path),
            )
        except MutationToolchainError as exc:
            raise MutationToolchainError(
                "loaded source class member cannot be sealed: "
                f"{module.__name__}.{path}.{name}: {exc}"
            ) from exc
    owner_namespace = type.__getattribute__(owner, "__dict__")
    if (
        type(owner_namespace) is not MappingProxyType
        or sys.modules.get("abc") is not _EAGER_ABC_MODULE
        or sys.modules.get("_abc") is not _EAGER_NATIVE_ABC_MODULE
        or sys.modules.get("weakref") is not _EAGER_WEAKREF_MODULE
        or vars(_EAGER_ABC_MODULE).get("ABCMeta") is not _EAGER_ABC_META
        or vars(_EAGER_ABC_MODULE).get("ABC") is not _EAGER_ABC_CLASS
        or vars(_EAGER_NATIVE_ABC_MODULE).get("_get_dump")
        is not _EAGER_ABC_GET_DUMP
        or vars(_EAGER_WEAKREF_MODULE).get("ReferenceType") is not ReferenceType
        or vars(ReferenceType).get("__call__") is not _EAGER_WEAKREF_CALL
        or not _has_exact_abcmeta_derived_metaclass(owner)
        or owner_namespace.get("_abc_impl", _EAGER_ATTRIBUTE_MISSING) is not member
        or type(member) is not _EAGER_ABC_DATA_TYPE
    ):
        raise MutationToolchainError(
            f"loaded source ABC runtime binding changed: {module.__name__}.{path}"
        )
    _verify_eager_provider_attribute("abc", _EAGER_ABC_MODULE, "ABCMeta")
    _verify_eager_provider_attribute("abc", _EAGER_ABC_MODULE, "ABC")
    _verify_eager_provider_attribute(
        "_abc",
        _EAGER_NATIVE_ABC_MODULE,
        "_get_dump",
    )
    _verify_eager_provider_attribute(
        "weakref",
        _EAGER_WEAKREF_MODULE,
        "ReferenceType",
    )
    eager_abc_impl = _eager_class_abc_impl(module, owner, path=path)
    if (
        eager_abc_impl is not _EAGER_ATTRIBUTE_MISSING
        and eager_abc_impl is not member
    ):
        raise MutationToolchainError(
            f"eager source ABC data binding changed: {module.__name__}.{path}"
        )
    dump = _EAGER_ABC_GET_DUMP(owner)
    if (
        type(dump) is not tuple
        or len(dump) != 4
        or type(tuple.__getitem__(dump, 3)) is not int
    ):
        raise MutationToolchainError(
            f"loaded source ABC dump changed: {module.__name__}.{path}"
        )
    return [
        "_abc._abc_data",
        _abc_weakref_set_shape(
            tuple.__getitem__(dump, 0),
            label="registry",
        ),
        _abc_weakref_set_shape(
            tuple.__getitem__(dump, 1),
            label="positive cache",
        ),
        _abc_weakref_set_shape(
            tuple.__getitem__(dump, 2),
            label="negative cache",
        ),
        str(tuple.__getitem__(dump, 3)),
    ]


def _active_pytest_runtime_context_references(
    context: object | None,
) -> tuple[str, object | None, object | None] | None:
    if context is None:
        return None
    _verify_lru_runtime_context(context)
    values = tuple(
        _EAGER_LRU_RUNTIME_CONTEXT_MEMBER_GET(
            descriptor,
            context,
            _EAGER_LRU_RUNTIME_CONTEXT_TYPE,
        )
        for _name, descriptor in _EAGER_LRU_RUNTIME_CONTEXT_SLOT_DESCRIPTORS
    )
    mode, config, manager, _wrapper, _cache_parameters = values
    if mode not in {"active-pytest", "standalone-parent"}:
        raise MutationToolchainError("pytest runtime reference context changed")
    return mode, config, manager


def _exact_pytest_pdb_lifecycle_reference_shape(
    module: ModuleType,
    owner: type[object],
    *,
    path: str,
    name: str,
    member: object,
    lru_runtime_context: object | None,
) -> object:
    if (
        vars(module).get("__name__") != "_pytest.debugging"
        or path != "pytestPDB"
        or name not in {"_config", "_pluginmanager"}
    ):
        return _EAGER_ATTRIBUTE_MISSING
    captured_modules = tuple(
        captured
        for module_name, captured in _PREFIX_MODULES_AFTER_DETERMINISTIC_IMPORTS
        if module_name == "_pytest.debugging"
    )
    eager_owner = _eager_module_namespace_entry(
        "_pytest.debugging",
        module,
        "pytestPDB",
    )
    namespace = type.__getattribute__(owner, "__dict__")
    if (
        sys.modules.get("_pytest.debugging") is not module
        or len(captured_modules) != 1
        or captured_modules[0] is not module
        or not isinstance(eager_owner, _EagerNamespaceEntry)
        or eager_owner.value is not owner
        or type(owner) is not type
        or vars(module).get("pytestPDB") is not owner
        or type.__getattribute__(owner, "__module__") != "_pytest.debugging"
        or type.__getattribute__(owner, "__qualname__") != "pytestPDB"
        or type(namespace) is not MappingProxyType
    ):
        raise MutationToolchainError(
            "loaded pytestPDB lifecycle consumer changed"
        )
    pytest_runtime_references = _active_pytest_runtime_context_references(
        lru_runtime_context
    )
    if pytest_runtime_references is None:
        raise MutationToolchainError(
            "loaded pytestPDB lifecycle requires an exact pytest lifecycle context"
        )
    mode, config, manager = pytest_runtime_references
    if (
        _EAGER_MAPPING_PROXY_GET(namespace, "_config") is not config
        or _EAGER_MAPPING_PROXY_GET(namespace, "_pluginmanager") is not manager
    ):
        raise MutationToolchainError(
            "loaded pytestPDB lifecycle ownership changed"
        )
    expected = config if name == "_config" else manager
    if member is not expected:
        raise MutationToolchainError(
            f"loaded pytestPDB lifecycle reference changed: {name}"
        )
    return [
        "pytest-runtime-reference",
        mode,
        "Config" if name == "_config" else "PytestPluginManager",
    ]


(
    _EAGER_LRU_WRAPPER_TYPE,
    _EAGER_LRU_CACHE_CLEAR_DESCRIPTOR,
    _EAGER_LRU_CACHE_INFO_DESCRIPTOR,
    _EAGER_LRU_CACHE_INFO_TYPE,
    _EAGER_LRU_CACHE_INFO_TYPE_SHAPE,
    _EAGER_LRU_WRAPPER_BINDINGS,
) = _capture_eager_lru_wrapper_bindings()
_EAGER_LRU_CACHE_PARAMETERS_FUNCTION = object.__getattribute__(
    _EAGER_LRU_WRAPPER_BINDINGS[0].value,
    "__dict__",
).get("cache_parameters")
if type(_EAGER_LRU_CACHE_PARAMETERS_FUNCTION) is not FunctionType:
    raise MutationToolchainError(
        "reviewed functools LRU cache-parameter provider is unavailable"
    )
_EAGER_LRU_CACHE_PARAMETERS_CODE = object.__getattribute__(
    _EAGER_LRU_CACHE_PARAMETERS_FUNCTION,
    "__code__",
)
_EAGER_LRU_CACHE_PARAMETERS_GLOBALS = object.__getattribute__(
    _EAGER_LRU_CACHE_PARAMETERS_FUNCTION,
    "__globals__",
)
_EAGER_LRU_CACHE_PARAMETERS_BUILTINS = object.__getattribute__(
    _EAGER_LRU_CACHE_PARAMETERS_FUNCTION,
    "__builtins__",
)
_EAGER_PYTEST_CACHE_PARAMETERS_VERSION_POLICY = (
    _pytest_cache_parameters_version_policy
)
_EAGER_PYTEST_CACHE_PARAMETERS_VERSION_POLICY_CODE = object.__getattribute__(
    _EAGER_PYTEST_CACHE_PARAMETERS_VERSION_POLICY,
    "__code__",
)
_EAGER_PYTEST_CACHE_PARAMETERS_VERSION_POLICY_GLOBALS_ID = id(
    object.__getattribute__(
        _EAGER_PYTEST_CACHE_PARAMETERS_VERSION_POLICY,
        "__globals__",
    )
)
_STANDALONE_LRU_RUNTIME_CONTEXT = _EAGER_LRU_RUNTIME_CONTEXT_TYPE(
    mode="standalone-parent",
    config=None,
    plugin_manager=None,
    get_directory_wrapper=None,
    cache_parameters=None,
)
_EAGER_LRU_WRAPPER_NAMES = tuple(
    sorted(
        (
            *(binding.name for binding in _EAGER_LRU_WRAPPER_BINDINGS),
            _FASTPATH_LRU_FAMILY_NAME,
            _PYTEST_PLUGIN_MANAGER_LRU_FAMILY_NAME,
        )
    )
)
_EAGER_LRU_WRAPPER_SHA256 = _sha256_bytes(
    _compact_canonical_json_bytes(list(_EAGER_LRU_WRAPPER_NAMES))
)


def _runtime_class_sentinels(
    module: ModuleType,
    *,
    policy: _SourceCodePolicy,
    lru_runtime_context: object | None = None,
    _inactive_source_reader: FunctionType = (
        _exact_inactive_source_import_expected_value
    ),
) -> tuple[_RuntimeClassSentinel, ...]:
    if (
        _exact_inactive_source_import_expected_value
        is not _inactive_source_reader
        or type(module) is not ModuleType
    ):
        raise MutationToolchainError("loaded source module binding changed")
    module_name = vars(module).get("__name__")
    if type(module_name) is not str:
        raise MutationToolchainError("loaded source module metadata changed")
    missing = object()
    import_sentinels: dict[str, tuple[object, str | None]] = {}
    sentinels: list[_RuntimeClassSentinel] = []
    for binding in policy.bindings:
        if binding.kind != "class":
            continue
        path = ".".join(binding.path)
        active_candidate = _active_source_binding_candidate(
            module,
            policy=policy,
            binding=binding,
            import_sentinels=import_sentinels,
        )
        owner: object = module
        value: object = missing
        for index, part in enumerate(binding.path):
            try:
                value = vars(owner).get(part, missing)
            except TypeError:
                value = missing
            if value is missing or index == len(binding.path) - 1:
                break
            owner = value
        if binding.must_be_absent:
            if active_candidate is None:
                raise MutationToolchainError(
                    "deleted source class has no active candidate: "
                    f"{module_name}.{path}"
                )
            if value is not missing:
                raise MutationToolchainError(
                    "deleted source class is unexpectedly present: "
                    f"{module_name}.{path}"
                )
            continue
        inactive_import_expected = _INACTIVE_SOURCE_IMPORT_UNAVAILABLE
        if active_candidate is None:
            inactive_import_expected = (
                _inactive_source_reader(
                    module,
                    policy=policy,
                    source_binding=binding,
                )
            )
        if value is missing:
            if inactive_import_expected is not _INACTIVE_SOURCE_IMPORT_UNAVAILABLE:
                raise MutationToolchainError(
                    "loaded source imported class alternative is missing: "
                    f"{module_name}.{path}"
                )
            if active_candidate is not None:
                raise MutationToolchainError(
                    f"loaded source class binding is missing: {module_name}.{path}"
                )
            continue
        if active_candidate is None:
            if (
                inactive_import_expected is not _INACTIVE_SOURCE_IMPORT_UNAVAILABLE
                and value is inactive_import_expected
            ):
                continue
            raise MutationToolchainError(
                f"inactive source class is unexpectedly present: {module_name}.{path}"
            )
        if not _is_runtime_class(value):
            raise MutationToolchainError(
                f"loaded source class binding changed: {module_name}.{path}"
            )
        try:
            value_qualname = type.__getattribute__(value, "__qualname__")
            value_module = type.__getattribute__(value, "__module__")
            value_name = type.__getattribute__(value, "__name__")
            value_bases = type.__getattribute__(value, "__bases__")
            namespace = type.__getattribute__(value, "__dict__")
        except TypeError as exc:
            raise MutationToolchainError(
                f"loaded source class binding changed: {module_name}.{path}"
            ) from exc
        if (
            type(value_qualname) is not str
            or value_qualname != active_candidate.qualname
            or type(value_module) is not str
            or type(value_name) is not str
            or type(value_bases) is not tuple
            or type(namespace) is not MappingProxyType
        ):
            raise MutationToolchainError(
                f"loaded source class binding changed: {module_name}.{path}"
            )
        source_shapes = [
            shape
            for shape in policy.classes
            if (
                ".".join(shape.path) == path
                and shape.qualname == active_candidate.qualname
                and shape.first_line == active_candidate.first_line
                and shape.definition_line
                == active_candidate.definition_line
                and shape.guards == active_candidate.guards
                and shape.guards_complete == active_candidate.guards_complete
            )
        ]
        if len(source_shapes) != 1:
            raise MutationToolchainError(
                "sealed source class candidate shape is ambiguous: "
                f"{module_name}.{path}"
            )
        source_shape = source_shapes[0]
        expected_class_module = module_name
        for literal_name, literal_shape in source_shape.literal_members:
            if (
                literal_name == "__module__"
                and type(literal_shape) is list
                and literal_shape[:1] == ["str"]
                and len(literal_shape) == 2
                and isinstance(literal_shape[1], str)
            ):
                expected_class_module = literal_shape[1]
                break
        if (
            value_module != expected_class_module
            and not _exact_reexported_class_module(
                module,
                value,
                source_shape=source_shape,
            )
        ):
            raise MutationToolchainError(
                f"loaded source class binding changed: {module_name}.{path}"
            )
        _verify_source_enum_literals(
            module,
            value,
            path=path,
            source_shape=source_shape,
        )
        expected_bases = _source_plain_class_bases(module, source_shape)
        if expected_bases is not None and (
            len(value_bases) != len(expected_bases)
            or any(
                actual is not expected
                for actual, expected in zip(
                    value_bases, expected_bases, strict=True
                )
            )
        ):
            raise MutationToolchainError(
                f"loaded source class hierarchy changed: {module_name}.{path}"
            )
        expected_metaclass = _source_plain_class_metaclass(
            module,
            source_shape,
            expected_bases,
        )
        if expected_metaclass is not None and type(value) is not expected_metaclass:
            raise MutationToolchainError(
                f"loaded source class metaclass changed: {module_name}.{path}"
            )
        if expected_metaclass is type:
            for name, expected_shape in source_shape.literal_members:
                runtime_name = _source_runtime_member_name(value_name, name)
                member = namespace.get(runtime_name, missing)
                if member is missing or _runtime_value_shape(member) != expected_shape:
                    raise MutationToolchainError(
                        "loaded source class data changed: "
                        f"{module_name}.{path}.{runtime_name}"
                    )
        for source_name, member_kind in source_shape.members:
            if member_kind != "function":
                continue
            runtime_name = _source_runtime_member_name(
                value_name,
                source_name,
            )
            member = namespace.get(runtime_name, missing)
            if type(member) is property:
                expected_doc = (
                    member.fget.__doc__
                    if isinstance(member.fget, FunctionType)
                    else None
                )
                if member.__doc__ != expected_doc:
                    raise MutationToolchainError(
                        "loaded source class descriptor changed: "
                        f"{module_name}.{path}.{runtime_name}"
                    )
        declared_names = {
            _source_runtime_member_name(value_name, name)
            for name, _kind in source_shape.members
        }
        members = tuple(
            _RuntimeClassMemberSentinel(
                name=name,
                value=member,
                shape=_runtime_source_class_member_shape(
                    module,
                    value,
                    path=path,
                    name=name,
                    member=member,
                    source_shape=source_shape,
                    lru_runtime_context=lru_runtime_context,
                ),
            )
            for name, member in sorted(namespace.items())
        )
        expected_namespace_names = _source_class_namespace_keys(
            module,
            value,
            path=path,
            policy=policy,
            source_shape=source_shape,
        )
        actual_namespace_names = tuple(member.name for member in members)
        if (
            expected_namespace_names is not None
            and actual_namespace_names != expected_namespace_names
            and not _exact_initial_pytest_class_lifecycle_keys(
                module,
                value,
                path=path,
                expected_names=expected_namespace_names,
                members=members,
            )
        ):
            raise MutationToolchainError(
                "loaded source class namespace key set changed: "
                f"{module_name}.{path}; "
                f"missing={sorted(set(expected_namespace_names) - set(actual_namespace_names))!r}; "
                f"extra={sorted(set(actual_namespace_names) - set(expected_namespace_names))!r}"
            )
        if (
            expected_namespace_names is None
            and not source_shape.decorators
            and not declared_names.issubset(namespace)
        ):
            raise MutationToolchainError(
                f"loaded source class namespace changed: {module_name}.{path}"
            )
        sentinels.append(
            _RuntimeClassSentinel(
                path=path,
                value=value,
                module=value_module,
                qualname=value_qualname,
                metaclass=type(value),
                bases=value_bases,
                members=members,
            )
        )
    return tuple(sentinels)


def _exact_hypothesis_running_under_pytest_transition(
    module: ModuleType,
    binding: _SourceModuleDataBinding,
    value: object,
) -> bool:
    module_name = vars(module).get("__name__") if type(module) is ModuleType else None
    if (
        type(module_name) is not str
        or module_name != "hypothesis.core"
        or binding.name != "running_under_pytest"
        or binding.shape != ["bool", False]
        or value is not True
    ):
        return False
    plugin_name = "_hypothesis_pytestplugin"
    plugin = sys.modules.get(plugin_name)
    if not isinstance(plugin, ModuleType):
        return False
    try:
        expected_hook = _eager_module_namespace_entry(
            plugin_name,
            plugin,
            "pytest_runtest_call",
        )
    except MutationToolchainError:
        return False
    hook = vars(plugin).get("pytest_runtest_call")
    if (
        not isinstance(expected_hook, _EagerNamespaceEntry)
        or hook is not expected_hook.value
        or type(hook) is not FunctionType
        or hook.__module__ != plugin_name
        or hook.__qualname__ != "pytest_runtest_call"
        or hook.__globals__ is not vars(plugin)
    ):
        return False
    specification = vars(plugin).get("__spec__")
    origin = getattr(specification, "origin", None)
    loader = getattr(specification, "loader", None)
    module_file = vars(plugin).get("__file__")
    if not isinstance(origin, str) or not isinstance(module_file, str):
        return False
    try:
        source_path = Path(module_file).resolve(strict=True)
        if source_path != Path(origin).resolve(strict=True):
            return False
        source = _stable_policy_bytes(
            Path(sys.prefix).resolve(strict=True),
            source_path,
            label="sealed Hypothesis pytest lifecycle hook",
        )
        variant = _source_loader_variant(
            loader,
            module_name=plugin_name,
            rewrite_module_is_attested=(
                isinstance(sys.modules.get("_pytest.assertion.rewrite"), ModuleType)
            ),
        )
        entries, _policy, _bindings = _sealed_source_variant_payload(
            source,
            source_path=source_path,
            variant=variant,
        )
        tree = ast.parse(source, filename=os.fspath(source_path), mode="exec")
    except (MutationToolchainError, OSError, SyntaxError, ValueError):
        return False
    if _runtime_function_code_identity(hook) not in {
        (
            entry["qualname"],
            entry["firstlineno"],
            entry["firstcol"],
            entry["sha256"],
        )
        for entry in entries
        if entry.get("qualname") == "pytest_runtest_call"
    }:
        return False
    functions = [
        node
        for node in ast.walk(tree)
        if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef))
        and node.name == "pytest_runtest_call"
    ]
    if len(functions) != 1:
        return False
    function = functions[0]
    expected_decorator = ast.parse(
        "@pytest.hookimpl(hookwrapper=True)\n"
        "def pytest_runtest_call(item):\n"
        "    pass\n"
    ).body[0].decorator_list[0]
    expected_assignment = ast.parse(
        "core.running_under_pytest = True\n"
    ).body[0]
    return (
        len(function.decorator_list) == 1
        and ast.dump(
            function.decorator_list[0],
            annotate_fields=True,
            include_attributes=False,
        )
        == ast.dump(
            expected_decorator,
            annotate_fields=True,
            include_attributes=False,
        )
        and sum(
            ast.dump(
                node,
                annotate_fields=True,
                include_attributes=False,
            )
            == ast.dump(
                expected_assignment,
                annotate_fields=True,
                include_attributes=False,
            )
            for node in ast.walk(function)
        )
        == 1
        and any(
            isinstance(node, ast.ImportFrom)
            and node.level == 0
            and node.module == "hypothesis"
            and any(alias.name == "core" for alias in node.names)
            for node in ast.walk(function)
        )
    )


def _runtime_module_data_sentinels(
    module: ModuleType,
    *,
    policy: _SourceCodePolicy,
) -> tuple[_RuntimeModuleDataSentinel, ...]:
    missing = object()
    sentinels: list[_RuntimeModuleDataSentinel] = []
    for binding in policy.module_data:
        value = vars(module).get(binding.name, missing)
        actual_shape = (
            None if value is missing else _runtime_value_shape(value)
        )
        if (
            value is missing
            or (
                actual_shape != binding.shape
                and not _exact_hypothesis_running_under_pytest_transition(
                    module,
                    binding,
                    value,
                )
            )
        ):
            raise MutationToolchainError(
                "loaded source module policy changed: "
                f"{module.__name__}.{binding.name}"
            )
        sentinels.append(
            _RuntimeModuleDataSentinel(
                name=binding.name,
                value=value,
                shape=actual_shape,
            )
        )
    return tuple(sentinels)


def _runtime_function_code_identity(
    function: FunctionType,
) -> tuple[object, object, object, object]:
    code = function.__code__
    first_column = next(
        (
            start_column
            for _start_line, _end_line, start_column, end_column in code.co_positions()
            if (
                start_column is not None
                and end_column is not None
                and end_column > start_column
            )
        ),
        -1,
    )
    return (
        code.co_qualname,
        code.co_firstlineno,
        first_column,
        _normalized_code_sha256(code),
    )


def _exact_sealed_class_method(
    owner: type[object],
    *,
    module_name: str,
    owner_qualname: str,
    method_name: str,
) -> FunctionType | None:
    defining_module = sys.modules.get(module_name)
    if not isinstance(defining_module, ModuleType):
        return None
    function = vars(owner).get(method_name)
    expected_qualname = f"{owner_qualname}.{method_name}"
    if (
        type(function) is not FunctionType
        or vars(defining_module).get(owner_qualname) is not owner
        or owner.__module__ != module_name
        or owner.__qualname__ != owner_qualname
        or function.__module__ != module_name
        or function.__qualname__ != expected_qualname
        or function.__code__.co_qualname != expected_qualname
        or function.__globals__ is not vars(defining_module)
    ):
        return None
    specification = vars(defining_module).get("__spec__")
    loader = getattr(specification, "loader", None)
    origin = getattr(specification, "origin", None)
    module_file = vars(defining_module).get("__file__")
    if not isinstance(origin, str) or not isinstance(module_file, str):
        return None
    try:
        variant = _source_loader_variant(
            loader,
            module_name=module_name,
            rewrite_module_is_attested=(
                isinstance(sys.modules.get("_pytest.assertion.rewrite"), ModuleType)
            ),
        )
        source_path = Path(module_file).resolve(strict=True)
        if source_path != Path(origin).resolve(strict=True):
            return None
        prefix = Path(sys.prefix).resolve(strict=True)
        source = _stable_policy_bytes(
            prefix,
            source_path,
            label=f"sealed pytest lifecycle method {expected_qualname}",
        )
        entries, _policy, _bindings = _sealed_source_variant_payload(
            source,
            source_path=source_path,
            variant=variant,
        )
    except (MutationToolchainError, OSError, ValueError):
        return None
    actual = _runtime_function_code_identity(function)
    if actual not in {
        (
            entry["qualname"],
            entry["firstlineno"],
            entry["firstcol"],
            entry["sha256"],
        )
        for entry in entries
        if entry.get("qualname") == expected_qualname
    }:
        return None
    return function


def _exact_pytest_function_lifecycle_transition(
    before: _RuntimeClassSentinel,
    after: _RuntimeClassSentinel,
) -> bool:
    attr_name = "_pytest_diamond_inheritance_warning_shown"
    before_members = {item.name: item for item in before.members}
    after_members = {item.name: item for item in after.members}
    python_module = sys.modules.get("_pytest.python")
    function_class = (
        vars(python_module).get("Function")
        if isinstance(python_module, ModuleType)
        else None
    )
    function_definition_class = (
        vars(python_module).get("FunctionDefinition")
        if isinstance(python_module, ModuleType)
        else None
    )
    admitted_class = {
        "Function": function_class,
        "FunctionDefinition": function_definition_class,
    }.get(before.path)
    if (
        admitted_class is None
        or before.value is not admitted_class
        or before.value is not after.value
        or before.value.__module__ != "_pytest.python"
        or before.value.__qualname__ != before.path
        or not isinstance(python_module, ModuleType)
        or set(after_members) - set(before_members) != {attr_name}
        or set(before_members) - set(after_members)
        or attr_name in before_members
    ):
        return False
    lifecycle_member = after_members[attr_name]
    if lifecycle_member.value is not True or lifecycle_member.shape != ["bool", True]:
        return False
    nodes_module = sys.modules.get("_pytest.nodes")
    item_class = (
        vars(nodes_module).get("Item")
        if isinstance(nodes_module, ModuleType)
        else None
    )
    if (
        not inspect.isclass(item_class)
        or item_class not in after.value.__mro__
        or not inspect.isclass(function_class)
        or (
            before.path == "FunctionDefinition"
            and (
                len(after.value.__bases__) != 1
                or after.value.__bases__[0] is not function_class
            )
        )
    ):
        return False
    item_init = _exact_sealed_class_method(
        item_class,
        module_name="_pytest.nodes",
        owner_qualname="Item",
        method_name="__init__",
    )
    lifecycle_hook = _exact_sealed_class_method(
        item_class,
        module_name="_pytest.nodes",
        owner_qualname="Item",
        method_name="_check_item_and_collector_diamond_inheritance",
    )
    return (
        item_init is not None
        and lifecycle_hook is not None
        and "_check_item_and_collector_diamond_inheritance"
        in item_init.__code__.co_names
        and "setattr" in lifecycle_hook.__code__.co_names
        and attr_name in lifecycle_hook.__code__.co_consts
        and any(value is True for value in lifecycle_hook.__code__.co_consts)
    )


def _verify_runtime_source_bindings(
    module: ModuleType,
    *,
    policy: _SourceCodePolicy,
    lru_runtime_context: object | None = None,
) -> None:
    key = id(module)
    expected = _RUNTIME_SOURCE_SENTINELS.get(key)
    module_name = vars(module).get("__name__")
    if type(module_name) is str and module_name == "hypothesis._settings":
        settings_binding = _exact_eager_hypothesis_settings_classdict_cell()
        if module is not settings_binding.source_module:
            raise MutationToolchainError(
                "reviewed Hypothesis settings module binding changed"
            )
        _verify_eager_hypothesis_settings_classdict_cell(
            settings_binding.classdict_cell,
            policy=policy,
        )
    if module_name == "execnet.gateway_base":
        _exact_execnet_debug_disabled_outcome(module, policy=policy)
    _verify_runtime_builtin_fallbacks(module, policy=policy)
    current_imports = _runtime_import_sentinels(
        module,
        policy=policy,
        expected=(expected.imports if expected is not None else None),
    )
    current_classes = _runtime_class_sentinels(
        module,
        policy=policy,
        lru_runtime_context=lru_runtime_context,
    )
    current_module_data = _runtime_module_data_sentinels(module, policy=policy)
    if expected is None:
        _RUNTIME_SOURCE_SENTINELS[key] = _RuntimeSourceSentinel(
            module=module,
            imports=current_imports,
            classes=current_classes,
            module_data=current_module_data,
        )
        return
    if expected.module is not module:
        raise MutationToolchainError(
            f"loaded source module sentinel changed: {module.__name__}"
        )
    if [item.name for item in current_imports] != [
        item.name for item in expected.imports
    ]:
        raise MutationToolchainError(
            f"loaded source import binding set changed: {module.__name__}"
        )
    for before, after in zip(expected.imports, current_imports, strict=True):
        if (
            before.value is not after.value
            or before.provider_name != after.provider_name
            or before.provider is not after.provider
            or before.provider_attribute != after.provider_attribute
            or before.provider_value is not after.provider_value
            or before.callable_code is not after.callable_code
            or before.callable_code_sha256 != after.callable_code_sha256
        ):
            raise MutationToolchainError(
                f"loaded source import binding changed: {module.__name__}.{before.name}"
            )
    if [item.name for item in current_module_data] != [
        item.name for item in expected.module_data
    ]:
        raise MutationToolchainError(
            f"loaded source module policy set changed: {module.__name__}"
        )
    for before, after in zip(
        expected.module_data,
        current_module_data,
        strict=True,
    ):
        if before.value is not after.value or before.shape != after.shape:
            raise MutationToolchainError(
                "loaded source module policy changed: "
                f"{module.__name__}.{before.name}"
            )
    if [item.path for item in current_classes] != [
        item.path for item in expected.classes
    ]:
        raise MutationToolchainError(
            f"loaded source class binding set changed: {module.__name__}"
        )
    lifecycle_advanced = False
    for before, after in zip(expected.classes, current_classes, strict=True):
        if (
            before.value is not after.value
            or before.module != after.module
            or before.qualname != after.qualname
            or before.metaclass is not after.metaclass
        ):
            raise MutationToolchainError(
                f"loaded source class binding changed: {module.__name__}.{before.path}"
            )
        if len(before.bases) != len(after.bases) or any(
            left is not right
            for left, right in zip(before.bases, after.bases, strict=True)
        ):
            raise MutationToolchainError(
                f"loaded source class hierarchy changed: {module.__name__}.{before.path}"
            )
        before_names = [item.name for item in before.members]
        after_names = [item.name for item in after.members]
        if before_names != after_names:
            if not _exact_pytest_function_lifecycle_transition(before, after):
                raise MutationToolchainError(
                    "loaded source class namespace key set changed: "
                    f"{module.__name__}.{before.path}; "
                    f"missing={sorted(set(before_names) - set(after_names))!r}; "
                    f"extra={sorted(set(after_names) - set(before_names))!r}"
                )
            lifecycle_advanced = True
        after_by_name = {item.name: item for item in after.members}
        for old_member in before.members:
            new_member = after_by_name[old_member.name]
            if (
                old_member.value is not new_member.value
                or old_member.shape != new_member.shape
            ):
                raise MutationToolchainError(
                    "loaded source class namespace changed: "
                    f"{module.__name__}.{before.path}.{old_member.name}"
                )
    if lifecycle_advanced:
        _RUNTIME_SOURCE_SENTINELS[key] = _RuntimeSourceSentinel(
            module=module,
            imports=current_imports,
            classes=current_classes,
            module_data=current_module_data,
        )


def _verify_loaded_source_code(
    module: ModuleType,
    *,
    source: bytes,
    source_path: Path,
    variant: str,
    expected_manifest: object | None = None,
    admitted_source_paths: frozenset[str] | None = None,
    admitted_module_paths: frozenset[str] | None = None,
    admitted_class_ids: frozenset[int] | None = None,
    require_complete: bool = True,
    lru_runtime_context: object | None = None,
    _loaded_bindings_verifier: FunctionType = _verify_loaded_bindings,
    _loaded_bindings_verifier_fingerprints: tuple[tuple[object, ...], ...] = (
        _EAGER_LOADED_BINDINGS_VERIFIER_CALLABLE_FINGERPRINTS
    ),
    _exact_callable_verifier: FunctionType = _verify_exact_callable_fingerprint,
    _exact_callable_verifier_code: CodeType = (
        _verify_exact_callable_fingerprint.__code__
    ),
    _exact_callable_verifier_defaults: object = (
        _EAGER_EXACT_CALLABLE_VERIFIER_DEFAULTS
    ),
    _exact_callable_verifier_kwdefaults: dict[str, object] = (
        _EAGER_EXACT_CALLABLE_VERIFIER_KWDEFAULTS
    ),
    _exact_callable_verifier_kwdefault_items: tuple[tuple[str, object], ...] = (
        _EAGER_EXACT_CALLABLE_VERIFIER_KWDEFAULT_ITEMS
    ),
    _exact_callable_verifier_builtins: dict[str, object] = (
        _EAGER_EXACT_STRING_KEYED_DICT_READER_BUILTINS
    ),
    _dict_reader: FunctionType = _EAGER_EXACT_STRING_KEYED_DICT_READER,
    _dict_reader_code: CodeType = _EAGER_EXACT_STRING_KEYED_DICT_READER_CODE,
    _dict_reader_defaults: object = (
        _EAGER_EXACT_STRING_KEYED_DICT_READER_DEFAULTS
    ),
    _dict_reader_kwdefaults: dict[str, object] = (
        _EAGER_EXACT_STRING_KEYED_DICT_READER_KWDEFAULTS
    ),
    _dict_reader_kwdefault_items: tuple[tuple[str, object], ...] = (
        _EAGER_EXACT_STRING_KEYED_DICT_READER_KWDEFAULT_ITEMS
    ),
    _dict_reader_builtins: dict[str, object] = (
        _EAGER_EXACT_STRING_KEYED_DICT_READER_BUILTINS
    ),
    _object_getattribute: object = object.__getattribute__,
    _builtin_type: type[type] = type,
    _builtin_len: BuiltinFunctionType = len,
    _builtin_all: BuiltinFunctionType = all,
    _builtin_any: BuiltinFunctionType = any,
    _builtin_zip: type[zip] = zip,
    _builtin_vars: BuiltinFunctionType = vars,
    _mapping_items: MethodDescriptorType = dict.items,
    _string_eq: WrapperDescriptorType = str.__eq__,
    _tuple_len: WrapperDescriptorType = tuple.__len__,
    _tuple_getitem: MethodDescriptorType = tuple.__getitem__,
    _dict_type: type[dict] = dict,
    _tuple_type: type[tuple] = tuple,
    _string_type: type[str] = str,
    _function_type: type[FunctionType] = FunctionType,
    _code_type: type[CodeType] = CodeType,
    _cell_type: type[CellType] = CellType,
    _object_type: type[object] = object,
    _cell_contents_descriptor: GetSetDescriptorType = (
        _EXACT_CALLABLE_CELL_CONTENTS_DESCRIPTOR
    ),
    _error_type: type[MutationToolchainError] = MutationToolchainError,
    _toolchain_namespace: dict[str, object] = globals(),
    _inactive_source_reader: FunctionType = (
        _exact_inactive_source_import_expected_value
    ),
) -> dict[str, object]:
    def seal_exact_callable_verifier() -> None:
        reader_items = (
            _tuple_type(_mapping_items(_dict_reader_kwdefaults))
            if _builtin_type(_dict_reader_kwdefaults) is _dict_type
            else ()
        )
        callable_items = (
            _tuple_type(_mapping_items(_exact_callable_verifier_kwdefaults))
            if _builtin_type(_exact_callable_verifier_kwdefaults) is _dict_type
            else ()
        )
        if (
            _builtin_type(_dict_reader) is not _function_type
            or _builtin_type(_dict_reader_code) is not _code_type
            or _object_getattribute(_dict_reader, "__code__")
            is not _dict_reader_code
            or _object_getattribute(_dict_reader, "__globals__")
            is not _toolchain_namespace
            or _object_getattribute(_dict_reader, "__builtins__")
            is not _dict_reader_builtins
            or _object_getattribute(_dict_reader, "__defaults__")
            is not _dict_reader_defaults
            or _dict_reader_defaults is not None
            or _object_getattribute(_dict_reader, "__kwdefaults__")
            is not _dict_reader_kwdefaults
            or _object_getattribute(_dict_reader, "__closure__") is not None
            or _builtin_len(reader_items)
            != _builtin_len(_dict_reader_kwdefault_items)
            or _builtin_all(
                _builtin_type(current) is _tuple_type
                and _tuple_len(current) == 2
                and _builtin_type(expected) is _tuple_type
                and _tuple_len(expected) == 2
                and _builtin_type(_tuple_getitem(current, 0)) is _string_type
                and _builtin_type(_tuple_getitem(expected, 0)) is _string_type
                and _string_eq(
                    _tuple_getitem(current, 0),
                    _tuple_getitem(expected, 0),
                )
                and _tuple_getitem(current, 1)
                is _tuple_getitem(expected, 1)
                for current, expected in _builtin_zip(
                    reader_items,
                    _dict_reader_kwdefault_items,
                    strict=True,
                )
            )
            is not True
        ):
            raise _error_type("loaded source verifier binding changed")
        try:
            for name, expected in (
                ("type", _builtin_type),
                ("str", _string_type),
                ("len", _builtin_len),
                ("any", _builtin_any),
                ("zip", _builtin_zip),
                ("vars", _builtin_vars),
                ("dict", _dict_type),
                ("tuple", _tuple_type),
                ("object", _object_type),
            ):
                if _dict_reader(_dict_reader_builtins, name) is not expected:
                    raise _error_type("loaded source verifier binding changed")
            for name, expected in (
                ("_verify_exact_callable_fingerprint", _exact_callable_verifier),
                (
                    "_EAGER_EXACT_CALLABLE_VERIFIER_DEFAULTS",
                    _exact_callable_verifier_defaults,
                ),
                (
                    "_EAGER_EXACT_CALLABLE_VERIFIER_KWDEFAULTS",
                    _exact_callable_verifier_kwdefaults,
                ),
                (
                    "_EAGER_EXACT_CALLABLE_VERIFIER_KWDEFAULT_ITEMS",
                    _exact_callable_verifier_kwdefault_items,
                ),
                (
                    "_EAGER_EXACT_STRING_KEYED_DICT_READER",
                    _dict_reader,
                ),
                (
                    "_EAGER_EXACT_STRING_KEYED_DICT_READER_CODE",
                    _dict_reader_code,
                ),
                (
                    "_EAGER_EXACT_STRING_KEYED_DICT_READER_DEFAULTS",
                    _dict_reader_defaults,
                ),
                (
                    "_EAGER_EXACT_STRING_KEYED_DICT_READER_KWDEFAULTS",
                    _dict_reader_kwdefaults,
                ),
                (
                    "_EAGER_EXACT_STRING_KEYED_DICT_READER_KWDEFAULT_ITEMS",
                    _dict_reader_kwdefault_items,
                ),
                (
                    "_EAGER_EXACT_STRING_KEYED_DICT_READER_BUILTINS",
                    _dict_reader_builtins,
                ),
                (
                    "_EXACT_CALLABLE_CELL_CONTENTS_DESCRIPTOR",
                    _cell_contents_descriptor,
                ),
                ("CellType", _cell_type),
                ("FunctionType", _function_type),
                ("CodeType", _code_type),
            ):
                if _dict_reader(_toolchain_namespace, name) is not expected:
                    raise _error_type("loaded source verifier binding changed")
        except _error_type as exc:
            raise _error_type("loaded source verifier binding changed") from exc
        if (
            _builtin_type(_exact_callable_verifier) is not _function_type
            or _builtin_type(_exact_callable_verifier_code) is not _code_type
            or _object_getattribute(_exact_callable_verifier, "__code__")
            is not _exact_callable_verifier_code
            or _object_getattribute(_exact_callable_verifier, "__globals__")
            is not _toolchain_namespace
            or _object_getattribute(_exact_callable_verifier, "__builtins__")
            is not _exact_callable_verifier_builtins
            or _exact_callable_verifier_builtins is not _dict_reader_builtins
            or _object_getattribute(_exact_callable_verifier, "__defaults__")
            is not _exact_callable_verifier_defaults
            or _exact_callable_verifier_defaults is not None
            or _object_getattribute(_exact_callable_verifier, "__kwdefaults__")
            is not _exact_callable_verifier_kwdefaults
            or _object_getattribute(_exact_callable_verifier, "__closure__")
            is not None
            or _builtin_len(callable_items)
            != _builtin_len(_exact_callable_verifier_kwdefault_items)
            or _builtin_all(
                _builtin_type(current) is _tuple_type
                and _tuple_len(current) == 2
                and _builtin_type(expected) is _tuple_type
                and _tuple_len(expected) == 2
                and _builtin_type(_tuple_getitem(current, 0)) is _string_type
                and _builtin_type(_tuple_getitem(expected, 0)) is _string_type
                and _string_eq(
                    _tuple_getitem(current, 0),
                    _tuple_getitem(expected, 0),
                )
                and _tuple_getitem(current, 1)
                is _tuple_getitem(expected, 1)
                for current, expected in _builtin_zip(
                    callable_items,
                    _exact_callable_verifier_kwdefault_items,
                    strict=True,
                )
            )
            is not True
        ):
            raise _error_type("loaded source verifier binding changed")

    seal_exact_callable_verifier()
    if (
        _verify_loaded_bindings is not _loaded_bindings_verifier
        or _EAGER_LOADED_BINDINGS_VERIFIER_CALLABLE_FINGERPRINTS
        is not _loaded_bindings_verifier_fingerprints
        or _verify_exact_callable_fingerprint is not _exact_callable_verifier
        or _exact_inactive_source_import_expected_value
        is not _inactive_source_reader
    ):
        raise MutationToolchainError("loaded source verifier binding changed")
    expected_entries, policy, expected_bindings = _sealed_source_variant_payload(
        source,
        source_path=source_path,
        variant=variant,
    )
    expected_object_summary = _code_manifest_summary(expected_entries)
    expected_variant_summary = {
        **expected_object_summary,
        "binding_sha256": _sha256_bytes(
            _canonical_json_bytes(
                _binding_topology_payload(policy, expected_bindings)
            )
        ),
    }
    if expected_manifest is not None:
        if not isinstance(expected_manifest, dict):
            raise MutationToolchainError(
                f"sealed source code manifest is invalid: {module.__name__}"
            )
        variants = expected_manifest.get("variants")
        if (
            not isinstance(variants, dict)
            or variants.get(variant) != expected_variant_summary
        ):
            raise MutationToolchainError(
                f"sealed source code manifest changed: {module.__name__}"
            )
    actual_summary, actual_entries = _loaded_source_code_summary(
        module,
        source=source,
        source_path=source_path,
        admitted_source_paths=admitted_source_paths,
        admitted_module_paths=admitted_module_paths,
        admitted_class_ids=admitted_class_ids,
    )
    def keyed(entries: Sequence[dict[str, object]]) -> dict[tuple[object, ...], str]:
        return {
            (
                item["qualname"],
                item["name"],
                item["firstlineno"],
                item["firstcol"],
            ): str(item["sha256"])
            for item in entries
        }

    expected_by_key = keyed(expected_entries)
    actual_by_key = keyed(actual_entries)
    expected_keys = set(expected_by_key)
    actual_keys = set(actual_by_key)
    missing = sorted(expected_keys - actual_keys)
    extra = sorted(actual_keys - expected_keys)
    if (require_complete and missing) or extra:
        raise MutationToolchainError(
            "loaded source callable inventory differs from sealed source: "
            f"{module.__name__}; missing={missing!r}; extra={extra!r}"
        )
    changed = sorted(
        key
        for key in actual_keys & expected_keys
        if actual_by_key[key] != expected_by_key[key]
    )
    if changed or (require_complete and actual_summary != expected_object_summary):
        raise MutationToolchainError(
            "loaded source code objects differ from sealed source: "
            f"{module.__name__}; changed={changed!r}"
        )
    loaded_attested_code_identities = frozenset(
        (
            item["qualname"],
            item["firstlineno"],
            item["firstcol"],
            item["sha256"],
        )
        for item in actual_entries
    )
    seal_exact_callable_verifier()
    try:
        if (
            _exact_callable_verifier(_loaded_bindings_verifier_fingerprints[0])
            is not _loaded_bindings_verifier
        ):
            raise MutationToolchainError("loaded source verifier binding changed")
        for fingerprint in _loaded_bindings_verifier_fingerprints[1:]:
            _exact_callable_verifier(fingerprint)
    except MutationToolchainError as exc:
        raise MutationToolchainError("loaded source verifier binding changed") from exc
    _loaded_bindings_verifier(
        module,
        bindings=expected_bindings,
        attested_code_identities=loaded_attested_code_identities,
        admitted_source_paths=admitted_source_paths,
        admitted_class_ids=admitted_class_ids,
        policy=policy,
        _inactive_source_reader=_inactive_source_reader,
    )
    _verify_runtime_source_bindings(
        module,
        policy=policy,
        lru_runtime_context=lru_runtime_context,
    )
    return actual_summary


def _startup_control_scopes(search_paths: Sequence[Path]) -> tuple[Path, ...]:
    selected: dict[str, Path] = {}
    customization_names = {"sitecustomize", "usercustomize"}
    for search_path in search_paths:
        try:
            with os.scandir(search_path) as entries:
                children = sorted(entries, key=lambda entry: entry.name.casefold())
        except OSError as exc:
            raise MutationToolchainError(
                f"cannot enumerate Python startup path {search_path}: {exc}"
            ) from exc
        for entry in children:
            candidate = Path(entry.path)
            folded_name = entry.name.casefold()
            selected_file = (
                folded_name.endswith((".pth", ".egg-link"))
                or folded_name in {"sitecustomize.py", "usercustomize.py"}
            )
            selected_directory = folded_name in customization_names
            if not selected_file and not selected_directory:
                continue
            try:
                metadata_value = entry.stat(follow_symlinks=False)
            except OSError as exc:
                raise MutationToolchainError(
                    f"cannot inspect Python startup scope {candidate}: {exc}"
                ) from exc
            if stat.S_ISLNK(metadata_value.st_mode) or _is_reparse(metadata_value):
                raise MutationToolchainError(
                    f"Python startup scope is a link or reparse point: {candidate}"
                )
            if selected_file and not stat.S_ISREG(metadata_value.st_mode):
                raise MutationToolchainError(
                    f"Python startup file is not regular: {candidate}"
                )
            if selected_directory and not stat.S_ISDIR(metadata_value.st_mode):
                raise MutationToolchainError(
                    f"Python startup package is not a directory: {candidate}"
                )
            folded_path = os.path.normcase(os.fspath(candidate))
            if folded_path in selected:
                raise MutationToolchainError(
                    f"Python startup scope is enumerated twice: {candidate}"
                )
            selected[folded_path] = candidate
    return tuple(sorted(selected.values(), key=lambda path: str(path).casefold()))


def _checked_module_root(value: str, *, label: str) -> str:
    if (
        not isinstance(value, str)
        or not value
        or any(not part.isidentifier() for part in value.split("."))
    ):
        raise MutationToolchainError(f"{label} is not a dotted Python name")
    return value.split(".", 1)[0]


def _python_startup_import_roots(
    source: str,
    *,
    label: str,
    depth: int = 0,
) -> set[str]:
    if depth > 8:
        raise MutationToolchainError(f"{label} exceeds nested startup-code depth")
    try:
        tree = ast.parse(source, filename=label, mode="exec")
    except SyntaxError as exc:
        raise MutationToolchainError(f"{label} is not valid Python startup code") from exc
    roots: set[str] = set()
    for node in ast.walk(tree):
        if isinstance(node, ast.Import):
            roots.update(
                _checked_module_root(alias.name, label=label)
                for alias in node.names
            )
        elif isinstance(node, ast.ImportFrom):
            if node.level or node.module is None:
                raise MutationToolchainError(
                    f"{label} contains a relative startup import"
                )
            roots.add(_checked_module_root(node.module, label=label))
        elif isinstance(node, ast.Call):
            dynamic_kind: str | None = None
            if isinstance(node.func, ast.Name) and node.func.id in {
                "__import__",
                "exec",
                "eval",
            }:
                dynamic_kind = node.func.id
            elif (
                isinstance(node.func, ast.Attribute)
                and node.func.attr == "import_module"
            ):
                dynamic_kind = "import_module"
            if dynamic_kind is None:
                continue
            if (
                not node.args
                or not isinstance(node.args[0], ast.Constant)
                or not isinstance(node.args[0].value, str)
            ):
                raise MutationToolchainError(
                    f"{label} contains non-literal {dynamic_kind} startup code"
                )
            nested = node.args[0].value
            if dynamic_kind in {"__import__", "import_module"}:
                roots.add(_checked_module_root(nested, label=label))
            elif dynamic_kind == "exec":
                roots.update(
                    _python_startup_import_roots(
                        nested,
                        label=f"{label} exec literal",
                        depth=depth + 1,
                    )
                )
            else:
                raise MutationToolchainError(
                    f"{label} contains unadmitted eval startup code"
                )
    return roots


def _pth_import_roots(prefix: Path, path: Path) -> set[str]:
    raw = _stable_policy_bytes(prefix, path, label="Python .pth startup file")
    try:
        text = raw.decode("utf-8-sig")
    except UnicodeError as exc:
        raise MutationToolchainError(
            f"Python .pth startup file is not strict UTF-8: {path}"
        ) from exc
    roots: set[str] = set()
    for line_number, line in enumerate(text.splitlines(), start=1):
        if line.startswith("#") or not line.strip():
            continue
        if not line.startswith(("import ", "import\t")):
            raise MutationToolchainError(
                "Python .pth path injection is not admitted: "
                f"{path}:{line_number}"
            )
        roots.update(
            _python_startup_import_roots(
                line,
                label=f"{path}:{line_number}",
            )
        )
    return roots


def _loaded_prefix_module_entry(
    *,
    module_name: str,
    prefix: Path,
) -> tuple[dict[str, object], _FileIdentity]:
    module = sys.modules.get(module_name)
    if not isinstance(module, ModuleType):
        raise MutationToolchainError(
            f"Python startup module disappeared after startup: {module_name}"
        )
    specification = getattr(module, "__spec__", None)
    loader = getattr(specification, "loader", None)
    origin = getattr(specification, "origin", None)
    module_file = getattr(module, "__file__", None)
    if not isinstance(origin, str) or not isinstance(module_file, str):
        raise MutationToolchainError(
            f"Python startup module omits its file origin: {module_name}"
        )
    origin_path = _plain_existing_under(
        prefix,
        Path(origin),
        label=f"{module_name} startup module origin",
    )
    file_path = _plain_existing_under(
        prefix,
        Path(module_file),
        label=f"{module_name} startup module file",
    )
    if origin_path != file_path:
        raise MutationToolchainError(
            f"Python startup module contradicts its spec: {module_name}"
        )
    if type(loader) is SourceFileLoader:
        loader_kind = "source"
    elif type(loader) is ExtensionFileLoader:
        loader_kind = "extension"
    else:
        raise MutationToolchainError(
            f"Python startup module has an unadmitted loader: {module_name}"
        )
    identity = _stable_file_identity(
        prefix,
        file_path,
        label=f"{module_name} startup module",
    )
    code_manifest = None
    if loader_kind == "source":
        source = _stable_policy_bytes(
            prefix,
            file_path,
            label=f"{module_name} startup source",
        )
        code_manifest = _source_code_manifest(source, source_path=file_path)
    return (
        {
            "distribution": _STARTUP_DISTRIBUTION,
            "module": module_name,
            "path": identity.path,
            "loader_kind": loader_kind,
            "bytes": identity.bytes,
            "sha256": identity.sha256,
            "code_manifest": code_manifest,
        },
        identity,
    )


def _is_exact_assertion_rewrite_loader(loader: object) -> bool:
    loader_type = type(loader)
    rewrite_module = sys.modules.get("_pytest.assertion.rewrite")
    return (
        loader_type.__module__ == "_pytest.assertion.rewrite"
        and loader_type.__qualname__ == "AssertionRewritingHook"
        and isinstance(rewrite_module, ModuleType)
        and getattr(rewrite_module, "AssertionRewritingHook", None) is loader_type
    )


def _admitted_loader_kind(loader: object, *, label: str) -> str:
    if type(loader) is SourceFileLoader or _is_exact_assertion_rewrite_loader(loader):
        return "source"
    if type(loader) is ExtensionFileLoader:
        return "extension"
    raise MutationToolchainError(f"{label} has an unadmitted loader")


def _prefix_import_root_candidate(
    root: str,
    *,
    prefix: Path,
    search_paths: Sequence[Path],
) -> tuple[Path, str] | None:
    candidates: dict[str, tuple[Path, str]] = {}
    for search_path in search_paths:
        for candidate, loader_kind in (
            (search_path / f"{root}.py", "source"),
            (search_path / root / "__init__.py", "source"),
            *(
                (Path(str(search_path / root) + suffix), "extension")
                for suffix in EXTENSION_SUFFIXES
            ),
        ):
            try:
                resolved = _plain_existing_under(
                    prefix,
                    candidate,
                    label=f"{root} Python startup import root",
                )
            except MutationToolchainError as exc:
                if "is unavailable" in str(exc):
                    continue
                raise
            folded = os.path.normcase(os.fspath(resolved))
            candidates[folded] = (resolved, loader_kind)
    if len(candidates) > 1:
        raise MutationToolchainError(
            f"Python startup import root resolves ambiguously: {root}"
        )
    return next(iter(candidates.values()), None)


def _validate_external_startup_root(root: str) -> None:
    try:
        specification = find_spec(root)
    except (ImportError, AttributeError, ValueError) as exc:
        raise MutationToolchainError(
            f"Python startup import root cannot be resolved: {root}"
        ) from exc
    if specification is None:
        raise MutationToolchainError(
            f"Python startup import root cannot be resolved: {root}"
        )
    loader = specification.loader
    origin = specification.origin
    if origin == "built-in" and loader is BuiltinImporter:
        return
    if origin == "frozen" and loader is FrozenImporter:
        return
    if not isinstance(origin, str):
        raise MutationToolchainError(
            f"Python startup import root has no file identity: {root}"
        )
    if type(loader) not in {SourceFileLoader, ExtensionFileLoader}:
        raise MutationToolchainError(
            f"Python startup import root has an unadmitted loader: {root}"
        )
    try:
        base_prefix = Path(sys.base_prefix).resolve(strict=True)
        _plain_existing_under(
            base_prefix,
            Path(origin),
            label=f"{root} base-runtime startup module",
        )
    except (MutationToolchainError, OSError) as exc:
        raise MutationToolchainError(
            "Python startup import root resolved outside the admitted project or "
            f"base-runtime scopes: {root} -> {origin}"
        ) from exc


def _validate_loaded_root_matches(
    root: str,
    *,
    expected_path: Path,
    expected_loader_kind: str,
) -> None:
    module = sys.modules.get(root)
    if module is None:
        return
    if not isinstance(module, ModuleType):
        raise MutationToolchainError(
            f"Python startup import root is not a module: {root}"
        )
    specification = getattr(module, "__spec__", None)
    loader = getattr(specification, "loader", None)
    origin = getattr(specification, "origin", None)
    module_file = getattr(module, "__file__", None)
    if not isinstance(origin, str) or not isinstance(module_file, str):
        raise MutationToolchainError(
            f"Python startup import root omits its file identity: {root}"
        )
    try:
        origin_path = Path(origin).resolve(strict=True)
        module_path = Path(module_file).resolve(strict=True)
    except OSError as exc:
        raise MutationToolchainError(
            f"Python startup import root file is unavailable: {root}"
        ) from exc
    if origin_path != module_path or module_path != expected_path:
        raise MutationToolchainError(
            "Python startup import root contradicts its static prefix scope: "
            f"{root}"
        )
    if _admitted_loader_kind(loader, label=f"{root} Python startup import root") != (
        expected_loader_kind
    ):
        raise MutationToolchainError(
            f"Python startup import root loader contradicts its file type: {root}"
        )


def _attest_captured_prefix_modules(
    *,
    prefix: Path,
    admitted_module_files: Mapping[str, _FileIdentity],
    admitted_source_paths: Mapping[str, str],
    lru_runtime_context: object | None = None,
) -> tuple[
    frozenset[str],
    frozenset[str],
    frozenset[int],
    tuple[tuple[str, ModuleType], ...],
]:
    for alias, snapshot in sorted(_MODULE_OBJECTS_BEFORE_TOOLCHAIN_IMPORT.items()):
        original, raw_file, _origin, _loader, raw_locations = snapshot
        captured_under_prefix = False
        if isinstance(raw_file, str):
            try:
                Path(raw_file).resolve(strict=True).relative_to(prefix)
            except (OSError, ValueError):
                pass
            else:
                captured_under_prefix = True
        if not captured_under_prefix:
            for raw_location in raw_locations:
                try:
                    Path(raw_location).resolve(strict=True).relative_to(prefix)
                except (OSError, ValueError):
                    continue
                captured_under_prefix = True
                break
        if captured_under_prefix and sys.modules.get(alias) is not original:
            raise MutationToolchainError(
                f"captured prefix module binding changed: {alias}"
            )

    captured: list[tuple[str, ModuleType, Path, str]] = []
    for alias, module in sorted(tuple(sys.modules.items())):
        if not isinstance(module, ModuleType):
            continue
        specification = getattr(module, "__spec__", None)
        module_file = getattr(module, "__file__", None)
        if not isinstance(module_file, str):
            locations = getattr(specification, "submodule_search_locations", None)
            if locations:
                for raw_location in locations:
                    try:
                        Path(raw_location).resolve(strict=True).relative_to(prefix)
                    except (OSError, ValueError):
                        continue
                    raise MutationToolchainError(
                        "captured prefix namespace module has no exact file identity: "
                        f"{alias}"
                    )
            continue
        try:
            file_path = Path(module_file).resolve(strict=True)
            file_path.relative_to(prefix)
        except (OSError, ValueError):
            continue
        origin = getattr(specification, "origin", None)
        loader = getattr(specification, "loader", None)
        if not isinstance(origin, str):
            raise MutationToolchainError(
                f"captured prefix module omits its spec origin: {alias}"
            )
        try:
            origin_path = Path(origin).resolve(strict=True)
        except OSError as exc:
            raise MutationToolchainError(
                f"captured prefix module origin is unavailable: {alias}"
            ) from exc
        if origin_path != file_path:
            raise MutationToolchainError(
                f"captured prefix module contradicts its spec: {alias}"
            )
        loader_kind = _admitted_loader_kind(
            loader,
            label=f"captured prefix module {alias}",
        )
        relative = _relative_under(
            prefix,
            file_path,
            label=f"captured prefix module {alias}",
        )
        expected = admitted_module_files.get(relative.casefold())
        if expected is None or expected.path != relative:
            raise MutationToolchainError(
                "captured prefix module is outside every static reviewed byte "
                f"scope: {alias} -> {relative}"
            )
        actual = _stable_file_identity(
            prefix,
            file_path,
            label=f"captured prefix module {alias}",
        )
        if actual != expected:
            raise MutationToolchainError(
                f"captured prefix module bytes changed: {alias}"
            )
        if loader_kind == "source" and file_path.suffix.casefold() != ".py":
            raise MutationToolchainError(
                f"captured source module is not backed by source: {alias}"
            )
        captured.append((alias, module, file_path, loader_kind))

    rewrite_is_attested = any(
        alias == "_pytest.assertion.rewrite"
        for alias, _module, _path, _kind in captured
    )
    admitted_paths = frozenset(admitted_source_paths)
    admitted_all_paths = frozenset(
        os.path.normcase(
            os.fspath(
                prefix.joinpath(*PurePosixPath(item.path).parts).resolve(strict=True)
            )
        )
        for item in admitted_module_files.values()
    )
    sources: dict[str, bytes] = {}
    admitted_class_ids: set[int] = set()
    for alias, module, file_path, loader_kind in captured:
        if loader_kind != "source":
            continue
        source_key = os.path.normcase(os.fspath(file_path))
        source = sources.get(source_key)
        if source is None:
            source = _stable_policy_bytes(
                prefix,
                file_path,
                label=f"captured prefix module {alias} source",
            )
            sources[source_key] = source
        _, policy = _compile_sealed_source(
            source,
            source_path=file_path,
            assertion_pass_hook=None,
        )
        for value in vars(module).values():
            if inspect.isclass(value) and value.__qualname__ in policy.class_qualnames:
                admitted_class_ids.add(id(value))
    frozen_class_ids = frozenset(admitted_class_ids)
    for alias, module, file_path, loader_kind in captured:
        if loader_kind != "source":
            continue
        variant = _source_loader_variant(
            getattr(module.__spec__, "loader", None),
            module_name=alias,
            rewrite_module_is_attested=rewrite_is_attested,
        )
        source = sources[os.path.normcase(os.fspath(file_path))]
        _verify_loaded_source_code(
            module,
            source=source,
            source_path=file_path,
            variant=variant,
            admitted_source_paths=admitted_paths,
            admitted_module_paths=admitted_all_paths,
            admitted_class_ids=frozen_class_ids,
            require_complete=False,
            lru_runtime_context=lru_runtime_context,
        )
    return (
        admitted_paths,
        admitted_all_paths,
        frozen_class_ids,
        tuple((alias, module) for alias, module, _path, _kind in captured),
    )


def _build_prefix_startup_identity(
    *,
    prefix: Path,
    search_paths: Sequence[Path],
    global_paths: dict[str, tuple[str, str]],
    existing_modules: Sequence[dict[str, object]],
    admitted_module_files: dict[str, _FileIdentity],
    admitted_source_paths: dict[str, str],
    attestation_context: dict[str, object] | None = None,
    lru_runtime_context: object | None = None,
) -> tuple[dict[str, object], list[dict[str, object]], int, int]:
    startup_files: dict[str, _FileIdentity] = {}
    import_roots: set[str] = set()
    for scope in _startup_control_scopes(search_paths):
        folded_name = scope.name.casefold()
        if folded_name in {
            "sitecustomize",
            "sitecustomize.py",
            "usercustomize",
            "usercustomize.py",
        }:
            import_roots.add(folded_name.split(".", 1)[0])
        if folded_name.endswith(".pth"):
            import_roots.update(_pth_import_roots(prefix, scope))
        for identity in _walk_plain_tree(
            prefix,
            scope,
            label="Python startup scope",
        ):
            folded = identity.path.casefold()
            prior = global_paths.get(folded)
            if prior is not None:
                raise MutationToolchainError(
                    "Python startup control file overlaps a distribution scope: "
                    f"{identity.path}"
                )
            _claim_unique_toolchain_path(
                global_paths,
                distribution_name=_STARTUP_DISTRIBUTION,
                relative=identity.path,
            )
            startup_files[identity.path] = identity

    module_entries: list[dict[str, object]] = []
    startup_module_names: list[str] = []
    existing_by_name = {str(item["module"]): item for item in existing_modules}
    for module_name in sorted(import_roots):
        candidate = _prefix_import_root_candidate(
            module_name,
            prefix=prefix,
            search_paths=search_paths,
        )
        if candidate is None:
            _validate_external_startup_root(module_name)
            continue
        module_path, loader_kind = candidate
        _validate_loaded_root_matches(
            module_name,
            expected_path=module_path,
            expected_loader_kind=loader_kind,
        )
        identity = _stable_file_identity(
            prefix,
            module_path,
            label=f"{module_name} Python startup import root",
        )
        code_manifest = None
        if loader_kind == "source":
            code_manifest = _source_code_manifest(
                _stable_policy_bytes(
                    prefix,
                    module_path,
                    label=f"{module_name} Python startup source",
                ),
                source_path=module_path,
            )
        entry: dict[str, object] = {
            "distribution": _STARTUP_DISTRIBUTION,
            "module": module_name,
            "path": identity.path,
            "loader_kind": loader_kind,
            "bytes": identity.bytes,
            "sha256": identity.sha256,
            "code_manifest": code_manifest,
        }
        startup_module_names.append(module_name)
        prior_module = existing_by_name.get(module_name)
        if prior_module is not None:
            if any(
                prior_module[field] != entry[field]
                for field in (
                    "module",
                    "path",
                    "loader_kind",
                    "bytes",
                    "sha256",
                    "code_manifest",
                )
            ):
                raise MutationToolchainError(
                    f"Python startup module conflicts with its distribution: {module_name}"
                )
            continue
        folded = identity.path.casefold()
        prior_path = global_paths.get(folded)
        if prior_path is None:
            _claim_unique_toolchain_path(
                global_paths,
                distribution_name=_STARTUP_DISTRIBUTION,
                relative=identity.path,
            )
            startup_files[identity.path] = identity
            admitted_module_files[folded] = identity
        else:
            prior_name, prior_relative = prior_path
            if prior_relative != identity.path:
                raise MutationToolchainError(
                    "Python startup module path collides case-insensitively: "
                    f"{prior_relative} and {identity.path}"
                )
            entry["distribution"] = prior_name
            expected_identity = admitted_module_files.get(folded)
            if expected_identity is not None and expected_identity != identity:
                raise MutationToolchainError(
                    f"Python startup module bytes conflict with its owner: {module_name}"
                )
            admitted_module_files[folded] = identity
        if loader_kind == "source":
            admitted_source_paths[
                os.path.normcase(os.fspath(module_path.resolve(strict=True)))
            ] = identity.path
        module_entries.append(entry)
        existing_by_name[module_name] = entry

    captured_context = _attest_captured_prefix_modules(
        prefix=prefix,
        admitted_module_files=admitted_module_files,
        admitted_source_paths=admitted_source_paths,
        lru_runtime_context=lru_runtime_context,
    )
    if attestation_context is not None:
        (
            attestation_context["source_paths"],
            attestation_context["module_paths"],
            attestation_context["class_ids"],
            attestation_context["runtime_modules"],
        ) = captured_context

    ordered_files = tuple(sorted(startup_files.values(), key=lambda item: item.path))
    file_payload = [
        {"path": item.path, "bytes": item.bytes, "sha256": item.sha256}
        for item in ordered_files
    ]
    startup_bytes = sum(item.bytes for item in ordered_files)
    unsigned: dict[str, object] = {
        "scope": _STARTUP_SCOPE,
        "import_roots": sorted(import_roots),
        "module_names": startup_module_names,
        "files": file_payload,
        "file_count": len(ordered_files),
        "bytes": startup_bytes,
    }
    startup = {
        **unsigned,
        "sha256": _sha256_bytes(_canonical_json_bytes(unsigned)),
    }
    return startup, module_entries, len(ordered_files), startup_bytes


def _build_test_toolchain_identity(
    *,
    prefix: Path,
    search_paths: Sequence[Path],
    roots: Sequence[str],
    registry: Mapping[str, _DistributionScope],
    host_roots: Sequence[str] = (),
    host_registry: Mapping[str, _DistributionScope] = MappingProxyType({}),
    _attestation_context: dict[str, object] | None = None,
    lru_runtime_context: object | None = None,
) -> dict[str, object]:
    """Build an identity from explicit paths; tests use this with fake installs."""

    if not prefix.is_absolute() or ".." in prefix.parts:
        raise MutationToolchainError(
            "interpreter prefix is not an absolute lexical path"
        )
    lexical_prefix = Path(os.path.abspath(prefix))
    _plain_directory(lexical_prefix, label="interpreter prefix")
    try:
        resolved_prefix = lexical_prefix.resolve(strict=True)
    except OSError as exc:
        raise MutationToolchainError(f"interpreter prefix is unavailable: {exc}") from exc
    if os.path.normcase(os.fspath(resolved_prefix)) != os.path.normcase(
        os.fspath(lexical_prefix)
    ):
        raise MutationToolchainError(
            "interpreter prefix resolves through a link or filesystem alias"
        )
    checked_paths: list[Path] = []
    for raw_path in search_paths:
        checked = _plain_existing_under(
            resolved_prefix,
            raw_path,
            label="distribution search path",
        )
        _plain_directory(checked, label="distribution search path")
        checked_paths.append(checked)
    unique_paths = tuple(sorted(set(checked_paths), key=lambda path: str(path).casefold()))
    if not unique_paths:
        raise MutationToolchainError("no project-prefix distribution search path exists")

    normalized_registry = {
        canonicalize_name(name): scope for name, scope in registry.items()
    }
    if len(normalized_registry) != len(registry):
        raise MutationToolchainError("reviewed distribution names collide canonically")
    normalized_host_registry = {
        canonicalize_name(name): scope for name, scope in host_registry.items()
    }
    if len(normalized_host_registry) != len(host_registry):
        raise MutationToolchainError(
            "reviewed host distribution names collide canonically"
        )
    combined_registry = dict(normalized_registry)
    for name, scope in normalized_host_registry.items():
        prior = combined_registry.get(name)
        if prior is not None and prior != scope:
            raise MutationToolchainError(
                f"reviewed distribution scopes conflict: {name}"
            )
        combined_registry[name] = scope
    index = _distribution_index(
        prefix=resolved_prefix,
        search_paths=unique_paths,
        registry=combined_registry,
    )
    closure = _active_dependency_closure(
        roots=roots,
        index=index,
        registry=combined_registry,
    )
    host_closure = _active_dependency_closure(
        roots=host_roots,
        index=index,
        registry=combined_registry,
    )
    selected_distributions = tuple(sorted(set(closure) | set(host_closure)))

    global_paths: dict[str, tuple[str, str]] = {}
    admitted_module_files: dict[str, _FileIdentity] = {}
    admitted_source_paths: dict[str, str] = {}
    distributions_payload: list[dict[str, object]] = []
    modules_payload: list[dict[str, object]] = []
    total_files = 0
    total_bytes = 0
    for name in selected_distributions:
        distribution = index[name]
        scope = combined_registry[name]
        version = distribution.version
        if not isinstance(version, str) or not version:
            raise MutationToolchainError(f"{name} has an invalid installed version")
        try:
            base = Path(distribution.locate_file(".")).resolve(strict=True)
        except OSError as exc:
            raise MutationToolchainError(
                f"{name} installation root is unavailable"
            ) from exc
        _plain_existing_under(resolved_prefix, base, label=f"{name} installation root")
        _plain_directory(base, label=f"{name} installation root")
        info = _metadata_directory(distribution, prefix=resolved_prefix)

        distribution_files: dict[str, _FileIdentity] = {}
        for relative in (*scope.import_paths,):
            relative = _safe_scope_path(relative, label=f"{name} import path")
            tree = base.joinpath(*PurePosixPath(relative).parts)
            for identity in _walk_plain_tree(
                resolved_prefix,
                tree,
                label=f"{name} import tree",
            ):
                if identity.path in distribution_files:
                    raise MutationToolchainError(
                        f"{name} import scopes overlap at {identity.path}"
                    )
                distribution_files[identity.path] = identity
                admitted_module_files[identity.path.casefold()] = identity
                if PurePosixPath(identity.path).suffix.casefold() == ".py":
                    admitted_source_paths[
                        os.path.normcase(
                            os.fspath(
                                resolved_prefix.joinpath(
                                    *PurePosixPath(identity.path).parts
                                ).resolve(strict=True)
                            )
                        )
                    ] = identity.path
        for identity in _walk_plain_tree(
            resolved_prefix,
            info,
            label=f"{name} metadata tree",
        ):
            if identity.path in distribution_files:
                raise MutationToolchainError(
                    f"{name} metadata overlaps its import scope"
                )
            distribution_files[identity.path] = identity

        for relative in distribution_files:
            _claim_unique_toolchain_path(
                global_paths,
                distribution_name=name,
                relative=relative,
            )
        ordered_files = tuple(
            sorted(distribution_files.values(), key=lambda item: item.path)
        )
        file_payload = [
            {"path": item.path, "bytes": item.bytes, "sha256": item.sha256}
            for item in ordered_files
        ]
        distribution_bytes = sum(item.bytes for item in ordered_files)
        total_files += len(ordered_files)
        total_bytes += distribution_bytes
        if total_files > _MAX_FILES or total_bytes > _MAX_TOTAL_BYTES:
            raise MutationToolchainError("test toolchain exceeds its aggregate limits")
        distributions_payload.append(
            {
                "name": name,
                "version": version,
                "import_paths": sorted(scope.import_paths),
                "dist_info_path": _relative_under(
                    resolved_prefix,
                    info,
                    label=f"{name} metadata",
                ),
                "file_count": len(ordered_files),
                "bytes": distribution_bytes,
                "sha256": _sha256_bytes(_canonical_json_bytes(file_payload)),
            }
        )

        for module_name, relative in scope.source_modules:
            relative = _safe_scope_path(relative, label=f"{module_name} module path")
            expected_path = base.joinpath(*PurePosixPath(relative).parts)
            expected_relative = _relative_under(
                resolved_prefix,
                expected_path,
                label=f"{module_name} module path",
            )
            identity = distribution_files.get(expected_relative)
            if identity is None:
                raise MutationToolchainError(
                    f"{name} does not own the declared module {module_name}"
                )
            modules_payload.append(
                {
                    "distribution": name,
                    "module": module_name,
                    "path": identity.path,
                    "loader_kind": "source",
                    "bytes": identity.bytes,
                    "sha256": identity.sha256,
                    "code_manifest": _source_code_manifest(
                        _stable_policy_bytes(
                            resolved_prefix,
                            expected_path,
                            label=f"{module_name} source module",
                        ),
                        source_path=expected_path,
                    ),
                }
            )
        for module_name, stem in scope.extension_modules:
            modules_payload.append(
                _extension_module_identity(
                    module_name=module_name,
                    stem_path=stem,
                    distribution_name=name,
                    base=base,
                    files=distribution_files,
                    prefix=resolved_prefix,
                )
            )

    startup, startup_modules, startup_file_count, startup_bytes = (
        _build_prefix_startup_identity(
            prefix=resolved_prefix,
            search_paths=unique_paths,
            global_paths=global_paths,
            existing_modules=modules_payload,
            admitted_module_files=admitted_module_files,
            admitted_source_paths=admitted_source_paths,
            attestation_context=_attestation_context,
            lru_runtime_context=lru_runtime_context,
        )
    )
    modules_payload.extend(startup_modules)
    total_files += startup_file_count
    total_bytes += startup_bytes
    if total_files > _MAX_FILES or total_bytes > _MAX_TOTAL_BYTES:
        raise MutationToolchainError("test toolchain exceeds its aggregate limits")

    distributions_payload.sort(key=lambda item: str(item["name"]))
    modules_payload.sort(key=lambda item: str(item["module"]))
    module_manifest = _sha256_bytes(_canonical_json_bytes(modules_payload))
    code_manifest_payload = [
        {
            "module": item["module"],
            "code_manifest": item["code_manifest"],
        }
        for item in modules_payload
    ]
    code_manifest = _sha256_bytes(_canonical_json_bytes(code_manifest_payload))
    unsigned: dict[str, object] = {
        "schema_version": TOOLCHAIN_SCHEMA_VERSION,
        "roots": sorted(canonicalize_name(name) for name in roots),
        "dependency_closure": list(closure),
        "host_roots": sorted(canonicalize_name(name) for name in host_roots),
        "host_dependency_closure": list(host_closure),
        "byte_scope": _BYTE_SCOPE,
        "bytecode_policy": _BYTECODE_POLICY,
        "prefix": str(resolved_prefix),
        "distributions": distributions_payload,
        "startup": startup,
        "modules": modules_payload,
        "module_manifest_sha256": module_manifest,
        "code_manifest_sha256": code_manifest,
        "file_count": total_files,
        "bytes": total_bytes,
    }
    return {
        **unsigned,
        "manifest_sha256": _sha256_bytes(_canonical_json_bytes(unsigned)),
    }


def _distribution_search_paths(prefix: Path) -> tuple[Path, ...]:
    paths: dict[str, Path] = {}
    for raw_entry in sys.path:
        if not raw_entry:
            continue
        raw_path = Path(raw_entry)
        lexical = Path(os.path.abspath(raw_path))
        try:
            resolved = lexical.resolve(strict=True)
        except OSError:
            continue
        try:
            lexical.relative_to(prefix)
            lexical_inside = True
        except ValueError:
            lexical_inside = False
        try:
            resolved.relative_to(prefix)
            resolved_inside = True
        except ValueError:
            resolved_inside = False
        if not lexical_inside and not resolved_inside:
            continue
        if (
            lexical_inside != resolved_inside
            or ".." in raw_path.parts
            or os.path.normcase(os.fspath(lexical))
            != os.path.normcase(os.fspath(resolved))
        ):
            raise MutationToolchainError(
                "sys.path alias crosses the project .venv boundary: "
                f"{lexical} -> {resolved}"
            )
        if not resolved.is_dir():
            raise MutationToolchainError(
                f"project .venv sys.path entry is not a directory: {lexical}"
            )
        folded = os.path.normcase(os.fspath(lexical))
        if folded in paths:
            continue
        paths[folded] = lexical
    return tuple(sorted(paths.values(), key=lambda path: str(path).casefold()))


def _require_isolated_bytecode(prefix: Path) -> None:
    if sys.dont_write_bytecode is not True:
        raise MutationToolchainError(
            "toolchain identity requires bytecode writes to be disabled"
        )
    raw_cache_prefix = sys.pycache_prefix
    if not isinstance(raw_cache_prefix, str) or not raw_cache_prefix:
        raise MutationToolchainError(
            "toolchain identity requires an isolated pycache prefix"
        )
    cache_prefix = Path(raw_cache_prefix)
    if not cache_prefix.is_absolute():
        raise MutationToolchainError("isolated pycache prefix must be absolute")
    resolved_cache = cache_prefix.resolve(strict=False)
    try:
        resolved_cache.relative_to(prefix)
    except ValueError:
        pass
    else:
        raise MutationToolchainError(
            "isolated pycache prefix must remain outside the project .venv"
        )
    try:
        before = cache_prefix.lstat()
    except FileNotFoundError:
        return
    except OSError as exc:
        raise MutationToolchainError(
            f"isolated pycache prefix cannot be inspected: {cache_prefix}: {exc}"
        ) from exc
    if (
        not stat.S_ISDIR(before.st_mode)
        or stat.S_ISLNK(before.st_mode)
        or _is_reparse(before)
    ):
        raise MutationToolchainError(
            "isolated pycache prefix must be absent or an empty plain directory"
        )
    try:
        with os.scandir(cache_prefix) as entries:
            populated = next(entries, None) is not None
        after = cache_prefix.lstat()
    except OSError as exc:
        raise MutationToolchainError(
            f"isolated pycache prefix cannot be inspected: {cache_prefix}: {exc}"
        ) from exc
    if (
        populated
        or stat.S_ISLNK(after.st_mode)
        or _is_reparse(after)
        or _metadata_signature(after) != _metadata_signature(before)
    ):
        raise MutationToolchainError(
            "isolated pycache prefix must be absent or an empty plain directory"
        )


def _verify_or_seal_prefix_runtime(
    prefix: Path,
    *,
    attestation_context: Mapping[str, object],
) -> None:
    raw_modules = attestation_context.get("runtime_modules")
    if not isinstance(raw_modules, tuple) or not all(
        isinstance(item, tuple)
        and len(item) == 2
        and isinstance(item[0], str)
        and isinstance(item[1], ModuleType)
        for item in raw_modules
    ):
        raise MutationToolchainError(
            "complete prefix module attestation context is unavailable"
        )
    modules = tuple(raw_modules)
    if [name for name, _module in modules] != sorted(
        {name for name, _module in modules}
    ):
        raise MutationToolchainError(
            "complete prefix module attestation set is not exact"
        )
    key = os.path.normcase(os.fspath(prefix))
    expected = _RUNTIME_PREFIX_SENTINELS.get(key)
    first_attestation = expected is None
    if expected is None:
        deterministic_key = os.path.normcase(
            os.fspath(_DETERMINISTIC_IMPORT_PREFIX)
        )
        if key == deterministic_key:
            expected = _RuntimePrefixSentinel(
                prefix=_DETERMINISTIC_IMPORT_PREFIX,
                modules=_PREFIX_MODULES_AFTER_DETERMINISTIC_IMPORTS,
            )
        else:
            _RUNTIME_PREFIX_SENTINELS[key] = _RuntimePrefixSentinel(
                prefix=prefix,
                modules=modules,
            )
            return
    if expected.prefix != prefix:
        raise MutationToolchainError("captured prefix module root changed")
    expected_names = [name for name, _module in expected.modules]
    current_names = [name for name, _module in modules]
    if current_names != expected_names:
        missing = sorted(set(expected_names) - set(current_names))
        extra = sorted(set(current_names) - set(expected_names))
        raise MutationToolchainError(
            "captured prefix module set changed: "
            f"missing={missing!r}; unexpected={extra!r}"
        )
    for (name, original), (_current_name, current) in zip(
        expected.modules,
        modules,
        strict=True,
    ):
        if current is not original or sys.modules.get(name) is not original:
            raise MutationToolchainError(
                f"captured prefix module binding changed: {name}"
            )
    if first_attestation:
        _RUNTIME_PREFIX_SENTINELS[key] = expected


def project_test_toolchain_identity(
    project_root: Path,
    *,
    lru_runtime_context: object,
) -> dict[str, object]:
    """Return the active project-venv stack from a live or snapshot checkout.

    A mutation child runs with its current directory and pytest root inside a
    disposable snapshot, while ``sys.prefix`` and ``sys.executable`` still name
    the live checkout's authoritative ``.venv``.  The parent independently
    seals that interpreter path.  This function therefore binds packages to
    the active ``sys.prefix`` and uses ``project_root`` only to verify the live
    checkout form when ``project_root/.venv`` exists.
    """

    try:
        resolved_root = project_root.resolve(strict=True)
        _plain_directory(resolved_root, label="project or snapshot root")
        raw_prefix = Path(sys.prefix)
        if not raw_prefix.is_absolute() or ".." in raw_prefix.parts:
            raise MutationToolchainError(
                "test toolchain interpreter prefix is not an absolute lexical path"
            )
        lexical_prefix = Path(os.path.abspath(raw_prefix))
        _plain_directory(lexical_prefix, label="test toolchain interpreter prefix")
        prefix = lexical_prefix.resolve(strict=True)
        if os.path.normcase(os.fspath(prefix)) != os.path.normcase(
            os.fspath(lexical_prefix)
        ):
            raise MutationToolchainError(
                "test toolchain interpreter prefix resolves through an alias"
            )
        if prefix.name != ".venv":
            raise MutationToolchainError(
                "test toolchain interpreter prefix is not a project .venv"
            )
        expected_executable = (
            prefix / "Scripts" / "python.exe"
            if os.name == "nt"
            else prefix / "bin" / "python"
        )
        if not os.path.samefile(expected_executable, sys.executable):
            raise MutationToolchainError(
                "test toolchain must use the project .venv interpreter"
            )
    except OSError as exc:
        raise MutationToolchainError(
            f"project .venv identity is unavailable: {exc}"
        ) from exc
    live_prefix = resolved_root / ".venv"
    try:
        live_prefix.lstat()
    except FileNotFoundError:
        pass
    except OSError as exc:
        raise MutationToolchainError(
            f"live checkout .venv is unavailable: {exc}"
        ) from exc
    else:
        try:
            _plain_directory(live_prefix, label="live checkout .venv")
            resolved_live_prefix = live_prefix.resolve(strict=True)
            if (
                os.path.normcase(os.fspath(resolved_live_prefix))
                != os.path.normcase(os.fspath(live_prefix))
                or resolved_live_prefix != prefix
            ):
                raise MutationToolchainError(
                    "live checkout .venv differs from the active interpreter prefix"
                )
        except OSError as exc:
            raise MutationToolchainError(
                f"live checkout .venv is unavailable: {exc}"
            ) from exc
    _require_isolated_bytecode(prefix)
    attestation_context: dict[str, object] = {}
    identity = _build_test_toolchain_identity(
        prefix=prefix,
        search_paths=_distribution_search_paths(prefix),
        roots=TEST_TOOLCHAIN_ROOTS,
        registry=_ADMITTED_DISTRIBUTIONS,
        host_roots=HOST_AUXILIARY_ROOTS,
        host_registry=_HOST_AUXILIARY_DISTRIBUTIONS,
        _attestation_context=attestation_context,
        lru_runtime_context=lru_runtime_context,
    )
    _verify_or_seal_prefix_runtime(
        prefix,
        attestation_context=attestation_context,
    )
    return identity


def _validate_source_code_manifest(value: object, *, label: str) -> None:
    if not isinstance(value, dict) or set(value) != {
        "schema_version",
        "object_count",
        "binding_count",
        "variants",
    }:
        raise MutationToolchainError(f"{label} code manifest fields are not exact")
    object_count = value["object_count"]
    binding_count = value["binding_count"]
    variants = value["variants"]
    expected_variants = {
        "raw",
        "pytest_rewrite_disabled",
        "pytest_rewrite_enabled",
    }
    if (
        value["schema_version"] != _CODE_MANIFEST_SCHEMA_VERSION
        or isinstance(object_count, bool)
        or not isinstance(object_count, int)
        or object_count < 0
        or isinstance(binding_count, bool)
        or not isinstance(binding_count, int)
        or binding_count < 0
        or not isinstance(variants, dict)
        or set(variants) != expected_variants
    ):
        raise MutationToolchainError(f"{label} code manifest is invalid")
    for variant_name in sorted(expected_variants):
        variant = variants[variant_name]
        if (
            not isinstance(variant, dict)
            or set(variant) != {
                "object_count",
                "sha256",
                "binding_sha256",
            }
            or variant["object_count"] != object_count
            or not _is_sha256(variant["sha256"])
            or not _is_sha256(variant["binding_sha256"])
        ):
            raise MutationToolchainError(
                f"{label} {variant_name} code manifest is invalid"
            )


def validate_test_toolchain_identity(value: object) -> dict[str, object]:
    """Validate the compact receipt shape and its self-hash."""

    if not isinstance(value, dict):
        raise MutationToolchainError("test toolchain identity is not an object")
    expected_fields = {
        "schema_version",
        "roots",
        "dependency_closure",
        "host_roots",
        "host_dependency_closure",
        "byte_scope",
        "bytecode_policy",
        "prefix",
        "distributions",
        "startup",
        "modules",
        "module_manifest_sha256",
        "code_manifest_sha256",
        "file_count",
        "bytes",
        "manifest_sha256",
    }
    if set(value) != expected_fields:
        raise MutationToolchainError("test toolchain identity fields are not exact")
    if value["schema_version"] != TOOLCHAIN_SCHEMA_VERSION:
        raise MutationToolchainError("test toolchain identity schema is unsupported")
    if value["roots"] != sorted(TEST_TOOLCHAIN_ROOTS):
        raise MutationToolchainError("test toolchain roots are not exact")
    if value["host_roots"] != sorted(HOST_AUXILIARY_ROOTS):
        raise MutationToolchainError("test toolchain host roots are not exact")
    if value["byte_scope"] != _BYTE_SCOPE or value["bytecode_policy"] != _BYTECODE_POLICY:
        raise MutationToolchainError("test toolchain byte policy is not admitted")
    prefix = value["prefix"]
    if not isinstance(prefix, str) or not prefix or not Path(prefix).is_absolute():
        raise MutationToolchainError("test toolchain prefix is invalid")
    closure = value["dependency_closure"]
    if (
        not isinstance(closure, list)
        or closure != sorted(set(closure))
        or not all(isinstance(name, str) and name in _ADMITTED_DISTRIBUTIONS for name in closure)
        or not set(TEST_TOOLCHAIN_ROOTS).issubset(closure)
    ):
        raise MutationToolchainError("test toolchain dependency closure is invalid")
    host_closure = value["host_dependency_closure"]
    combined_registry = {
        **_ADMITTED_DISTRIBUTIONS,
        **_HOST_AUXILIARY_DISTRIBUTIONS,
    }
    if (
        not isinstance(host_closure, list)
        or host_closure != sorted(set(host_closure))
        or not all(
            isinstance(name, str) and name in combined_registry
            for name in host_closure
        )
        or not set(HOST_AUXILIARY_ROOTS).issubset(host_closure)
    ):
        raise MutationToolchainError(
            "test toolchain host dependency closure is invalid"
        )
    selected_distributions = sorted(set(closure) | set(host_closure))
    raw_distributions = value["distributions"]
    if (
        not isinstance(raw_distributions, list)
        or len(raw_distributions) != len(selected_distributions)
    ):
        raise MutationToolchainError("test toolchain distributions are incomplete")
    distribution_names: list[str] = []
    total_files = 0
    total_bytes = 0
    distribution_fields = {
        "name",
        "version",
        "import_paths",
        "dist_info_path",
        "file_count",
        "bytes",
        "sha256",
    }
    for raw_distribution in raw_distributions:
        if not isinstance(raw_distribution, dict) or set(raw_distribution) != distribution_fields:
            raise MutationToolchainError("test toolchain distribution fields are not exact")
        name = raw_distribution["name"]
        if not isinstance(name, str) or name not in selected_distributions:
            raise MutationToolchainError("test toolchain distribution name is invalid")
        distribution_names.append(name)
        if raw_distribution["import_paths"] != sorted(
            combined_registry[name].import_paths
        ):
            raise MutationToolchainError("test toolchain import scope changed")
        info_path = raw_distribution["dist_info_path"]
        if not isinstance(info_path, str):
            raise MutationToolchainError("test toolchain metadata path is invalid")
        _safe_scope_path(info_path, label="test toolchain metadata path")
        if ".dist-info" not in PurePosixPath(info_path).name.casefold():
            raise MutationToolchainError("test toolchain metadata path is not dist-info")
        version = raw_distribution["version"]
        file_count = raw_distribution["file_count"]
        byte_count = raw_distribution["bytes"]
        if (
            not isinstance(version, str)
            or not version
            or isinstance(file_count, bool)
            or not isinstance(file_count, int)
            or file_count <= 0
            or isinstance(byte_count, bool)
            or not isinstance(byte_count, int)
            or byte_count <= 0
            or not _is_sha256(raw_distribution["sha256"])
        ):
            raise MutationToolchainError("test toolchain distribution identity is invalid")
        total_files += file_count
        total_bytes += byte_count
    if distribution_names != selected_distributions:
        raise MutationToolchainError("test toolchain distributions are not sorted and exact")

    raw_startup = value["startup"]
    startup_fields = {
        "scope",
        "import_roots",
        "module_names",
        "files",
        "file_count",
        "bytes",
        "sha256",
    }
    if not isinstance(raw_startup, dict) or set(raw_startup) != startup_fields:
        raise MutationToolchainError("test toolchain startup fields are not exact")
    if raw_startup["scope"] != _STARTUP_SCOPE:
        raise MutationToolchainError("test toolchain startup scope is not admitted")
    import_roots = raw_startup["import_roots"]
    startup_module_names = raw_startup["module_names"]
    if (
        not isinstance(import_roots, list)
        or import_roots != sorted(set(import_roots))
        or not all(
            isinstance(name, str) and name.isidentifier()
            for name in import_roots
        )
        or not isinstance(startup_module_names, list)
        or startup_module_names != sorted(set(startup_module_names))
        or not all(
            isinstance(name, str)
            and all(part.isidentifier() for part in name.split("."))
            for name in startup_module_names
        )
    ):
        raise MutationToolchainError("test toolchain startup names are invalid")
    raw_startup_files = raw_startup["files"]
    startup_file_paths: list[str] = []
    startup_file_bytes = 0
    if not isinstance(raw_startup_files, list):
        raise MutationToolchainError("test toolchain startup files are invalid")
    for raw_file in raw_startup_files:
        if not isinstance(raw_file, dict) or set(raw_file) != {
            "path",
            "bytes",
            "sha256",
        }:
            raise MutationToolchainError(
                "test toolchain startup file fields are not exact"
            )
        path = raw_file["path"]
        byte_count = raw_file["bytes"]
        if (
            not isinstance(path, str)
            or isinstance(byte_count, bool)
            or not isinstance(byte_count, int)
            or byte_count <= 0
            or byte_count > _MAX_FILE_BYTES
            or not _is_sha256(raw_file["sha256"])
        ):
            raise MutationToolchainError(
                "test toolchain startup file identity is invalid"
            )
        _safe_scope_path(path, label="test toolchain startup file path")
        startup_file_paths.append(path)
        startup_file_bytes += byte_count
    if startup_file_paths != sorted(set(startup_file_paths)):
        raise MutationToolchainError(
            "test toolchain startup files are not unique and sorted"
        )
    if (
        raw_startup["file_count"] != len(raw_startup_files)
        or raw_startup["bytes"] != startup_file_bytes
    ):
        raise MutationToolchainError(
            "test toolchain startup aggregate counts are inconsistent"
        )
    unsigned_startup = dict(raw_startup)
    startup_sha256 = unsigned_startup.pop("sha256")
    if not _is_sha256(startup_sha256) or startup_sha256 != _sha256_bytes(
        _canonical_json_bytes(unsigned_startup)
    ):
        raise MutationToolchainError("test toolchain startup digest is invalid")
    total_files += len(raw_startup_files)
    total_bytes += startup_file_bytes

    raw_modules = value["modules"]
    if not isinstance(raw_modules, list) or not raw_modules:
        raise MutationToolchainError("test toolchain module identities are empty")
    module_fields = {
        "distribution",
        "module",
        "path",
        "loader_kind",
        "bytes",
        "sha256",
        "code_manifest",
    }
    module_names: list[str] = []
    for raw_module in raw_modules:
        if not isinstance(raw_module, dict) or set(raw_module) != module_fields:
            raise MutationToolchainError("test toolchain module fields are not exact")
        distribution_name = raw_module["distribution"]
        module_name = raw_module["module"]
        module_path = raw_module["path"]
        byte_count = raw_module["bytes"]
        if (
            not isinstance(distribution_name, str)
            or distribution_name
            not in {*selected_distributions, _STARTUP_DISTRIBUTION}
            or not isinstance(module_name, str)
            or not module_name
            or not isinstance(module_path, str)
            or raw_module["loader_kind"] not in {"source", "extension"}
            or isinstance(byte_count, bool)
            or not isinstance(byte_count, int)
            or byte_count <= 0
            or not _is_sha256(raw_module["sha256"])
        ):
            raise MutationToolchainError("test toolchain module identity is invalid")
        _safe_scope_path(module_path, label="test toolchain module path")
        if raw_module["loader_kind"] == "source":
            _validate_source_code_manifest(
                raw_module["code_manifest"],
                label=f"{module_name} source module",
            )
        elif raw_module["code_manifest"] is not None:
            raise MutationToolchainError(
                "extension module must not carry a Python code manifest"
            )
        if (
            distribution_name == _STARTUP_DISTRIBUTION
            and module_path not in startup_file_paths
        ):
            raise MutationToolchainError(
                "Python startup module is absent from the startup byte scope"
            )
        module_names.append(module_name)
    if module_names != sorted(set(module_names)):
        raise MutationToolchainError("test toolchain module identities are not unique and sorted")
    if not set(startup_module_names).issubset(module_names):
        raise MutationToolchainError(
            "test toolchain startup module manifest is incomplete"
        )
    if any(
        raw_module["distribution"] == _STARTUP_DISTRIBUTION
        and raw_module["module"] not in startup_module_names
        for raw_module in raw_modules
    ):
        raise MutationToolchainError(
            "test toolchain module has an undeclared startup owner"
        )
    expected_module_manifest = _sha256_bytes(_canonical_json_bytes(raw_modules))
    if value["module_manifest_sha256"] != expected_module_manifest:
        raise MutationToolchainError("test toolchain module manifest digest is invalid")
    expected_code_manifest = _sha256_bytes(
        _canonical_json_bytes(
            [
                {
                    "module": raw_module["module"],
                    "code_manifest": raw_module["code_manifest"],
                }
                for raw_module in raw_modules
            ]
        )
    )
    if value["code_manifest_sha256"] != expected_code_manifest:
        raise MutationToolchainError("test toolchain code manifest digest is invalid")
    if value["file_count"] != total_files or value["bytes"] != total_bytes:
        raise MutationToolchainError("test toolchain aggregate counts are inconsistent")
    if total_files > _MAX_FILES or total_bytes > _MAX_TOTAL_BYTES:
        raise MutationToolchainError("test toolchain aggregate limits are exceeded")
    unsigned = dict(value)
    manifest = unsigned.pop("manifest_sha256")
    if not _is_sha256(manifest) or manifest != _sha256_bytes(
        _canonical_json_bytes(unsigned)
    ):
        raise MutationToolchainError("test toolchain manifest digest is invalid")
    return value


def _source_loader_variant(
    loader: object,
    *,
    module_name: str,
    rewrite_module_is_attested: bool,
) -> str:
    if type(loader) is SourceFileLoader:
        return "raw"
    loader_type = type(loader)
    rewrite_module = sys.modules.get("_pytest.assertion.rewrite")
    exact_rewrite_loader = (
        loader_type.__module__ == "_pytest.assertion.rewrite"
        and loader_type.__qualname__ == "AssertionRewritingHook"
        and isinstance(rewrite_module, ModuleType)
        and getattr(rewrite_module, "AssertionRewritingHook", None) is loader_type
        and rewrite_module_is_attested
    )
    if not exact_rewrite_loader:
        raise MutationToolchainError(
            f"test toolchain module has the wrong source loader: {module_name}"
        )
    config = getattr(loader, "config", None)
    getini = getattr(config, "getini", None)
    if not callable(getini):
        raise MutationToolchainError(
            f"pytest rewrite loader omits its assertion-pass policy: {module_name}"
        )
    try:
        assertion_pass_hook = getini("enable_assertion_pass_hook")
    except Exception as exc:
        raise MutationToolchainError(
            f"pytest rewrite loader cannot report its assertion-pass policy: {module_name}"
        ) from exc
    if type(assertion_pass_hook) is not bool:
        raise MutationToolchainError(
            f"pytest rewrite loader has an invalid assertion-pass policy: {module_name}"
        )
    return (
        "pytest_rewrite_enabled"
        if assertion_pass_hook
        else "pytest_rewrite_disabled"
    )


def loaded_test_toolchain_attestation(
    value: object,
    *,
    lru_runtime_context: object,
) -> dict[str, object]:
    """Prove that declared toolchain modules resolve to the sealed file bytes."""

    identity = validate_test_toolchain_identity(value)
    prefix = Path(str(identity["prefix"])).resolve(strict=True)
    attestation_context: dict[str, object] = {}
    rebuilt = _build_test_toolchain_identity(
        prefix=prefix,
        search_paths=_distribution_search_paths(prefix),
        roots=TEST_TOOLCHAIN_ROOTS,
        registry=_ADMITTED_DISTRIBUTIONS,
        host_roots=HOST_AUXILIARY_ROOTS,
        host_registry=_HOST_AUXILIARY_DISTRIBUTIONS,
        _attestation_context=attestation_context,
        lru_runtime_context=lru_runtime_context,
    )
    if rebuilt != identity:
        raise MutationToolchainError(
            "live test toolchain identity changed before loaded attestation"
        )
    admitted_source_paths = attestation_context.get("source_paths")
    admitted_module_paths = attestation_context.get("module_paths")
    admitted_class_ids = attestation_context.get("class_ids")
    if not all(
        isinstance(item, frozenset)
        for item in (
            admitted_source_paths,
            admitted_module_paths,
            admitted_class_ids,
        )
    ):
        raise MutationToolchainError(
            "captured test toolchain attestation context is incomplete"
        )
    _verify_or_seal_prefix_runtime(
        prefix,
        attestation_context=attestation_context,
    )
    observed: list[dict[str, object]] = []
    for expected in identity["modules"]:
        assert isinstance(expected, dict)
        module_name = str(expected["module"])
        try:
            module = import_module(module_name)
        except Exception as exc:
            raise MutationToolchainError(
                f"test toolchain module cannot be imported: {module_name}"
            ) from exc
        if not isinstance(module, ModuleType):
            raise MutationToolchainError(
                f"test toolchain import is not a module: {module_name}"
            )
        specification = getattr(module, "__spec__", None)
        loader = getattr(specification, "loader", None)
        origin = getattr(specification, "origin", None)
        module_file = getattr(module, "__file__", None)
        if not isinstance(origin, str) or not isinstance(module_file, str):
            raise MutationToolchainError(
                f"test toolchain module omits its file origin: {module_name}"
            )
        try:
            origin_path = Path(origin).resolve(strict=True)
            file_path = Path(module_file).resolve(strict=True)
        except OSError as exc:
            raise MutationToolchainError(
                f"test toolchain module origin is unavailable: {module_name}"
            ) from exc
        if origin_path != file_path:
            raise MutationToolchainError(
                f"test toolchain module contradicts its spec: {module_name}"
            )
        expected_path = prefix.joinpath(*PurePosixPath(str(expected["path"])).parts)
        if file_path != expected_path.resolve(strict=True):
            raise MutationToolchainError(
                f"test toolchain module resolved outside its sealed distribution: {module_name}"
            )
        loader_kind = expected["loader_kind"]
        if loader_kind == "source":
            variant = _source_loader_variant(
                loader,
                module_name=module_name,
                rewrite_module_is_attested=any(
                    item["module"] == "_pytest.assertion.rewrite"
                    for item in observed
                ),
            )
        if loader_kind == "extension" and type(loader) is not ExtensionFileLoader:
            raise MutationToolchainError(
                f"test toolchain module has the wrong extension loader: {module_name}"
            )
        actual = _stable_file_identity(prefix, file_path, label=f"{module_name} module")
        if actual.bytes != expected["bytes"] or actual.sha256 != expected["sha256"]:
            raise MutationToolchainError(
                f"test toolchain module bytes changed: {module_name}"
            )
        if loader_kind == "source":
            source = _stable_policy_bytes(
                prefix,
                file_path,
                label=f"{module_name} loaded source",
            )
            _verify_loaded_source_code(
                module,
                source=source,
                source_path=file_path,
                variant=variant,
                expected_manifest=expected["code_manifest"],
                admitted_source_paths=admitted_source_paths,
                admitted_module_paths=admitted_module_paths,
                admitted_class_ids=admitted_class_ids,
                require_complete=(
                    module_name not in _ADMITTED_RUNTIME_CONDITIONAL_MODULES
                ),
                lru_runtime_context=lru_runtime_context,
            )
        observed.append(dict(expected))
    observed.sort(key=lambda item: str(item["module"]))
    observed_digest = _sha256_bytes(_canonical_json_bytes(observed))
    if observed_digest != identity["module_manifest_sha256"]:
        raise MutationToolchainError("loaded test toolchain module manifest changed")
    normalized_lru = _attest_eager_lru_wrappers_empty(
        lru_runtime_context
    )
    return {
        "schema_version": TOOLCHAIN_SCHEMA_VERSION,
        "manifest_sha256": identity["manifest_sha256"],
        "module_manifest_sha256": observed_digest,
        "code_manifest_sha256": identity["code_manifest_sha256"],
        "module_count": len(observed),
        "code_object_count": sum(
            int(item["code_manifest"]["object_count"])
            for item in observed
            if item["loader_kind"] == "source"
        ),
        "all_modules_match": True,
        "all_captured_modules_match": True,
        **normalized_lru,
    }


